INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f104ba-5eab-4fb7-bae2-b830f50bc7a4', '偶書五首 五', '偶书五首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["新店南原後夜程，黃河風浪信難平。","渡頭楊柳知人意，爲惹官船莫放行。"]', '["新店南原後夜程，黄河风浪信难平。","渡头楊柳知人意，爲惹官船莫放行。"]', '诗', 'shi', '', NULL, '偶書五首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974d5acc-2ebd-487b-a20b-927e9c962f00', '喜山鵲初歸三首 一', '喜山鵲初归三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["翠衿紅觜便知機，久避重羅穩處飛。","只爲從來偏護惜，窗前今賀主人歸。"]', '["翠衿紅觜便知機，久避重羅穩处飞。","只爲從来偏護惜，窗前今賀主人归。"]', '诗', 'shi', '', NULL, '喜山鵲初歸三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('498ed5e4-b26a-469b-a51e-4d474fc1252e', '喜山鵲初歸三首 二', '喜山鵲初归三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["山中只是惜珍禽，語不分明識爾心。","若使解言天下事，燕臺今築幾千金。"]', '["山中只是惜珍禽，語不分明識爾心。","若使解言天下事，燕台今築幾千金。"]', '诗', 'shi', '', NULL, '喜山鵲初歸三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b84bfbf-dee5-4fa6-83ae-ef185aa0577e', '喜山鵲初歸三首 三', '喜山鵲初归三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["阻他羅網到柴扉，不奈偷倉雀轉肥。","賴爾林塘添景趣，剩留山果引教歸。"]', '["阻他羅網到柴扉，不奈偷倉雀轉肥。","賴爾林塘添景趣，剩留山果引教归。"]', '诗', 'shi', '', NULL, '喜山鵲初歸三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc4987b-3cac-48cf-98a0-373f32939e9b', '虞鄉北原', '虞乡北原', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["澤北邨貧煙火獰，稚田冬旱倩牛耕。","老人惆悵逢人訴，開盡黃花麥未金。"]', '["澤北邨貧煙火獰，稚田冬旱倩牛耕。","老人惆悵逢人訴，开尽黄花麦未金。"]', '诗', 'shi', '', NULL, '虞鄉北原 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f68c9f6-23cf-41e2-9d60-db076b223392', '洛中三首 一', '洛中三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["秋風團扇未驚心，笑看妝臺落葉侵。","繡鳯不教金縷暗，青樓何處有寒砧。"]', '["秋风團扇未驚心，笑看妝台落葉侵。","繡鳯不教金縷暗，青楼何处有寒砧。"]', '诗', 'shi', '', NULL, '洛中三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7f2b10-12cc-4f06-8a4b-913b8f4dd3ac', '洛中三首 二', '洛中三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不用頻嗟世路難，浮生各自繫悲懽。","風霜一夜添羇思，羅綺誰家待早寒。"]', '["不用頻嗟世路难，浮生各自繫悲懽。","风霜一夜添羇思，羅綺誰家待早寒。"]', '诗', 'shi', '', NULL, '洛中三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c388ab65-833b-4b5d-9d4c-69a9dba6ab0e', '洛中三首 三', '洛中三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["燕巢空後誰相伴，鴛被縫來不忍薰。","薄命敢辭長滴淚，倡家未必肯留君。"]', '["燕巢空後誰相伴，鴛被縫来不忍薰。","薄命敢辞长滴泪，倡家未必肯留君。"]', '诗', 'shi', '', NULL, '洛中三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3713db20-ade8-4870-a3b0-a4dcc2eb0b45', '寓筆', '寓笔', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["年年鑷鬢到花飄，依舊花繁鬢易凋。","撩亂一塲人更恨，春風誰道勝輕飆。"]', '["年年鑷鬢到花飄，依旧花繁鬢易凋。","撩亂一塲人更恨，春风誰道勝轻飆。"]', '诗', 'shi', '', NULL, '寓筆 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3590d458-2afb-4d5e-95f6-12d45efa7399', '戲題試衫', '戲題試衫', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["朝班盡說人宜紫，洞府應無鶴着緋。","從此玉皇須破例，染霞裁賜地仙衣。"]', '["朝班尽说人宜紫，洞府應無鹤着緋。","從此玉皇須破例，染霞裁賜地仙衣。"]', '诗', 'shi', '', NULL, '戲題試衫 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4a014d-a068-49c3-afc9-2efafdc27aa6', '汴柳半枯因悲柳中隱', '汴柳半枯因悲柳中隐', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["行人莫歎前朝樹，已占河堤幾百春。","惆悵題詩柳中隱，柳衰猶在自無身。"]', '["行人莫歎前朝樹，已占河堤幾百春。","惆悵題诗柳中隐，柳衰猶在自無身。"]', '诗', 'shi', '', NULL, '汴柳半枯因悲柳中隱 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75ddcd58-c79c-4b3a-9ca4-7e84c1cfc267', '上方', '上方', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["花落更同悲木落，鶯聲相續即蟬聲。","榮枯了得無多事，只是閑人漫繫情。"]', '["花落更同悲木落，鶯声相續即蟬声。","榮枯了得無多事，只是闲人漫繫情。"]', '诗', 'shi', '', NULL, '上方 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0092ded3-c8f1-48bd-a28e-4d1c40081910', '寄王贊學', '寄王贊学', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["黃卷不關兼濟業，青山自保老閑身。","一行萬里纖塵靜，可要張儀更入秦。"]', '["黄卷不关兼濟業，青山自保老闲身。","一行万里纖塵静，可要張儀更入秦。"]', '诗', 'shi', '', NULL, '寄王贊學 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237c217b-edba-4bce-964c-d48c994b2188', '新節', '新節', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["轉悲新歲重於山，不似輕鷗肯復還。","朱紱縱教金印換，青雲未勝白頭閑。"]', '["轉悲新歲重於山，不似轻鷗肯复還。","朱紱縱教金印換，青云未勝白头闲。"]', '诗', 'shi', '', NULL, '新節 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61cd8313-81aa-4d92-813d-06250a628bff', '自河西歸山二首 一', '自河西归山二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["一水悠悠一葉危，往來長恨阻歸期。","鄉關不是無華表，自爲多驚獨上遲。"]', '["一水悠悠一葉危，往来长恨阻归期。","乡关不是無华表，自爲多驚独上遲。"]', '诗', 'shi', '', NULL, '自河西歸山二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819bc650-9daf-4dbb-9950-dafd26e7f2f1', '自河西歸山二首 二', '自河西归山二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["水闊風驚去路危，孤舟欲上更遲遲。","鶴羣長擾三珠樹，不借人間一隻騎。"]', '["水闊风驚去路危，孤舟欲上更遲遲。","鹤羣长擾三珠樹，不借人间一隻騎。"]', '诗', 'shi', '', NULL, '自河西歸山二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d1fa49-b5db-494a-bfd5-8ad54f431464', '王官二首 一', '王官二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["風荷似醉和花舞，沙鳥無情伴客閑。","總是此中皆有恨，更堪微雨半遮山。"]', '["风荷似醉和花舞，沙鸟無情伴客闲。","總是此中皆有恨，更堪微雨半遮山。"]', '诗', 'shi', '', NULL, '王官二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ca2498-6dca-448f-ac44-a6972689d266', '王官二首 二', '王官二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["荷塘煙罩小齋虛，景物皆宜入畫圖。","盡日無人只高臥，一雙白鳥隔紗廚。"]', '["荷塘煙罩小斋虛，景物皆宜入畫圖。","尽日無人只高臥，一雙白鸟隔紗廚。"]', '诗', 'shi', '', NULL, '王官二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9520446-4980-44ee-904f-4a5425f355a2', '賀翰林侍郎二首 一', '賀翰林侍郎二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["太白東歸鶴背吟，鏡湖空在酒船沈。","今朝忽見銀臺事，早晚重徵入翰林。"]', '["太白东归鹤背吟，镜湖空在酒船沈。","今朝忽见銀台事，早晚重徵入翰林。"]', '诗', 'shi', '', NULL, '賀翰林侍郎二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('124914f9-eabf-4d4c-8723-e771ac1478bc', '賀翰林侍郎二首 二', '賀翰林侍郎二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["玉版徵書洞裏看，沈羲新拜侍郎官。","文星喜氣連台曜，聖主方知四海安。"]', '["玉版徵书洞裏看，沈羲新拜侍郎官。","文星喜氣連台曜，聖主方知四海安。"]', '诗', 'shi', '', NULL, '賀翰林侍郎二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0403ebdb-e3c8-43bf-95f6-45a48d85bc4a', '寄王十四舍人', '寄王十四舍人', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["幾年汶上約同遊，擬爲蓮峰別置樓。","今日鳳皇池畔客，五千仞雪不回頭。"]', '["幾年汶上約同游，擬爲蓮峰別置楼。","今日鳳皇池畔客，五千仞雪不回头。"]', '诗', 'shi', '', NULL, '寄王十四舍人 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dd221c-b53c-4d3b-8414-61edbaa93ab8', '綸閣有感', '綸閣有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["風濤曾阻化鱗來，誰料蓬瀛路却開。","欲去遲遲還自笑，狂才應不是仙才。"]', '["风濤曾阻化鱗来，誰料蓬瀛路却开。","欲去遲遲還自笑，狂才應不是仙才。"]', '诗', 'shi', '', NULL, '綸閣有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c2f0e7-0940-4496-a686-ef586df5e2ad', '狂題十八首 一', '狂題十八首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["莫恨艱危日日多，時情其奈倖門何。","貔貅睡穩蛟龍渴，猶把燒殘朽鐵磨。"]', '["莫恨艱危日日多，时情其奈倖门何。","貔貅睡穩蛟龙渴，猶把燒殘朽鐵磨。"]', '诗', 'shi', '', NULL, '狂題十八首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e76ffa2-243e-40dc-a0ea-e174f97aa97e', '狂題十八首 二', '狂題十八首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["別鶴淒涼指法存，戴逵能耻近王門。","世間第一風流事，借得王公玉枕痕。"]', '["別鹤淒涼指法存，戴逵能耻近王门。","世间第一风流事，借得王公玉枕痕。"]', '诗', 'shi', '', NULL, '狂題十八首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('327c574e-005d-4b9e-94cd-9411f8e8b68a', '狂題十八首 三', '狂題十八首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["交疎自古戒言深，肝膽徒傾致鑠金。","不是史遷書與說，誰知孤負李陵心。"]', '["交疎自古戒言深，肝膽徒傾致鑠金。","不是史遷书與说，誰知孤負李陵心。"]', '诗', 'shi', '', NULL, '狂題十八首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91bac00e-9fb4-470a-90f9-285f027ec696', '狂題十八首 四', '狂題十八首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["南華落筆似荒唐，若肯經綸亦不狂。","偶作客星侵帝座，却應虛薄是嚴光。"]', '["南华落笔似荒唐，若肯經綸亦不狂。","偶作客星侵帝座，却應虛薄是嚴光。"]', '诗', 'shi', '', NULL, '狂題十八首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d4e897-048c-486a-8c31-b259aa3a3e72', '狂題十八首 五', '狂題十八首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不勞世路更相猜，忍到須休惜得材。","幾度懶乘風水便，抝船折舵恐難回。"]', '["不勞世路更相猜，忍到須休惜得材。","幾度懶乘风水便，抝船折舵恐难回。"]', '诗', 'shi', '', NULL, '狂題十八首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e45c6f-f636-4235-a942-1bbd7c6cc264', '狂題十八首 六', '狂題十八首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["由來相愛只詩僧，怪石長松自得朋。","却怕他生還識字，依前日下作孤燈。"]', '["由来相愛只诗僧，怪石长松自得朋。","却怕他生還識字，依前日下作孤灯。"]', '诗', 'shi', '', NULL, '狂題十八首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b794d29b-4f8e-4a4b-847c-4371fdf15c04', '狂題十八首 七', '狂題十八首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["老禪乘仗莫過身，遠岫孤雲見亦頻。","應是佛邊猶怕鬧，信緣須作且閑人。"]', '["老禪乘仗莫過身，远岫孤云见亦頻。","應是佛邊猶怕鬧，信緣須作且闲人。"]', '诗', 'shi', '', NULL, '狂題十八首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1088f8-ad3f-4949-abb2-5ef9d7cca51e', '狂題十八首 八', '狂題十八首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["止竟閑人不愛閑，只偷無事閉柴關。","轟霆攪破蛟龍窟，也被狂風卷出山。"]', '["止竟闲人不愛闲，只偷無事閉柴关。","轟霆攪破蛟龙窟，也被狂风卷出山。"]', '诗', 'shi', '', NULL, '狂題十八首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6402c50c-a59c-4c76-aefb-f14e9be09d6b', '狂題十八首 九', '狂題十八首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["地下修文著作郎，生前飢處倒空墻。","何如神爽騎星去，猶自研幾助玉皇。"]', '["地下修文著作郎，生前飢处倒空墻。","何如神爽騎星去，猶自研幾助玉皇。"]', '诗', 'shi', '', NULL, '狂題十八首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ef590f-4cfe-43b9-b7af-301961889799', '狂題十八首 十', '狂題十八首 十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雨洗芭蕉葉上詩，獨來憑檻晚晴時。","故園雖恨風荷膩，新句閑題亦滿池。"]', '["雨洗芭蕉葉上诗，独来憑檻晚晴时。","故园雖恨风荷膩，新句闲題亦满池。"]', '诗', 'shi', '', NULL, '狂題十八首 十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8efe24b3-cd66-4fd4-8925-832d6547bf14', '狂題十八首 十一', '狂題十八首 十一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["初時拄杖向鄰村，漸到清明亦杜門。","三十年來辭病表，今朝臥病感皇恩。"]', '["初时拄杖向鄰村，漸到清明亦杜门。","三十年来辞病表，今朝臥病感皇恩。"]', '诗', 'shi', '', NULL, '狂題十八首 十一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71dac7b3-b68c-42fb-8304-72647303dfe2', '狂題十八首 十二', '狂題十八首 十二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["來時雖恨失青氊，自見芭蕉幾十篇。","應是阿劉還宿債，剩拚才思折供錢。"]', '["来时雖恨失青氊，自见芭蕉幾十篇。","應是阿劉還宿債，剩拚才思折供錢。"]', '诗', 'shi', '', NULL, '狂題十八首 十二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('679071df-6555-4827-ad61-c1942fea2fc5', '狂題十八首 十三', '狂題十八首 十三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["芭蕉叢畔碧嬋娟，免更悠悠擾蜀川。","應到去時題不盡，不勞分寄校書牋。"]', '["芭蕉叢畔碧嬋娟，免更悠悠擾蜀川。","應到去时題不尽，不勞分寄校书牋。"]', '诗', 'shi', '', NULL, '狂題十八首 十三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3bf849-ab1b-42c6-8874-96a096965024', '狂題十八首 十四', '狂題十八首 十四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自傷衰病漸難平，永夜禪牀雨滴聲。","聞道虎瘡仍帶鏃，吼來和痛亦橫行。"]', '["自傷衰病漸难平，永夜禪牀雨滴声。","闻道虎瘡仍带鏃，吼来和痛亦橫行。"]', '诗', 'shi', '', NULL, '狂題十八首 十四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2926ddf8-9d99-4c0a-87c9-56db60e5cb75', '狂題十八首 十五', '狂題十八首 十五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昨日流鶯今日蟬，起來又是夕陽天。","六龍飛轡長相窘，更忍乘危自着鞭。"]', '["昨日流鶯今日蟬，起来又是夕陽天。","六龙飞轡长相窘，更忍乘危自着鞭。"]', '诗', 'shi', '', NULL, '狂題十八首 十五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e14e835-02de-42ae-8626-2d1a0bdd7d41', '狂題十八首 十六', '狂題十八首 十六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["有是有非還有慮，無心無跡亦無猜。","不平便激風波險，莫向安時稔禍胎。"]', '["有是有非還有慮，無心無跡亦無猜。","不平便激风波險，莫向安时稔禍胎。"]', '诗', 'shi', '', NULL, '狂題十八首 十六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a72b9d-81cf-4a87-8b09-8f6ce0d2146b', '狂題十八首 十七', '狂題十八首 十七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["十年三署讓官頻，認得無才又索身。","莫道太行同一路，大都安穩屬閑人。"]', '["十年三署讓官頻，認得無才又索身。","莫道太行同一路，大都安穩屬闲人。"]', '诗', 'shi', '', NULL, '狂題十八首 十七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a61020-f4a2-4f4c-8b8d-0143d22c94da', '狂題十八首 十八', '狂題十八首 十八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["曾聞劫火到蓬壺，縮盡鼇頭海亦枯。","今日家山同此恨，人歸未得鶴歸無。"]', '["曾闻劫火到蓬壺，縮尽鼇头海亦枯。","今日家山同此恨，人归未得鹤归無。"]', '诗', 'shi', '', NULL, '狂題十八首 十八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75af1049-35a3-42ae-bffd-90089bf3ef27', '遊仙二首 一', '游仙二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["蛾眉新畫覺嬋娟，鬬走將花阿母邊。","仙曲教成慵不理，玉階相簇打金錢。"]', '["蛾眉新畫覺嬋娟，鬬走將花阿母邊。","仙曲教成慵不理，玉階相簇打金錢。"]', '诗', 'shi', '', NULL, '遊仙二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e36541b-bb38-416a-8d20-8cf76dbad6e5', '遊仙二首 二', '游仙二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["劉郎相約事難諧，雨散雲飛自此乖。","月姊殷勤留不住，碧空遺下水精釵。"]', '["劉郎相約事难諧，雨散云飞自此乖。","月姊殷勤留不住，碧空遺下水精釵。"]', '诗', 'shi', '', NULL, '遊仙二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266f1bd0-a44c-4bbf-b64d-d626e5ebe52e', '漫書五首 一', '漫书五首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["長擬求閑未得閑，又勞行役出秦關。","逢人漸覺鄉音異，却恨鶯聲似故山。"]', '["长擬求闲未得闲，又勞行役出秦关。","逢人漸覺乡音異，却恨鶯声似故山。"]', '诗', 'shi', '', NULL, '漫書五首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e45696-6548-47cf-8324-83cda0fa7de0', '漫書五首 二', '漫书五首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["溪邊隨事有桑麻，盡日山程十數家。","莫怪行人頻悵望，杜鵑不是故鄉花。"]', '["溪邊隨事有桑麻，尽日山程十數家。","莫怪行人頻悵望，杜鵑不是故乡花。"]', '诗', 'shi', '', NULL, '漫書五首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3be046-ac42-425a-8e9f-def1a53542b3', '漫書五首 三', '漫书五首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["海上昔聞麋愛鶴，山中今日鹿憎龜。","愛憎止竟須關分，莫把微才望所知。"]', '["海上昔闻麋愛鹤，山中今日鹿憎龟。","愛憎止竟須关分，莫把微才望所知。"]', '诗', 'shi', '', NULL, '漫書五首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4446a7e3-637f-4903-8e8a-ea3b5dfc335c', '漫書五首 四', '漫书五首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["世路快心無好事，恩門嘉話合書紳。","神藏鬼伏能千變，亦勝忘機避要津。"]', '["世路快心無好事，恩门嘉話合书紳。","神藏鬼伏能千变，亦勝忘機避要津。"]', '诗', 'shi', '', NULL, '漫書五首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44c413b-f039-4703-b1f5-dc73907e9c36', '漫書五首 五', '漫书五首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["四翁識勢保安閑，須爲生靈暫出山。","一種老人能算度，磻溪心跡愧商顏。"]', '["四翁識勢保安闲，須爲生靈暫出山。","一種老人能算度，磻溪心跡愧商顏。"]', '诗', 'shi', '', NULL, '漫書五首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1be2bb-ab0e-4074-8937-241b7bef8525', '偶詩五首 一', '偶诗五首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閑韻雖高不衒才，偶拋猨鳥乍歸來。","夕陽照箇新紅葉，似要題詩落硯臺。"]', '["闲韻雖高不衒才，偶拋猨鸟乍归来。","夕陽照箇新紅葉，似要題诗落硯台。"]', '诗', 'shi', '', NULL, '偶詩五首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde32250-e1f6-407d-bd49-a2ec23eabb8b', '偶詩五首 二', '偶诗五首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["芙蓉騷客空留怨，芍藥詩家只寄情。","誰似天才李山甫，牡丹屬思亦縱橫。"]', '["芙蓉騷客空留怨，芍藥诗家只寄情。","誰似天才李山甫，牡丹屬思亦縱橫。"]', '诗', 'shi', '', NULL, '偶詩五首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7fe5386-9eb3-4e4a-8b6c-ee05be62ace0', '偶詩五首 三', '偶诗五首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["賢豪出處盡沉吟，白日高懸只照心。","一掬信陵墳上土，便如碣石累千金。"]', '["賢豪出处尽沉吟，白日高懸只照心。","一掬信陵墳上土，便如碣石累千金。"]', '诗', 'shi', '', NULL, '偶詩五首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52cdf3e-1c86-4736-af5a-a9ada52d36db', '偶詩五首 四', '偶诗五首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["聲貌由來固絕倫，今朝共許占殘春。","當歌莫怪頻垂淚，得地翻慚早失身。"]', '["声貌由来固絕倫，今朝共許占殘春。","當歌莫怪頻垂泪，得地翻慚早失身。"]', '诗', 'shi', '', NULL, '偶詩五首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06774686-2e23-4309-b84e-83d0de71a64c', '偶詩五首 五', '偶诗五首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["中宵茶鼎沸時驚，正是寒窗竹雪明。","甘得寂寥能到老，一生心地亦應平。"]', '["中宵茶鼎沸时驚，正是寒窗竹雪明。","甘得寂寥能到老，一生心地亦應平。"]', '诗', 'shi', '', NULL, '偶詩五首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1773dc56-420a-4e73-b4c4-5adfff1cb1d0', '雜題二首 一', '杂題二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["先知左袒始同行，須待龍樓羽翼成。","若使只憑三傑力，猶應漢鼎一毫輕。"]', '["先知左袒始同行，須待龙楼羽翼成。","若使只憑三傑力，猶應漢鼎一毫轻。"]', '诗', 'shi', '', NULL, '雜題二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ad0863-2acd-4246-a32d-2b1d0cf94980', '雜題二首 二', '杂題二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["魚在枯池鳥在林，四時無奈雪霜侵。","若教激勸由真宰，亦獎青松徑寸心。"]', '["鱼在枯池鸟在林，四时無奈雪霜侵。","若教激勸由真宰，亦獎青松徑寸心。"]', '诗', 'shi', '', NULL, '雜題二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c930d2-cb7d-493a-a5df-0ba66deace2c', '光化踏青有感', '光化踏青有感', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["引得車回莫認恩，却成寂寞與誰論。","到頭不是君王意，羞插垂楊更傍門。"]', '["引得车回莫認恩，却成寂寞與誰論。","到头不是君王意，羞插垂楊更傍门。"]', '诗', 'shi', '', NULL, '光化踏青有感 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4c2074-a60e-458e-8c74-0ca8eebb6c93', '丑年冬', '丑年冬', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["醉日昔聞都下酒，何如今喜折新茶。","不堪病渴仍多慮，好向㴩湖便出家。"]', '["醉日昔闻都下酒，何如今喜折新茶。","不堪病渴仍多慮，好向㴩湖便出家。"]', '诗', 'shi', '', NULL, '丑年冬 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a24e9a-b734-4259-819a-f7dd4cf06a76', '白菊三首 一', '白菊三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["人間萬恨已難平，栽得垂[楊]更繫情。","猶喜閏前霜未下，菊邊依舊舞身輕。"]', '["人间万恨已难平，栽得垂[楊]更繫情。","猶喜閏前霜未下，菊邊依旧舞身轻。"]', '诗', 'shi', '', NULL, '白菊三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0999303b-6686-4053-8fd7-c69c1a37a46f', '白菊三首 二', '白菊三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["莫惜西風又起來，猶能婀娜傍池臺。","不辭暫被霜寒挫，舞袖招香即却回。"]', '["莫惜西风又起来，猶能婀娜傍池台。","不辞暫被霜寒挫，舞袖招香即却回。"]', '诗', 'shi', '', NULL, '白菊三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24629e4a-bb7a-49cc-b65d-74e1c4302908', '白菊三首 三', '白菊三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["爲報繁霜且莫催，窮秋須到自低垂。","橫拖長袖招人別，只待春風却舞來。"]', '["爲報繁霜且莫催，窮秋須到自低垂。","橫拖长袖招人別，只待春风却舞来。"]', '诗', 'shi', '', NULL, '白菊三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb31d2a1-2091-45fe-b4c2-2f3ab9d0e3bb', '扇', '扇', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["珍重逢秋莫棄捐，依依只仰故人憐。","有時池上遮殘日，承得霜林幾箇蟬。"]', '["珍重逢秋莫棄捐，依依只仰故人怜。","有时池上遮殘日，承得霜林幾箇蟬。"]', '诗', 'shi', '', NULL, '扇 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26f8dbf-ff6a-4d33-a854-65c43672e130', '修史亭三首 一', '修史亭三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["山前鄰叟去紛紛，獨強衰羸愛杜門。","漸覺一家看冷落，地爐生火自溫存。"]', '["山前鄰叟去紛紛，独強衰羸愛杜门。","漸覺一家看冷落，地爐生火自溫存。"]', '诗', 'shi', '', NULL, '修史亭三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d386094e-a3e1-4abe-8baa-c77bbb5fb9eb', '修史亭三首 二', '修史亭三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["甘心七十且酣歌，自算平生幸已多。","不似香山白居士，晚將心地著禪魔。"]', '["甘心七十且酣歌，自算平生幸已多。","不似香山白居士，晚將心地著禪魔。"]', '诗', 'shi', '', NULL, '修史亭三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9425c4a9-c282-4cca-bf59-6fe67d58ef98', '修史亭三首 三', '修史亭三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["烏紗巾上是青天，檢束酬知四十年。","誰料平生臂鷹手，挑燈自送佛前錢。"]', '["烏紗巾上是青天，檢束酬知四十年。","誰料平生臂鷹手，挑灯自送佛前錢。"]', '诗', 'shi', '', NULL, '修史亭三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ea5ba5-58ae-47a1-8131-da0a93602abd', '力疾山下吳邨看杏花十九首 一', '力疾山下吳邨看杏花十九首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["春來漸覺一川明，馬上繁花作陣迎。","掉臂只將詩酒敵，不勞金鼓助橫行。"]', '["春来漸覺一川明，马上繁花作陣迎。","掉臂只將诗酒敵，不勞金鼓助橫行。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5df1090-d3da-4543-a130-5f8a27e6e341', '力疾山下吳邨看杏花十九首 二', '力疾山下吳邨看杏花十九首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閶闔曾排捧御爐，猶看曉月認金鋪。","羸形不畫凌煙閣，只爲微才激壯圖。"]', '["閶闔曾排捧御爐，猶看晓月認金鋪。","羸形不畫凌煙閣，只爲微才激壯圖。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083d4f1f-3033-44bd-a1df-c94e61e8bf87', '力疾山下吳邨看杏花十九首 三', '力疾山下吳邨看杏花十九首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["鏡留雪鬢暖消無，春到棃花日又晡。","移取扶桑堦下種，年年看長礙金烏。"]', '["镜留雪鬢暖消無，春到棃花日又晡。","移取扶桑堦下種，年年看长礙金烏。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c09950a-c39a-4dae-83fa-9e1d8ef41a99', '力疾山下吳邨看杏花十九首 四', '力疾山下吳邨看杏花十九首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["折來未盡不須休，年少爭來莫與留。","更願狂風知我意，一時吹向海西頭。"]', '["折来未尽不須休，年少爭来莫與留。","更願狂风知我意，一时吹向海西头。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4e22cc-f4d9-4fca-9b88-118e4869286d', '力疾山下吳邨看杏花十九首 五', '力疾山下吳邨看杏花十九首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["才情百巧鬬風光，却笑雕花刻葉忙。","熨帖新巾來與裹，猶看騰踏少年場。"]', '["才情百巧鬬风光，却笑雕花刻葉忙。","熨帖新巾来與裹，猶看腾踏少年場。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7646349-bf1e-463f-93e0-c25911021cb6', '力疾山下吳邨看杏花十九首 六', '力疾山下吳邨看杏花十九首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["浮世榮枯總不知，且憂花陣被風欺。","儂家自有麒麟閣，第一功名只賞詩。"]', '["浮世榮枯總不知，且憂花陣被风欺。","儂家自有麒麟閣，第一功名只賞诗。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50c6ae8-1705-40c7-b787-5ec4a5a265a8', '力疾山下吳邨看杏花十九首 七', '力疾山下吳邨看杏花十九首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["白衫裁袖本教寬，朱紫由來亦一般。","王老小兒吹笛看，我儂試舞爾儂看。"]', '["白衫裁袖本教寬，朱紫由来亦一般。","王老小兒吹笛看，我儂試舞爾儂看。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3f3a94-9f70-4786-9e5d-5cc14faf8097', '力疾山下吳邨看杏花十九首 八', '力疾山下吳邨看杏花十九首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["單床薄被又羈棲，待到花開亦甚迷。","若道折多還有罪，只應鶯囀是金雞。"]', '["單床薄被又羈棲，待到花开亦甚迷。","若道折多還有罪，只應鶯囀是金雞。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f2aad1-8d19-4910-92cb-d990f42efb75', '力疾山下吳邨看杏花十九首 九', '力疾山下吳邨看杏花十九首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["近來桃李半燒枯，歸臥鄉園只老夫。","莫算明年人在否，不知花得更開無。"]', '["近来桃李半燒枯，归臥乡园只老夫。","莫算明年人在否，不知花得更开無。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b60b99e-c942-41e7-b83f-7d4a9ab60a45', '力疾山下吳邨看杏花十九首 十', '力疾山下吳邨看杏花十九首 十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["漢王何事損精神，花滿深宮不見春。","穠豔三千臨粉鏡，獨悲掩面李夫人。"]', '["漢王何事損精神，花满深宮不见春。","穠豔三千臨粉镜，独悲掩面李夫人。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('422153c9-35ef-4903-a530-fd8052db1275', '力疾山下吳邨看杏花十九首 十一', '力疾山下吳邨看杏花十九首 十一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["能豔能芳自一家，勝鸞勝鳳勝煙霞。","客來須共醒醒看，碾盡明昌幾角茶。"]', '["能豔能芳自一家，勝鸾勝鳳勝煙霞。","客来須共醒醒看，碾尽明昌幾角茶。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1629e96d-4bab-43d2-80da-8da1fdae9846', '力疾山下吳邨看杏花十九首 十二', '力疾山下吳邨看杏花十九首 十二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["造化無端欲自神，裁紅剪翠爲新春。","不如分減閑心力，更助英豪濟活人。"]', '["造化無端欲自神，裁紅剪翠爲新春。","不如分減闲心力，更助英豪濟活人。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94644c7d-8ad6-477c-88c7-9bac48c97799', '力疾山下吳邨看杏花十九首 十三', '力疾山下吳邨看杏花十九首 十三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["徘徊自勸莫沾纓，分付年年谷口鶯。","却賴無情容易別，有情早箇不勝情。"]', '["徘徊自勸莫沾纓，分付年年谷口鶯。","却賴無情容易別，有情早箇不勝情。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ecc4e7e-b4a0-4290-ba5b-7c728186d9d7', '力疾山下吳邨看杏花十九首 十四', '力疾山下吳邨看杏花十九首 十四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["閑步偏宜舞袖迎，春光何事獨無情。","垂楊合是詩家物，只愛敷溪道北生。"]', '["闲步偏宜舞袖迎，春光何事独無情。","垂楊合是诗家物，只愛敷溪道北生。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b09b1ab-864e-40ac-ab19-32f75c91d3ab', '力疾山下吳邨看杏花十九首 十五', '力疾山下吳邨看杏花十九首 十五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["亦知王大是昌齡，杜二其如律韻清。","還有酸寒堪笑處，擬誇朱紱更崢嶸。"]', '["亦知王大是昌齡，杜二其如律韻清。","還有酸寒堪笑处，擬誇朱紱更崢嶸。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d69155-945c-4b35-8730-44b61dd75a13', '力疾山下吳邨看杏花十九首 十六', '力疾山下吳邨看杏花十九首 十六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["潘郎愛說是詩家，枉占河陽一縣花。","千載幾人搜警句，補方金字愛晴霞。"]', '["潘郎愛说是诗家，枉占河陽一縣花。","千載幾人搜警句，補方金字愛晴霞。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f56eb08e-cc05-49be-b447-10a0b88a905c', '力疾山下吳邨看杏花十九首 十七', '力疾山下吳邨看杏花十九首 十七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["行樂溪邊步轉遲，出山漸減探花期。","去年四度今三度，恐到憑人折去時。"]', '["行乐溪邊步轉遲，出山漸減探花期。","去年四度今三度，恐到憑人折去时。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b59184-b840-4d47-95ee-a142894c9b3f', '力疾山下吳邨看杏花十九首 十八', '力疾山下吳邨看杏花十九首 十八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["此身衰病轉堪嗟，長忍春寒獨惜花。","更恨新詩無紙寫，蜀牋堆積是誰家。"]', '["此身衰病轉堪嗟，长忍春寒独惜花。","更恨新诗無紙寫，蜀牋堆積是誰家。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de37d6e-38d5-418f-aac6-13028dc3fbca', '力疾山下吳邨看杏花十九首 十九', '力疾山下吳邨看杏花十九首 十九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昨日黃昏始看回，夢中相約又銜杯。","起來聞到風飄却，猶擬教人掃取來。"]', '["昨日黄昏始看回，梦中相約又銜杯。","起来闻到风飄却，猶擬教人掃取来。"]', '诗', 'shi', '', NULL, '力疾山下吳邨看杏花十九首 十九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a00417-968f-41c2-87d2-ba89c05b5058', '少儀', '少儀', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昨日登班綴柏臺，更慚起草屬微才。","錦窠不是尋常錦，兼向丘遲奪得來。"]', '["昨日登班綴柏台，更慚起草屬微才。","錦窠不是尋常錦，兼向丘遲奪得来。"]', '诗', 'shi', '', NULL, '少儀 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e1906b-36f6-4a7b-9bfc-82255323a2a4', '重陽四首 一', '重陽四首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["簷前減燕菊添芳，燕盡庭前菊又荒。","老大比他年少少，每逢佳節更悲涼。"]', '["簷前減燕菊添芳，燕尽庭前菊又荒。","老大比他年少少，每逢佳節更悲涼。"]', '诗', 'shi', '', NULL, '重陽四首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4982fe25-1e34-4017-8d08-ae050f23af37', '重陽四首 二', '重陽四首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雨寒莫待菊花催，須怕晴空暖併開。","開却一枝開却盡，且隨幽蝶更徘徊。"]', '["雨寒莫待菊花催，須怕晴空暖併开。","开却一枝开却尽，且隨幽蝶更徘徊。"]', '诗', 'shi', '', NULL, '重陽四首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88003232-fd34-465e-a554-def43a11403d', '重陽四首 三', '重陽四首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["青娥懶唱無衣換，黃菊新開乞酒難。","長有長亭惆悵事，隔河更得對憑欄。"]', '["青娥懶唱無衣換，黄菊新开乞酒难。","长有长亭惆悵事，隔河更得对憑欄。"]', '诗', 'shi', '', NULL, '重陽四首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0783ac9-a773-46ac-ba0b-f718010cd17e', '重陽四首 四', '重陽四首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["白髮怕寒梳更懶，黃花晴日照初開。","籬頭應是蝶相報，已被鄰家攜酒來。"]', '["白髮怕寒梳更懶，黄花晴日照初开。","籬头應是蝶相報，已被鄰家携酒来。"]', '诗', 'shi', '', NULL, '重陽四首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5048f36-b4d4-493e-a981-97a4bcb220c8', '長命縷', '长命縷', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["他鄉處處堪悲事，殘照依依惜別天。","此去知名長命縷，殷勤爲我唱花前。"]', '["他乡处处堪悲事，殘照依依惜別天。","此去知名长命縷，殷勤爲我唱花前。"]', '诗', 'shi', '', NULL, '長命縷 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e0743d7-df63-4066-9ddf-b4d68ec9afcc', '柏東', '柏东', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["冥得機心豈在僧，柏東閑步愛騰騰。","免教世路人相忌，逢着村醪亦不憎。"]', '["冥得機心豈在僧，柏东闲步愛腾腾。","免教世路人相忌，逢着村醪亦不憎。"]', '诗', 'shi', '', NULL, '柏東 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a565c5-f80e-4d54-8526-85791275c919', '歌者十二首 一', '歌者十二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["追逐翻嫌傍管弦，金釵擊節自當筵。","風霜一夜燕鴻斷，唱作江南袚禊天。"]', '["追逐翻嫌傍管弦，金釵擊節自當筵。","风霜一夜燕鴻斷，唱作江南袚禊天。"]', '诗', 'shi', '', NULL, '歌者十二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300ea51e-62c5-419e-8f74-4b2dca620bad', '歌者十二首 二', '歌者十二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["玉樹花飄鳳失棲，一聲初壓管弦低。","清回煩署成瀟灑，豔逐寒雲變慘悽。"]', '["玉樹花飄鳳失棲，一声初壓管弦低。","清回煩署成瀟灑，豔逐寒云变慘悽。"]', '诗', 'shi', '', NULL, '歌者十二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf4b3da-3fb6-4a06-a969-c6a668638a4d', '歌者十二首 三', '歌者十二首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["十斛明珠亦易拚，欲兼人藝古來難。","五雲合是新聲染，鎔作瓊漿灑露盤。"]', '["十斛明珠亦易拚，欲兼人藝古来难。","五云合是新声染，鎔作瓊漿灑露盤。"]', '诗', 'shi', '', NULL, '歌者十二首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ba6ab81-6c19-470d-8947-d0494dc77810', '歌者十二首 四', '歌者十二首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不似新聲唱亦新，旋調玉管旋生春。","愁腸隔斷珠簾外，只爲今宵共聽人。"]', '["不似新声唱亦新，旋調玉管旋生春。","愁腸隔斷珠簾外，只爲今宵共听人。"]', '诗', 'shi', '', NULL, '歌者十二首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa62aca9-5335-4b44-b867-2e092849610a', '歌者十二首 五', '歌者十二首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["十年逃難別雲林，暫輟狂歌且聽琴。","轉覺淡交言有味，此聲知是古人心。"]', '["十年逃难別云林，暫輟狂歌且听琴。","轉覺淡交言有味，此声知是古人心。"]', '诗', 'shi', '', NULL, '歌者十二首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dd5613-5b16-402e-a9fa-409ca9a9b0e0', '歌者十二首 六', '歌者十二首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["五柳先生自識微，無言共笑手空揮。","胸中免被風波撓，肯爲螳螂動殺機。"]', '["五柳先生自識微，無言共笑手空揮。","胸中免被风波撓，肯爲螳螂动殺機。"]', '诗', 'shi', '', NULL, '歌者十二首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a76935e-c8b3-4245-ac68-17e60042d844', '歌者十二首 七', '歌者十二首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["風霜寒水旅人心，幾處笙歌繡戶深。","分泊一場雲散後，未勝初夜便聽琴。"]', '["风霜寒水旅人心，幾处笙歌繡戶深。","分泊一場云散後，未勝初夜便听琴。"]', '诗', 'shi', '', NULL, '歌者十二首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f19195b-c2e1-4fbd-ab6e-4bc9c76b57ee', '歌者十二首 八', '歌者十二首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自憐眼暗難求藥，莫恨花繁便有風。","桃李更開須強看，明年兼恐聽歌聾。"]', '["自怜眼暗难求藥，莫恨花繁便有风。","桃李更开須強看，明年兼恐听歌聾。"]', '诗', 'shi', '', NULL, '歌者十二首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98efd3fa-7d36-4b52-9025-98a1f819a074', '歌者十二首 九', '歌者十二首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["白雲深處寄生涯，歲暮生情賴此花。","蜂蝶繞來忙繞袖，似知教折送鄰家。"]', '["白云深处寄生涯，歲暮生情賴此花。","蜂蝶繞来忙繞袖，似知教折送鄰家。"]', '诗', 'shi', '', NULL, '歌者十二首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53fbb59-e525-4807-8150-e6d0f0cbc24f', '歌者十二首 十', '歌者十二首 十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["重九仍重歲漸闌，強開病眼更登攀。","年年認得酣歌處，猶恐招魂葬故山。"]', '["重九仍重歲漸闌，強开病眼更登攀。","年年認得酣歌处，猶恐招魂葬故山。"]', '诗', 'shi', '', NULL, '歌者十二首 十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b409d4-c039-42b8-b55f-30589baa76cd', '歌者十二首 十一', '歌者十二首 十一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["繞壁依稀認寫真，更須粉繪飾羸身。","淒涼不道身無壽，九日還無舊會人。"]', '["繞壁依稀認寫真，更須粉繪飾羸身。","淒涼不道身無壽，九日還無旧會人。"]', '诗', 'shi', '', NULL, '歌者十二首 十一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6caaaef-0e8a-4c79-bafe-df9e1e8dfa0a', '歌者十二首 十二', '歌者十二首 十二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["鶴氅花香搭槿籬，枕前蛩迸酒醒時。","夕陽似照陶家菊，黃蝶無窮壓故枝。"]', '["鹤氅花香搭槿籬，枕前蛩迸酒醒时。","夕陽似照陶家菊，黄蝶無窮壓故枝。"]', '诗', 'shi', '', NULL, '歌者十二首 十二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6faaea56-dbe9-459c-8592-d6cb02069bf2', '題裴晉公華嶽廟題名', '題裴晉公华嶽廟題名', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["嶽前大隊赴淮西，從此中原息鼓鼙。","石闕莫教苔蘚上，分明認取晉公題。"]', '["嶽前大隊赴淮西，從此中原息鼓鼙。","石闕莫教苔蘚上，分明認取晉公題。"]', '诗', 'shi', '', NULL, '題裴晉公華嶽廟題名 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bc67b0-717e-4e6f-8bb8-9fdea59aa2c1', '楊柳枝壽杯詞十八首 一', '楊柳枝壽杯词十八首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["樂府翻來占太平，風光無處不含情。","千門萬戶喧歌吹，富貴人間只此聲。"]', '["乐府翻来占太平，风光無处不含情。","千门万戶喧歌吹，富貴人间只此声。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991b7a35-43c0-43cc-9695-e99329ecdf08', '楊柳枝壽杯詞十八首 二', '楊柳枝壽杯词十八首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["撼晚梳空不自持，與君同折上樓時。","春風還有常情處，繫得人心免別離。"]', '["撼晚梳空不自持，與君同折上楼时。","春风還有常情处，繫得人心免別離。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d51ce74-4561-44d6-8f3b-8fad755d94d3', '楊柳枝壽杯詞十八首 三', '楊柳枝壽杯词十八首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["灞亭東去徹隋堤，贈別何須醉似泥。","萬里往來無一事，便帆輕拂亂鶯啼。"]', '["灞亭东去徹隋堤，贈別何須醉似泥。","万里往来無一事，便帆轻拂亂鶯啼。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d160d04-a01e-4fc7-a2f6-47bac7050e9c', '楊柳枝壽杯詞十八首 四', '楊柳枝壽杯词十八首 四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["臺城細仗曉初移，詔賜千官禊飲時。","綠帳遠籠輕珮響，更曛晴日上龍旗。"]', '["台城細仗晓初移，詔賜千官禊饮时。","綠帳远籠轻珮响，更曛晴日上龙旗。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ca92cb-9329-4378-b51d-d4695afe5c30', '楊柳枝壽杯詞十八首 五', '楊柳枝壽杯词十八首 五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["桃源仙子不須誇，聞道惟栽一片花。","何似浣紗溪畔住，綠陰相間兩三家。"]', '["桃源仙子不須誇，闻道惟栽一片花。","何似浣紗溪畔住，綠陰相间兩三家。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56af7bc-0f4a-4f7d-a874-b94bf635e0b9', '楊柳枝壽杯詞十八首 六', '楊柳枝壽杯词十八首 六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["偶然樓上卷珠簾，往往長條拂枕函。","恰值小娥初學舞，擬偷金縷押春衫。"]', '["偶然楼上卷珠簾，往往长條拂枕函。","恰值小娥初学舞，擬偷金縷押春衫。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21794d52-25f2-41f6-8a6a-251e5e38ba30', '楊柳枝壽杯詞十八首 七', '楊柳枝壽杯词十八首 七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["池邊影動散鴛鴦，更引微風亂繡牀。","直待玉窗塵不起，始應金鴈得成行。"]', '["池邊影动散鴛鴦，更引微风亂繡牀。","直待玉窗塵不起，始應金鴈得成行。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df98b09e-516c-44f6-893b-91f28ed1b5ae', '楊柳枝壽杯詞十八首 八', '楊柳枝壽杯词十八首 八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["稻畦分影向江邨，憔悴經霜只半存。","昨日流鶯今不見，亂螢飛出照黃昏。"]', '["稻畦分影向江邨，憔悴經霜只半存。","昨日流鶯今不见，亂螢飞出照黄昏。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba78680-94ae-4a4f-877d-666745f8f0da', '楊柳枝壽杯詞十八首 九', '楊柳枝壽杯词十八首 九', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["客淚休沾漢水濱，舞腰羞殺漢宮人。","狂風更與回煙箒，掃盡繁花獨占春。"]', '["客泪休沾漢水濱，舞腰羞殺漢宮人。","狂风更與回煙箒，掃尽繁花独占春。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 九 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e107fb7-ce0e-4935-9f20-39f90087ed35', '楊柳枝壽杯詞十八首 十', '楊柳枝壽杯词十八首 十', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["遊人莫歎易凋衰，長樂榮枯自有期。","看取明年春意動，更於何處最先知。"]', '["游人莫歎易凋衰，长乐榮枯自有期。","看取明年春意动，更於何处最先知。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('640aeba6-bb5e-4df5-b9b8-edf191ae81b1', '楊柳枝壽杯詞十八首 十一', '楊柳枝壽杯词十八首 十一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["昔年行樂及芳時，一上丹梯桂一枝。","笑問江頭醉公子，饒君滿把麴塵絲。"]', '["昔年行乐及芳时，一上丹梯桂一枝。","笑问江头醉公子，饒君满把麴塵絲。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4c636e-bb9f-4dba-a828-a909f9c5189a', '楊柳枝壽杯詞十八首 十二', '楊柳枝壽杯词十八首 十二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["渡頭殘照一行新，獨自依依向北人。","莫恨鄉程千里遠，眼中從此故鄉春。"]', '["渡头殘照一行新，独自依依向北人。","莫恨乡程千里远，眼中從此故乡春。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce721c5-1c99-474d-904b-bd76c684681e', '楊柳枝壽杯詞十八首 十三', '楊柳枝壽杯词十八首 十三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["絮惹輕枝雪未飄，小溪煙束帶危橋。","鄰家女伴頻攀折，不覺回身罥翠翹。"]', '["絮惹轻枝雪未飄，小溪煙束带危橋。","鄰家女伴頻攀折，不覺回身罥翠翹。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f1a3a9-faf1-46c4-8357-9403ce86cff4', '楊柳枝壽杯詞十八首 十四', '楊柳枝壽杯词十八首 十四', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["處處縈空百萬枝，一枝枝好更題詩。","隔城遠岫招行客，便與朱樓當酒旗。"]', '["处处縈空百万枝，一枝枝好更題诗。","隔城远岫招行客，便與朱楼當酒旗。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十四 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc6ce7b-2491-4e18-9fe5-591da164e490', '楊柳枝壽杯詞十八首 十五', '楊柳枝壽杯词十八首 十五', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["錦城分得映金溝，兩岸年年引勝遊。"]', '["錦城分得映金溝，兩岸年年引勝游。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十五 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91441932-3571-404e-93f3-73d1bf4871ff', '楊柳枝壽杯詞十八首 十六', '楊柳枝壽杯词十八首 十六', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["日暖津頭絮已飛，看看還是送君歸。","莫言萬緒牽愁思，緝取長繩繫落暉。"]', '["日暖津头絮已飞，看看還是送君归。","莫言万緒牽愁思，緝取长繩繫落暉。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十六 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13884152-b9e9-40c7-abb8-2540daa9747e', '楊柳枝壽杯詞十八首 十七', '楊柳枝壽杯词十八首 十七', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["大堤時節近清明，霞襯煙籠遶郡城。","好是梨花相映處，更勝松雪日初晴。"]', '["大堤时節近清明，霞襯煙籠遶郡城。","好是梨花相映处，更勝松雪日初晴。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十七 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a73765f-2b6d-48be-bde1-3388d0264379', '楊柳枝壽杯詞十八首 十八', '楊柳枝壽杯词十八首 十八', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["聖主千年樂未央，御溝金翠滿垂楊。","年年織作升平字，高映南山獻壽觴。"]', '["聖主千年乐未央，御溝金翠满垂楊。","年年织作升平字，高映南山獻壽觴。"]', '诗', 'shi', '', NULL, '楊柳枝壽杯詞十八首 十八 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b8b9f5e-95de-44e7-8659-e4f60090292a', '山鵲', '山鵲', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["多驚本爲好毛衣，只賴人憐始却歸。","衆鳥自知顏色減，妬他偏向眼前飛。"]', '["多驚本爲好毛衣，只賴人怜始却归。","衆鸟自知顏色減，妬他偏向眼前飞。"]', '诗', 'shi', '', NULL, '山鵲 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19935893-8dc1-47a4-b7ce-4637321baa65', '李居士', '李居士', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["高風只在五峰前，應是精靈降作賢。","萬里無雲惟一鶴，鄉中同看却昇天。"]', '["高风只在五峰前，應是精靈降作賢。","万里無云惟一鹤，乡中同看却昇天。"]', '诗', 'shi', '', NULL, '李居士 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fd429d-5cdf-4bda-9d0f-e04f12f224af', '杏花', '杏花', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["詩家偏爲此傷情，品韻由來莫與爭。","解笑亦應兼解語，只應慵語倩鶯聲。"]', '["诗家偏爲此傷情，品韻由来莫與爭。","解笑亦應兼解語，只應慵語倩鶯声。"]', '诗', 'shi', '', NULL, '杏花 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df27fd6-291b-49e4-9e42-94afbbbae717', '白菊三首 一', '白菊三首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不疑陶令是狂生，作賦其如有定情。","猶勝江南隱居士，詩魔終嫋負孤名。"]', '["不疑陶令是狂生，作賦其如有定情。","猶勝江南隐居士，诗魔終嫋負孤名。"]', '诗', 'shi', '', NULL, '白菊三首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2218791-f432-4923-a93b-129a18f62b01', '白菊三首 二', '白菊三首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["自古詩人少顯榮，逃名何用更題名。","詩中有慮猶須戒，莫向詩中著不平。"]', '["自古诗人少显榮，逃名何用更題名。","诗中有慮猶須戒，莫向诗中著不平。"]', '诗', 'shi', '', NULL, '白菊三首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7132b3db-7589-4865-aea2-d616d82d73c9', '白菊三首 三', '白菊三首 三', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["登高可羨少年場，白菊堆邊鬢似霜。","益算更希沾上藥，今朝第七十重陽。"]', '["登高可羨少年場，白菊堆邊鬢似霜。","益算更希沾上藥，今朝第七十重陽。"]', '诗', 'shi', '', NULL, '白菊三首 三 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0c9721-e1cf-417b-bc69-775f13936a4c', '聽雨', '听雨', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["半夜思家睡裏愁，雨聲落落屋簷頭。","照泥星出依前黑，淹爛庭花不肯休。"]', '["半夜思家睡裏愁，雨声落落屋簷头。","照泥星出依前黑，淹爛庭花不肯休。"]', '诗', 'shi', '', NULL, '聽雨 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c1d03c-457c-4f61-a7ee-0a896c02606a', '楊柳枝二首 一', '楊柳枝二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["陶家五柳簇衡門，還有高情愛此君。","何處更添詩境好，新蟬欹枕每先聞。"]', '["陶家五柳簇衡门，還有高情愛此君。","何处更添诗境好，新蟬欹枕每先闻。"]', '诗', 'shi', '', NULL, '楊柳枝二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da4721a-bf15-4aac-895e-db29bbadccd6', '楊柳枝二首 二', '楊柳枝二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["數枝珍重蘸滄浪，無限塵心暫免忙。","煩暑若和煙露裛，便同佛手灑清涼。"]', '["數枝珍重蘸滄浪，無限塵心暫免忙。","煩暑若和煙露裛，便同佛手灑清涼。"]', '诗', 'shi', '', NULL, '楊柳枝二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35c4388a-1d08-4c2f-a78d-da44e522ce40', '修史亭二首 一', '修史亭二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["少年已慣擲年光，時節催驅獨不忙。","今日無疑亦無病，前程無事擾醫王。"]', '["少年已慣擲年光，时節催驱独不忙。","今日無疑亦無病，前程無事擾醫王。"]', '诗', 'shi', '', NULL, '修史亭二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b9e489-4ffe-4b5b-aad3-b4a6d274e4fe', '修史亭二首 二', '修史亭二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["籬落輕寒整頓新，雪晴步屣會諸鄰。","自從南至歌風頂，始見人煙外有人。"]', '["籬落轻寒整頓新，雪晴步屣會諸鄰。","自從南至歌风頂，始见人煙外有人。"]', '诗', 'shi', '', NULL, '修史亭二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa67069a-e4c0-4249-948b-a2e29418896e', '漫書', '漫书', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["樂退安貧知是分，成家報國亦何慚。","到還僧院心期在，瑟瑟澄鮮百丈潭。"]', '["乐退安貧知是分，成家報国亦何慚。","到還僧院心期在，瑟瑟澄鲜百丈潭。"]', '诗', 'shi', '', NULL, '漫書 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2e1267-c71b-4f73-ab65-ae7eda3c3870', '雜題二首 一', '杂題二首 一', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["棋局長攜上釣船，殺中棋殺勝絲牽。","洪鑪任鑄千鈞鼎，只在磻溪一縷懸。"]', '["棋局长携上釣船，殺中棋殺勝絲牽。","洪鑪任鑄千鈞鼎，只在磻溪一縷懸。"]', '诗', 'shi', '', NULL, '雜題二首 一 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6a9b54-b12d-4b55-b209-a82b4cacb0b5', '雜題二首 二', '杂題二首 二', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["曉鏡高窗氣象深，自憐清格笑塵心。","世間不爲蛾眉誤，海上方應鶴背吟。"]', '["晓镜高窗氣象深，自怜清格笑塵心。","世间不爲蛾眉誤，海上方應鹤背吟。"]', '诗', 'shi', '', NULL, '雜題二首 二 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77fb33d6-6073-4147-b1c8-1673dfdd6856', '題休休亭', '題休休亭', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["咄，諾。","休休休，莫莫莫。","伎兩雖多性靈惡，賴是長教閑處著。","休休休，莫莫莫。","一局棋，一爐藥。","天意時情可料度，白日偏催快活人。","黃金難買堪騎鶴，若曰爾何能，荅言耐辱莫。"]', '["咄，諾。","休休休，莫莫莫。","伎兩雖多性靈惡，賴是长教闲处著。","休休休，莫莫莫。","一局棋，一爐藥。","天意时情可料度，白日偏催快活人。","黄金难買堪騎鹤，若曰爾何能，荅言耐辱莫。"]', '诗', 'shi', '', NULL, '題休休亭 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fbb614c-d10f-4780-a112-b37130fbbc02', '馮燕歌', '馮燕歌', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["魏中義士有馮燕，遊俠幽幷最少年。","避讐偶作滑臺客，嘶風躍馬來翩翩。","此時恰遇鶯花月，堤上軒車晝不絕。","兩面高樓語笑聲，指點行人情暗結。","擲果潘郎誰不慕，朱門別見紅妝露。","故故推門掩不開，似教歐軋傳言語。","馮生敲鐙袖籠鞭，半拂垂楊半惹煙。","樹間春鳥知人意，的的心期暗與傳。","傳道張嬰偏嗜酒，從此香閨爲我有。","梁間客燕正相欺，屋上鳴鳩空自鬬。","嬰歸醉臥非讐汝，豈知負過人懷懼。","燕依戶扇欲潛逃，巾在枕傍指令取。","誰言狼戾心能忍，待我情深情不隱。","回身本謂取巾難，倒柄方知授霜刅。","馮君撫劒即遲疑，自顧平生心不欺。","爾能負彼必相負，假手他人復在誰。","窗間紅豔猶可掬，熟視花鈿情不足。","唯將大義斷胸襟，粉頸初迴如切玉。","鳳皇釵碎各分飛，怨魄嬌魂何處追。","凌波如喚遊金谷，羞彼[揶揄]淚滿衣。","新人藏匿舊人起，白晝喧呼駭鄰里。","誣執張嬰不自明，貴免生前遭考捶。","官將赴市擁紅塵，掉臂人來擗看人。","傳聲莫遣有冤濫，盜殺嬰家即我身。","初聞僚吏翻疑歎，呵叱風狂詞不變。","縲囚解縛猶自疑，疑是夢中方脫免。","未死勸君莫浪言，臨危不顧始知難。","已爲不平能割愛，更將身命救深冤。","白馬賢侯賈相公，長懸金帛募才雄。","拜章請贖馮燕罪，千古三河激義風。","黃河東注無時歇，注盡波瀾名不滅。","爲感詞人沈下賢，長歌更與分明說。","此君精爽知猶在，長與人間留炯誡。","鑄作金燕香作堆，焚香酬酒聽歌來。"]', '["魏中義士有馮燕，游俠幽幷最少年。","避讐偶作滑台客，嘶风躍马来翩翩。","此时恰遇鶯花月，堤上軒车晝不絕。","兩面高楼語笑声，指点行人情暗結。","擲果潘郎誰不慕，朱门別见紅妝露。","故故推门掩不开，似教歐軋傳言語。","馮生敲鐙袖籠鞭，半拂垂楊半惹煙。","樹间春鸟知人意，的的心期暗與傳。","傳道張嬰偏嗜酒，從此香閨爲我有。","梁间客燕正相欺，屋上鳴鳩空自鬬。","嬰归醉臥非讐汝，豈知負過人懷懼。","燕依戶扇欲潛逃，巾在枕傍指令取。","誰言狼戾心能忍，待我情深情不隐。","回身本謂取巾难，倒柄方知授霜刅。","馮君撫劒即遲疑，自顧平生心不欺。","爾能負彼必相負，假手他人复在誰。","窗间紅豔猶可掬，熟視花鈿情不足。","唯將大義斷胸襟，粉頸初迴如切玉。","鳳皇釵碎各分飞，怨魄嬌魂何处追。","凌波如喚游金谷，羞彼[揶揄]泪满衣。","新人藏匿旧人起，白晝喧呼駭鄰里。","誣執張嬰不自明，貴免生前遭考捶。","官將赴市擁紅塵，掉臂人来擗看人。","傳声莫遣有冤濫，盜殺嬰家即我身。","初闻僚吏翻疑歎，呵叱风狂词不变。","縲囚解縛猶自疑，疑是梦中方脫免。","未死勸君莫浪言，臨危不顧始知难。","已爲不平能割愛，更將身命救深冤。","白马賢侯賈相公，长懸金帛募才雄。","拜章請贖馮燕罪，千古三河激義风。","黄河东注無时歇，注尽波瀾名不滅。","爲感词人沈下賢，长歌更與分明说。","此君精爽知猶在，长與人间留炯誡。","鑄作金燕香作堆，焚香酬酒听歌来。"]', '诗', 'shi', '', NULL, '馮燕歌 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a1128d-e315-4e89-8450-b3e7dca1029d', '寄薛起居', '寄薛起居', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["小域新銜賀聖朝，亦知蹇分巧難拋。","麤才自合無岐路，不破工夫漫解嘲。"]', '["小域新銜賀聖朝，亦知蹇分巧难拋。","麤才自合無岐路，不破工夫漫解嘲。"]', '诗', 'shi', '', NULL, '寄薛起居 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1cac948-8ede-4d0e-9bd9-c6f99763542a', '月下留丹竈', '月下留丹竈', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["月下留丹竈，壇邊樹羽衣。","異香人不覺，殘夜鶴分飛。","朝會初元盛，蓬瀛舊侶稀。","瑤函真跡在，妖魅敢揚威。"]', '["月下留丹竈，壇邊樹羽衣。","異香人不覺，殘夜鹤分飞。","朝會初元盛，蓬瀛旧侶稀。","瑤函真跡在，妖魅敢揚威。"]', '诗', 'shi', '', NULL, '月下留丹竈 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e600f4-b6e0-4caf-b752-3442cad3291b', '元日', '元日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["甲子今重數，生涯只自憐。","殷勤元日日，欹午又明年。"]', '["甲子今重數，生涯只自怜。","殷勤元日日，欹午又明年。"]', '诗', 'shi', '', NULL, '元日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('989b140b-b6be-4437-abc8-427d0cfae843', '洛陽詠古', '洛陽詠古', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["石勒童年有戰機，洛陽長嘯倚門時。","晉朝不是王夷甫，大智何由得預知。"]', '["石勒童年有戰機，洛陽长嘯倚门时。","晉朝不是王夷甫，大智何由得預知。"]', '诗', 'shi', '', NULL, '洛陽詠古 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a93088-0dcb-49d7-baa0-38d17360acb4', '詩品二十四則 雄渾', '诗品二十四則 雄渾', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["大用外腓，真體內充。","返虛入渾，積健爲雄。","具備萬物，橫絕太空。","荒荒油雲，寥寥長風。","超以象外，得其環中。","持之匪強，來之無窮。"]', '["大用外腓，真體內充。","返虛入渾，積健爲雄。","具備万物，橫絕太空。","荒荒油云，寥寥长风。","超以象外，得其环中。","持之匪強，来之無窮。"]', '诗', 'shi', '', NULL, '詩品二十四則 雄渾 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c73e26d9-454f-4413-8acd-906d1aa3e662', '詩品二十四則 沖淡', '诗品二十四則 沖淡', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["素處以默，妙機其微。","飲之太和，獨鶴與飛。","猶之惠風，苒苒在衣。","閱音修篁，美曰載歸。","遇之匪深，即之愈稀。","脫有形似，握手已違。"]', '["素处以默，妙機其微。","饮之太和，独鹤與飞。","猶之惠风，苒苒在衣。","閱音修篁，美曰載归。","遇之匪深，即之愈稀。","脫有形似，握手已違。"]', '诗', 'shi', '', NULL, '詩品二十四則 沖淡 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83171b8-7a62-4eaf-b2cc-470914576177', '詩品二十四則 纖穠', '诗品二十四則 纖穠', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["采采流水，蓬蓬遠春。","窈窕深谷，時見美人。","碧桃滿樹，風日水濱。","柳陰路曲，流鶯比鄰。","乘之愈往，識之愈真。","如將不盡，與古爲新。"]', '["采采流水，蓬蓬远春。","窈窕深谷，时见美人。","碧桃满樹，风日水濱。","柳陰路曲，流鶯比鄰。","乘之愈往，識之愈真。","如將不尽，與古爲新。"]', '诗', 'shi', '', NULL, '詩品二十四則 纖穠 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f60329c-6fbf-4e79-b001-933f90311d37', '詩品二十四則 沈著', '诗品二十四則 沈著', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["綠杉野屋，落日氣清。","脫巾獨步，時聞鳥聲。","鴻鴈不來，之子遠行。","所思不遠，若爲平生。","海風碧雲，夜渚月明。","如有佳語，大河前橫。"]', '["綠杉野屋，落日氣清。","脫巾独步，时闻鸟声。","鴻鴈不来，之子远行。","所思不远，若爲平生。","海风碧云，夜渚月明。","如有佳語，大河前橫。"]', '诗', 'shi', '', NULL, '詩品二十四則 沈著 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96104c85-c9df-4967-8fd3-a33d09cd71cb', '詩品二十四則 高古', '诗品二十四則 高古', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["畸人乘真，手把芙蓉。","泛彼浩劫，窅然空縱。","月出東斗，好風相從。","太華夜碧，人聞清鐘。","虛佇神素，脫然畦封。","黃唐在獨，落落玄宗。"]', '["畸人乘真，手把芙蓉。","泛彼浩劫，窅然空縱。","月出东斗，好风相從。","太华夜碧，人闻清鐘。","虛佇神素，脫然畦封。","黄唐在独，落落玄宗。"]', '诗', 'shi', '', NULL, '詩品二十四則 高古 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d555cb2-83cb-4962-9048-867be0255a3d', '詩品二十四則 典雅', '诗品二十四則 典雅', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["玉壺買春，賞雨茆屋。","坐中佳士，左右修竹。","白雲初晴，幽鳥相逐。","眠琴綠陰，上有飛瀑。","落花無言，人淡如菊。","書之歲華，其曰可讀。"]', '["玉壺買春，賞雨茆屋。","坐中佳士，左右修竹。","白云初晴，幽鸟相逐。","眠琴綠陰，上有飞瀑。","落花無言，人淡如菊。","书之歲华，其曰可读。"]', '诗', 'shi', '', NULL, '詩品二十四則 典雅 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef2f3ad2-6df1-4519-ab0e-ae19a456cb6b', '詩品二十四則 洗煉', '诗品二十四則 洗煉', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["猶鑛出金，如鉛出銀。","超心煉冶，絕愛[緇]磷。","空潭瀉春，古鏡照神。","體素儲潔，乘月返真。","載瞻星辰，載歌幽人。","流水今日，明月前身。"]', '["猶鑛出金，如鉛出銀。","超心煉冶，絕愛[緇]磷。","空潭瀉春，古镜照神。","體素儲潔，乘月返真。","載瞻星辰，載歌幽人。","流水今日，明月前身。"]', '诗', 'shi', '', NULL, '詩品二十四則 洗煉 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dbdddda-95ab-4546-bd08-654ef2d08586', '詩品二十四則 勁健', '诗品二十四則 勁健', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["行神如空，行氣如虹。","巫峽千尋，走雲連風。","飲真茹強，蓄素守中。","喻彼行健，是謂存雄。","天地與立，神化攸同。","期之以實，御之以終。"]', '["行神如空，行氣如虹。","巫峽千尋，走云連风。","饮真茹強，蓄素守中。","喻彼行健，是謂存雄。","天地與立，神化攸同。","期之以實，御之以終。"]', '诗', 'shi', '', NULL, '詩品二十四則 勁健 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b406fec9-9888-4ba7-bcc1-44aea1fb1d2a', '詩品二十四則 綺麗', '诗品二十四則 綺丽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["神存富貴，始輕黃金。","濃盡必枯，淺者屢深。","露餘山青，紅杏在林。","月明華屋，畫橋碧陰。","金尊酒滿，共客彈琴。","取之自足，良殫美襟。"]', '["神存富貴，始轻黄金。","濃尽必枯，淺者屢深。","露餘山青，紅杏在林。","月明华屋，畫橋碧陰。","金尊酒满，共客彈琴。","取之自足，良殫美襟。"]', '诗', 'shi', '', NULL, '詩品二十四則 綺麗 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026db8ed-2a59-495f-a4e5-25556b033624', '詩品二十四則 自然', '诗品二十四則 自然', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["俯拾即是，不取諸鄰。","俱道適往，著手成春。","如逢花開，如瞻歲新。","真予不奪，強得易貧。","幽人空山，過水采蘋。","薄言情晤，悠悠天鈞。"]', '["俯拾即是，不取諸鄰。","俱道適往，著手成春。","如逢花开，如瞻歲新。","真予不奪，強得易貧。","幽人空山，過水采蘋。","薄言情晤，悠悠天鈞。"]', '诗', 'shi', '', NULL, '詩品二十四則 自然 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c871d1f-0985-4ae8-b0d3-9f0ba929a0ec', '詩品二十四則 含蓄', '诗品二十四則 含蓄', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["不著一字，盡得風流。","語不涉難，已不堪憂。","是有真宰，與之沈浮。","如淥滿酒，花時返秋。","悠悠空塵，忽忽海漚。","淺深聚散，萬取一收。"]', '["不著一字，尽得风流。","語不涉难，已不堪憂。","是有真宰，與之沈浮。","如淥满酒，花时返秋。","悠悠空塵，忽忽海漚。","淺深聚散，万取一收。"]', '诗', 'shi', '', NULL, '詩品二十四則 含蓄 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e802371-0491-47f3-8981-97898b118867', '詩品二十四則 豪放', '诗品二十四則 豪放', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["觀花匪禁，吞吐大荒。","由道返氣，處得以狂。","天風浪浪，海山蒼蒼。","真力彌滿，萬象在旁。","前招三辰，後引鳳皇。","曉策六鼇，濯足扶桑。"]', '["观花匪禁，吞吐大荒。","由道返氣，处得以狂。","天风浪浪，海山蒼蒼。","真力彌满，万象在旁。","前招三辰，後引鳳皇。","晓策六鼇，濯足扶桑。"]', '诗', 'shi', '', NULL, '詩品二十四則 豪放 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23d4003-2d86-43a6-b3a5-d8167828d08f', '詩品二十四則 精神', '诗品二十四則 精神', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["欲返不盡，相期與來。","明漪絕底，奇花初胎。","青春鸚鵡，楊柳池臺。","碧山人來，清酒滿杯。","生氣遠出，不著死灰。","妙造自然，伊誰與裁。"]', '["欲返不尽，相期與来。","明漪絕底，奇花初胎。","青春鸚鵡，楊柳池台。","碧山人来，清酒满杯。","生氣远出，不著死灰。","妙造自然，伊誰與裁。"]', '诗', 'shi', '', NULL, '詩品二十四則 精神 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ad7b55-75ba-419d-8dd1-26f9d4db11ef', '詩品二十四則 縝密', '诗品二十四則 縝密', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["是有真跡，如不可知。","意象欲生，造化已奇。","水流花開，清露未晞。","要路愈遠，幽行爲遲。","語不欲犯，思不欲癡。","猶春於綠，明月雪時。"]', '["是有真跡，如不可知。","意象欲生，造化已奇。","水流花开，清露未晞。","要路愈远，幽行爲遲。","語不欲犯，思不欲癡。","猶春於綠，明月雪时。"]', '诗', 'shi', '', NULL, '詩品二十四則 縝密 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf0d96c-74c2-4f65-b53d-c50571102a1d', '詩品二十四則 疎野', '诗品二十四則 疎野', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["惟性所宅，真取弗羈。","拾物自富，與率爲期。","築屋松下，脫帽看詩。","但知旦暮，不辨何時。","倘然適意，豈必有爲。","若其天放，如是得之。"]', '["惟性所宅，真取弗羈。","拾物自富，與率爲期。","築屋松下，脫帽看诗。","但知旦暮，不辨何时。","倘然適意，豈必有爲。","若其天放，如是得之。"]', '诗', 'shi', '', NULL, '詩品二十四則 疎野 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb29e78-7a6d-494c-83b5-cfdbc6d1a4fe', '詩品二十四則 清奇', '诗品二十四則 清奇', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["娟娟羣松，下有漪流。","晴雪滿汀，隔溪漁舟。","可人如玉，步屧尋幽。","載行載止，空碧悠悠。","神出古異，淡不可收。","如月之曙，如氣之秋。"]', '["娟娟羣松，下有漪流。","晴雪满汀，隔溪漁舟。","可人如玉，步屧尋幽。","載行載止，空碧悠悠。","神出古異，淡不可收。","如月之曙，如氣之秋。"]', '诗', 'shi', '', NULL, '詩品二十四則 清奇 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c940e34-3fda-4ef2-9268-45524a413e02', '詩品二十四則 委曲', '诗品二十四則 委曲', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["登彼太行，翠遶羊腸。","杳靄流玉，悠悠花香。","力之於時，聲之於羌。","似往已迴，如幽匪藏。","水理漩洑，鵬風翱翔。","道不自器，與之圓方。"]', '["登彼太行，翠遶羊腸。","杳靄流玉，悠悠花香。","力之於时，声之於羌。","似往已迴，如幽匪藏。","水理漩洑，鵬风翱翔。","道不自器，與之圓方。"]', '诗', 'shi', '', NULL, '詩品二十四則 委曲 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21d01c8-0d64-4d33-a827-2533ed66331a', '詩品二十四則 實境', '诗品二十四則 實境', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["取語甚直，計思匪深。","忽逢幽人，如見道心。","晴磵之曲，碧松之陰。","一客荷樵，一客聽琴。","情性所至，妙不自尋。","遇之自天，冷然希音。"]', '["取語甚直，計思匪深。","忽逢幽人，如见道心。","晴磵之曲，碧松之陰。","一客荷樵，一客听琴。","情性所至，妙不自尋。","遇之自天，冷然希音。"]', '诗', 'shi', '', NULL, '詩品二十四則 實境 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('077e468a-ec52-468b-b76f-2024c7bb8924', '詩品二十四則 悲慨', '诗品二十四則 悲慨', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["大風捲水，林木爲摧。","意苦若死，招憩不來。","百歲如流，富貴冷灰。","大道日往，若爲雄才。","壯士拂劒，浩然彌哀。","蕭蕭落葉，漏雨蒼苔。"]', '["大风捲水，林木爲摧。","意苦若死，招憩不来。","百歲如流，富貴冷灰。","大道日往，若爲雄才。","壯士拂劒，浩然彌哀。","蕭蕭落葉，漏雨蒼苔。"]', '诗', 'shi', '', NULL, '詩品二十四則 悲慨 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f623830-7ea6-45f5-9a9c-35724dd4c1ef', '詩品二十四則 形容', '诗品二十四則 形容', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["絕佇靈素，少迴清真。","如覓水影，如寫陽春。","風雲變態，花草精神。","海之波瀾，山之嶙峋。","俱似大道，妙契同塵。","離形得似，庶幾斯人。"]', '["絕佇靈素，少迴清真。","如覓水影，如寫陽春。","风云变態，花草精神。","海之波瀾，山之嶙峋。","俱似大道，妙契同塵。","離形得似，庶幾斯人。"]', '诗', 'shi', '', NULL, '詩品二十四則 形容 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4442282-304d-4418-a7b2-683aa859e9e2', '詩品二十四則 超詣', '诗品二十四則 超詣', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["匪神之靈，匪機之微。","如將白雲，清風與歸。","遠引若至，臨之已非。","少有道契，終與俗違。","亂山高木，碧苔芳暉。","誦之思之，其聲愈稀。"]', '["匪神之靈，匪機之微。","如將白云，清风與归。","远引若至，臨之已非。","少有道契，終與俗違。","亂山高木，碧苔芳暉。","誦之思之，其声愈稀。"]', '诗', 'shi', '', NULL, '詩品二十四則 超詣 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aa04f9-1153-4c1b-8b67-ac9c905fdc74', '詩品二十四則 飄逸', '诗品二十四則 飄逸', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["落落欲往，矯矯不羣。","緱山之鶴，華頂之雲。","高人畫中，令色絪緼。","御風蓬葉，泛彼無垠。","如不可執，如將有聞。","識者已領，期之愈分。"]', '["落落欲往，矯矯不羣。","緱山之鹤，华頂之云。","高人畫中，令色絪緼。","御风蓬葉，泛彼無垠。","如不可執，如將有闻。","識者已領，期之愈分。"]', '诗', 'shi', '', NULL, '詩品二十四則 飄逸 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9e4874-a933-4ae0-ac01-4c0bfc39d6c5', '詩品二十四則 曠達', '诗品二十四則 曠達', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["生者百歲，相去幾何。","歡樂苦短，憂愁實多。","何如尊酒，日往烟蘿。","花覆茆簷，疎雨相過。","倒酒既盡，杖藜行過。","孰不有古，南山峨峨。"]', '["生者百歲，相去幾何。","歡乐苦短，憂愁實多。","何如尊酒，日往烟蘿。","花覆茆簷，疎雨相過。","倒酒既尽，杖藜行過。","孰不有古，南山峨峨。"]', '诗', 'shi', '', NULL, '詩品二十四則 曠達 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130fc4ff-8f1d-4785-8e4f-8f2417d9ecda', '詩品二十四則 流動', '诗品二十四則 流动', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["若納水輨，如轉丸珠。","夫豈可道，假體遺愚。","荒荒坤軸，悠悠天樞。","載要其端，載同其符。","超超神明，返返冥無。","來往千載，是之謂乎。"]', '["若納水輨，如轉丸珠。","夫豈可道，假體遺愚。","荒荒坤軸，悠悠天樞。","載要其端，載同其符。","超超神明，返返冥無。","来往千載，是之謂乎。"]', '诗', 'shi', '', NULL, '詩品二十四則 流動 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313efe5c-4f68-48c6-9ee1-d85613a4c47c', '句', '句', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["忍事敵災星，物望傾心久。","兇渠破膽頻。","鼎飫和方濟，台階潤欲平。","夜短猨悲減，風和鵲喜虛。","驊騮思故第，鸚鵡失佳人。","鯨鯢人海涸，魑魅棘林幽。","棋聲花院閉，幡影石壇高。","地涼清鶴夢，林靜肅僧儀。","晚妝留拜月，春睡更生香。","隔谷見雞犬，山苗接楚田。","人家寒食月，花影午時天。","官路好禽聲，軒車駐晚程。","南樓山最秀，北路邑偏清。","多病形容五十三，誰鄰借笏趂朝參。","十年太華無知己，只得虛中兩首詩。","看師逸蹟兩師宜，高適歌行李白詩。"]', '["忍事敵災星，物望傾心久。","兇渠破膽頻。","鼎飫和方濟，台階潤欲平。","夜短猨悲減，风和鵲喜虛。","驊騮思故第，鸚鵡失佳人。","鯨鯢人海涸，魑魅棘林幽。","棋声花院閉，幡影石壇高。","地涼清鹤梦，林静肅僧儀。","晚妝留拜月，春睡更生香。","隔谷见雞犬，山苗接楚田。","人家寒食月，花影午时天。","官路好禽声，軒车駐晚程。","南楼山最秀，北路邑偏清。","多病形容五十三，誰鄰借笏趂朝參。","十年太华無知己，只得虛中兩首诗。","看師逸蹟兩師宜，高適歌行李白诗。"]', '诗', 'shi', '', NULL, '句 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b74a409-0c54-4a99-a245-972e4189538a', '送邊上從事', '送邊上從事', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["戎裝佩鏌鎁，走馬逐輕車。","衰草城邊路，殘陽壟上笳。","黃河穿漢界，青塚出胡沙。","提筆男兒事，功名立可誇。"]', '["戎裝佩鏌鎁，走马逐轻车。","衰草城邊路，殘陽壟上笳。","黄河穿漢界，青塚出胡沙。","提笔男兒事，功名立可誇。"]', '诗', 'shi', '', NULL, '送邊上從事 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90fa4bcb-cd80-4581-9b9a-b3585352f32b', '送洛陽崔員外', '送洛陽崔員外', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["塞詔除嵩洛，觀圖見廢興。","城遷周古鼎，地列漢諸陵。","日送歸朝客，時招住嶽僧。","郡齋臺閣滿，公退即吟登。"]', '["塞詔除嵩洛，观圖见廢兴。","城遷周古鼎，地列漢諸陵。","日送归朝客，时招住嶽僧。","郡斋台閣满，公退即吟登。"]', '诗', 'shi', '', NULL, '送洛陽崔員外 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46e44bb-4ccd-4871-96c0-12f553308737', '送人尉黔中', '送人尉黔中', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["盤山行幾驛，水路復通巴。","峽漲三川雪，園開四季花。","公庭飛白鳥，官俸請丹砂。","知尉黔中後，高吟採物華。"]', '["盤山行幾驛，水路复通巴。","峽漲三川雪，园开四季花。","公庭飞白鸟，官俸請丹砂。","知尉黔中後，高吟採物华。"]', '诗', 'shi', '', NULL, '送人尉黔中 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5778262b-2266-4763-bc02-3a4c6755d703', '送宇文虞', '送宇文虞', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["此別欲何往，未言歸故林。","行車新歲近，落日亂山深。","野店寒無客，風巢動有禽。","潛知經目事，大半是愁吟。"]', '["此別欲何往，未言归故林。","行车新歲近，落日亂山深。","野店寒無客，风巢动有禽。","潛知經目事，大半是愁吟。"]', '诗', 'shi', '', NULL, '送宇文虞 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc8ad07-4f52-416f-b7f3-cc2e4d90874e', '題東林寺虎掊泉', '題东林寺虎掊泉', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["勝致通幽感，靈泉有虎掊。","爪擡山脉斷，掌託石心抝。","竹藹疑相近，松陰蓋亦交。","轉令棲遁者，真境逾難拋。"]', '["勝致通幽感，靈泉有虎掊。","爪擡山脉斷，掌託石心抝。","竹藹疑相近，松陰蓋亦交。","轉令棲遁者，真境逾难拋。"]', '诗', 'shi', '', NULL, '題東林寺虎掊泉 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5175c34-da87-4de6-b3bc-a935b346fa8e', '登甘露寺', '登甘露寺', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["盤江上幾層，峭壁半垂藤。","殿鎖南朝像，龕禪外國僧。","海濤摏砌檻，山雨灑窗燈。","日暮疎鐘起，聲聲徹廣陵。"]', '["盤江上幾層，峭壁半垂藤。","殿鎖南朝像，龕禪外国僧。","海濤摏砌檻，山雨灑窗灯。","日暮疎鐘起，声声徹廣陵。"]', '诗', 'shi', '', NULL, '登甘露寺 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18de435e-9774-4859-827c-0bcf1d6532ea', '甘露寺東軒', '甘露寺东軒', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["每日憐晴眺，閑吟只自娛。","山從平地有，水到遠天無。","老樹多封楚，輕烟暗染吳。","雖居此廊下，入戶亦躊躕。"]', '["每日怜晴眺，闲吟只自娛。","山從平地有，水到远天無。","老樹多封楚，轻烟暗染吳。","雖居此廊下，入戶亦躊躕。"]', '诗', 'shi', '', NULL, '甘露寺東軒 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f301fd18-267d-4f8a-90c6-e047caaad7bd', '甘露寺北軒', '甘露寺北軒', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["曉色宜閑望，山風遠益清。","白雲連晉閣，碧樹盡蕪城。","水靜沙痕出，煙消野火平。","最堪佳此境，爲我長詩情。"]', '["晓色宜闲望，山风远益清。","白云連晉閣，碧樹尽蕪城。","水静沙痕出，煙消野火平。","最堪佳此境，爲我长诗情。"]', '诗', 'shi', '', NULL, '甘露寺北軒 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4dea634-027d-45fc-908b-5372ec05fc91', '詠螢', '詠螢', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["熠熠與娟娟，池塘竹樹邊。","亂飛同曳火，成聚却無煙。","微雨灑不滅，清風吹欲燃。","舊曾書按上，頻把作囊懸。"]', '["熠熠與娟娟，池塘竹樹邊。","亂飞同曳火，成聚却無煙。","微雨灑不滅，清风吹欲燃。","旧曾书按上，頻把作囊懸。"]', '诗', 'shi', '', NULL, '詠螢 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bae582b-62ab-47f6-8d66-2f05b9594c1b', '望海', '望海', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["蒼茫空泛日，四顧絕人煙。","半浸中華岸，旁通異域船。","島間應有國，波外恐無天。","欲作乘槎客，翻愁去隔年。"]', '["蒼茫空泛日，四顧絕人煙。","半浸中华岸，旁通異域船。","島间應有国，波外恐無天。","欲作乘槎客，翻愁去隔年。"]', '诗', 'shi', '', NULL, '望海 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e89ddbad-2fc3-4151-870e-cda45036116c', '送楊環校書歸廣南', '送楊环校书归廣南', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["天南行李半波濤，灘樹枝枝拂戲猱。","初著藍衫從遠嶠，乍辭雲署泊輕艘。","山村象踏桄榔葉，海外人收翡翠毛。","名宦兩成歸舊隱，徧尋親友興何饒。"]', '["天南行李半波濤，灘樹枝枝拂戲猱。","初著藍衫從远嶠，乍辞云署泊轻艘。","山村象踏桄榔葉，海外人收翡翠毛。","名宦兩成归旧隐，徧尋親友兴何饒。"]', '诗', 'shi', '', NULL, '送楊環校書歸廣南 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d21ab1-31ff-4123-a86d-b1fdba206429', '經故宅有感', '經故宅有感', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["身沒南荒雨露賒，朱門空鎖舊繁華。","池塘鑿就方通水，桃杏栽成未見花。","異代圖書藏幾篋，傾城羅綺散誰家。","昔年埏埴生靈地，今日生人爲歎嗟。"]', '["身沒南荒雨露賒，朱门空鎖旧繁华。","池塘鑿就方通水，桃杏栽成未见花。","異代圖书藏幾篋，傾城羅綺散誰家。","昔年埏埴生靈地，今日生人爲歎嗟。"]', '诗', 'shi', '', NULL, '經故宅有感 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76c5af8f-e68d-45fe-a0b0-3f1f0f029dc4', '送入蕃使', '送入蕃使', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["獵獵旗幡過大荒，敕書猶帶御烟香。","滹沱河凍軍迴探，邏逤城孤雁著行。","遠寨風狂移帳幕，平沙日晚臥牛羊。","早終冊禮朝天闕，莫遣虬髭染塞霜。"]', '["獵獵旗幡過大荒，敕书猶带御烟香。","滹沱河凍軍迴探，邏逤城孤雁著行。","远寨风狂移帳幕，平沙日晚臥牛羊。","早終冊禮朝天闕，莫遣虬髭染塞霜。"]', '诗', 'shi', '', NULL, '送入蕃使 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee815980-f7ce-4628-bd99-698fff712372', '白石潭秋霽作', '白石潭秋霽作', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["潭心烟霧破斜暉，殷殷雷聲隔翠微。","崖蹙盤渦翻蜃窟，灘吹白石上漁磯。","陵風舴艋謳啞去，出水鸕鷀薄泊飛。","秋霽更誰同此望，遠鐘時見一僧歸。"]', '["潭心烟霧破斜暉，殷殷雷声隔翠微。","崖蹙盤渦翻蜃窟，灘吹白石上漁磯。","陵风舴艋謳啞去，出水鸕鷀薄泊飞。","秋霽更誰同此望，远鐘时见一僧归。"]', '诗', 'shi', '', NULL, '白石潭秋霽作 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b104e53e-499e-4cc7-9366-789933cd7f7a', '題金陵栖霞寺贈月公', '題金陵栖霞寺贈月公', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["明家不要買山錢，施作清池種白蓮。","松檜老依雲外地，樓臺深鎖洞中天。","風經絕頂迴疎雨，石倚危屏挂落泉。","欲結茅菴伴師住，肯饒多少薜蘿煙。"]', '["明家不要買山錢，施作清池種白蓮。","松檜老依云外地，楼台深鎖洞中天。","风經絕頂迴疎雨，石倚危屏挂落泉。","欲結茅菴伴師住，肯饒多少薜蘿煙。"]', '诗', 'shi', '', NULL, '題金陵栖霞寺贈月公 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae94ce0-264f-41e6-9b8e-e3e19bbe52d9', '嘲段成式', '嘲段成式', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["蹙鞠且徒爲，寧如目送時。","報讐慙選耎，存想恨逶遲。","促坐疑辟咡，銜盃強朵頤。","恣情窺窈窕，曾恃好風姿。","色授應難奪，神交願莫辭。","請君看曲譜，不負少年期。"]', '["蹙鞠且徒爲，寧如目送时。","報讐慙選耎，存想恨逶遲。","促坐疑辟咡，銜盃強朵頤。","恣情窺窈窕，曾恃好风姿。","色授應难奪，神交願莫辞。","請君看曲譜，不負少年期。"]', '诗', 'shi', '', NULL, '嘲段成式 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04daf8cf-e075-4739-9ad3-e8e092d9e8aa', '送江州薛尚書', '送江州薛尚书', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["匡廬千萬峯，影匝郡城中。","忽佩虎符去，遙疑鳥道通。","煙霞時滿郭，波浪暮連空。","樹翳樓臺月，帆飛鼓角風。","郡齋多嶽客，鄉戶半漁翁。","王事行春外，題詩寄遠公。"]', '["匡廬千万峯，影匝郡城中。","忽佩虎符去，遙疑鸟道通。","煙霞时满郭，波浪暮連空。","樹翳楼台月，帆飞鼓角风。","郡斋多嶽客，乡戶半漁翁。","王事行春外，題诗寄远公。"]', '诗', 'shi', '', NULL, '送江州薛尚書 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ae1def-f4ff-45f2-a4a8-2d3ba4745b2b', '津頭望白水', '津头望白水', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["晴江暗漲岸吹沙，山畔船衝樹杪斜。","城郭半淹橋市鬧，鷺鷥繚繞入人家。"]', '["晴江暗漲岸吹沙，山畔船衝樹杪斜。","城郭半淹橋市鬧，鷺鷥繚繞入人家。"]', '诗', 'shi', '', NULL, '津頭望白水 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0c0e40-3073-468f-9804-5586aced00dc', '公子行', '公子行', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["青山薄薄漏春風，日暮鳴鞭柳影中。","回望玉樓人不見，酒旗深處勒花驄。"]', '["青山薄薄漏春风，日暮鳴鞭柳影中。","回望玉楼人不见，酒旗深处勒花驄。"]', '诗', 'shi', '', NULL, '公子行 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('614d4b1d-0e9d-4f5e-a27e-30698fea9150', '看牡丹贈段成式', '看牡丹贈段成式', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["金蘂霞英疊彩香，初疑少女出蘭房。","逡巡又是一年別，寄語集仙呼索郎。"]', '["金蘂霞英叠彩香，初疑少女出蘭房。","逡巡又是一年別，寄語集仙呼索郎。"]', '诗', 'shi', '', NULL, '看牡丹贈段成式 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65458e44-c424-4a6b-a163-653449878f4a', '以人葠遺段成式', '以人葠遺段成式', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["人形上品傳方志，我得真英自紫團。","慙非叔子空持藥，更請伯言審細看。"]', '["人形上品傳方志，我得真英自紫團。","慙非叔子空持藥，更請伯言審細看。"]', '诗', 'shi', '', NULL, '以人葠遺段成式 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('765d2cc2-4974-4991-91b4-ba2d5e8a173c', '和段成式 一', '和段成式 一', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["迴簪轉黛喜猜防，粉署裁詩助酒狂。","若遇仙丹偕羽化，便隨蕭史亦何傷。"]', '["迴簪轉黛喜猜防，粉署裁诗助酒狂。","若遇仙丹偕羽化，便隨蕭史亦何傷。"]', '诗', 'shi', '', NULL, '和段成式 一 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a55f02-b115-481b-a44d-ebac1bb22af3', '和段成式 二', '和段成式 二', '5eb3ffa4-fab2-42bc-996b-25ad8d1ece98', '唐', '["玉樹瓊筵映彩霞，澄虛樓閣似仙家。","只緣存想歸蘭室，不向春風看夜花。"]', '["玉樹瓊筵映彩霞，澄虛楼閣似仙家。","只緣存想归蘭室，不向春风看夜花。"]', '诗', 'shi', '', NULL, '和段成式 二 周繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c867101-ade7-4ee6-b24b-d2eaa77eae09', '雜興', '杂兴', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["兩葉能蔽目，雙豆能塞聰。","理身不知道，將爲天地聾。","擾擾造化內，茫茫天地中。","苟或有所願，毛髪亦不容。"]', '["兩葉能蔽目，雙豆能塞聰。","理身不知道，將爲天地聾。","擾擾造化內，茫茫天地中。","苟或有所願，毛髪亦不容。"]', '诗', 'shi', '', NULL, '雜興 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df61077-fba8-4222-8053-1fa969c5adab', '雜怨 一', '杂怨 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["生在綺羅下，豈識漁陽道。","良人自戍來，夜夜夢中到。","漁陽萬里遠，近於中門限。","中門踰有時，漁陽常在眼。"]', '["生在綺羅下，豈識漁陽道。","良人自戍来，夜夜梦中到。","漁陽万里远，近於中门限。","中门踰有时，漁陽常在眼。"]', '诗', 'shi', '', NULL, '雜怨 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f79dbe-389c-4381-9917-9d33cbf921ba', '雜怨 二', '杂怨 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["君淚濡羅巾，妾淚滴路塵。","羅巾今在手，日得隨妾身。","路塵如因風，得上君車輪。"]', '["君泪濡羅巾，妾泪滴路塵。","羅巾今在手，日得隨妾身。","路塵如因风，得上君车輪。"]', '诗', 'shi', '', NULL, '雜怨 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d8e2ba7-ba52-44c7-83d4-06dfaa2339d1', '行路難', '行路难', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["莫言行路難，夷狄如中國。","謂言骨肉親，中門如異域。","出處全在人，路亦無通塞。","門前兩條轍，何處去不得。"]', '["莫言行路难，夷狄如中国。","謂言骨肉親，中门如異域。","出处全在人，路亦無通塞。","门前兩條轍，何处去不得。"]', '诗', 'shi', '', NULL, '行路難 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5763b85-5f21-41dd-ba9b-42e79993afed', '大垂手', '大垂手', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["金刀翦輕雲，盤用黃金縷。","裝束趙飛燕，教來掌上舞。","舞罷飛燕死，片片隨風去。"]', '["金刀翦轻云，盤用黄金縷。","裝束趙飞燕，教来掌上舞。","舞罷飞燕死，片片隨风去。"]', '诗', 'shi', '', NULL, '大垂手 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469e6a93-d96f-45a9-90db-e131187c4c4a', '空城雀', '空城雀', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["一雀入官倉，所食能損幾。","所慮往復頻，官倉乃害爾。","魚網不在天，鳥網不在水。","飲啄要自然，何必空城裏。"]', '["一雀入官倉，所食能損幾。","所慮往复頻，官倉乃害爾。","鱼網不在天，鸟網不在水。","饮啄要自然，何必空城裏。"]', '诗', 'shi', '', NULL, '空城雀 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3e9cc5-e2a2-412d-a884-4c17d072c5a2', '胡無人行', '胡無人行', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["男兒徇大義，立節不沽名。","腰間懸陸離，大歌胡無行。","不讀戰國書，不覽黃石經。","醉臥咸陽樓，夢入受降城。","更願生羽翼，飛身入青冥。","請攜天子劒，斫下旄頭星。","自然胡無人，雖有無戰爭。","悠哉典屬國，驅羊老一生。"]', '["男兒徇大義，立節不沽名。","腰间懸陸離，大歌胡無行。","不读戰国书，不覽黄石經。","醉臥咸陽楼，梦入受降城。","更願生羽翼，飞身入青冥。","請携天子劒，斫下旄头星。","自然胡無人，雖有無戰爭。","悠哉典屬国，驱羊老一生。"]', '诗', 'shi', '', NULL, '胡無人行 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eea5bcf-1f67-4a9f-b70f-d60dcea99111', '詠田家', '詠田家', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["二月賣新絲，五月糶新穀。","醫得眼前瘡，剜却心頭肉。","我願君王心，化作光明燭。","不照綺羅筵，只照逃亡屋。"]', '["二月賣新絲，五月糶新穀。","醫得眼前瘡，剜却心头肉。","我願君王心，化作光明燭。","不照綺羅筵，只照逃亡屋。"]', '诗', 'shi', '', NULL, '詠田家 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be65fed3-3677-4f79-84fb-4dd6cfdc19c4', '燕臺二首 一', '燕台二首 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["燕臺累黃金，上欲招儒雅。","貴得賢士來，更下於隗者。","自然樂毅徒，趨風走天下。","何必馳鳳書，旁求向林野。"]', '["燕台累黄金，上欲招儒雅。","貴得賢士来，更下於隗者。","自然乐毅徒，趨风走天下。","何必驰鳳书，旁求向林野。"]', '诗', 'shi', '', NULL, '燕臺二首 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc32e5a-8518-496b-a4a5-b4c995251763', '燕臺二首 二', '燕台二首 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["燕臺高百尺，燕滅臺亦平。","一種是亡國，猶得禮賢名。","何似章華畔，空餘禾黍生。"]', '["燕台高百尺，燕滅台亦平。","一種是亡国，猶得禮賢名。","何似章华畔，空餘禾黍生。"]', '诗', 'shi', '', NULL, '燕臺二首 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6c2eb5-4930-4b60-a227-7f94fb6a28a8', '古興', '古兴', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["片玉一塵輕，粒粟山丘重。","唐虞貴民食，秪是勤播種。","前聖後聖同，今人古人共。","一歲如苦饑，金玉何所用。"]', '["片玉一塵轻，粒粟山丘重。","唐虞貴民食，秪是勤播種。","前聖後聖同，今人古人共。","一歲如苦饑，金玉何所用。"]', '诗', 'shi', '', NULL, '古興 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f81a43-5b23-4871-a06e-8660db415ad8', '勸酒二首 一', '勸酒二首 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["白日無定影，清江無定波。","人無百年壽，百年復如何。","堂上陳美酒，堂下列笙歌。","與君入醉鄉，醉鄉樂天和。","歲歲松栢茂，日日丘陵多。","君看終南山，萬古青峨峨。"]', '["白日無定影，清江無定波。","人無百年壽，百年复如何。","堂上陳美酒，堂下列笙歌。","與君入醉乡，醉乡乐天和。","歲歲松栢茂，日日丘陵多。","君看終南山，万古青峨峨。"]', '诗', 'shi', '', NULL, '勸酒二首 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200b9d38-5f06-453f-83cb-197fdceeb8c1', '勸酒二首 二', '勸酒二首 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["灞上送行客，聽唱行客歌。","適來橋下水，已作渭川波。","人間榮樂少，四海別離多。","但恐別離淚，自成苦水河。","勸爾一杯酒，所贈無餘多。"]', '["灞上送行客，听唱行客歌。","適来橋下水，已作渭川波。","人间榮乐少，四海別離多。","但恐別離泪，自成苦水河。","勸爾一杯酒，所贈無餘多。"]', '诗', 'shi', '', NULL, '勸酒二首 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e75828-7908-4a38-bfdf-d491496721d1', '飲酒樂', '饮酒乐', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["日月似有事，一夜行一周。","草木猶須老，人生得無愁。","一飲解百結，再飲破百憂。","白髮欺貧賤，不入醉人頭。","我願東海水，盡向杯中流。","安得阮步兵，同入醉鄉遊。"]', '["日月似有事，一夜行一周。","草木猶須老，人生得無愁。","一饮解百結，再饮破百憂。","白髮欺貧賤，不入醉人头。","我願东海水，尽向杯中流。","安得阮步兵，同入醉乡游。"]', '诗', 'shi', '', NULL, '飲酒樂 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d6f052-2dcf-4a7b-be9e-773e4c6f6dd1', '公子行二首 一', '公子行二首 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["漢代多豪族，恩深益驕逸。","走馬踏殺人，街吏不敢詰。","紅樓宴青春，數里望雲蔚。","金缸焰勝畫，不畏落暉疾。","美人盡如月，南威莫能匹。","芙蓉自天來，不向水中出。","飛瓊奏雲和，碧簫吹鳳質。","唯恨魯陽死，無人駐白日。"]', '["漢代多豪族，恩深益驕逸。","走马踏殺人，街吏不敢詰。","紅楼宴青春，數里望云蔚。","金缸焰勝畫，不畏落暉疾。","美人尽如月，南威莫能匹。","芙蓉自天来，不向水中出。","飞瓊奏云和，碧簫吹鳳質。","唯恨魯陽死，無人駐白日。"]', '诗', 'shi', '', NULL, '公子行二首 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2805b567-edfc-4bf4-8f9a-964906968b1c', '公子行二首 二', '公子行二首 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["花樹出墻頭，花裏誰家樓。","一行書不讀，身封萬戶侯。","美人樓上歌，不是古涼州。"]', '["花樹出墻头，花裏誰家楼。","一行书不读，身封万戶侯。","美人楼上歌，不是古涼州。"]', '诗', 'shi', '', NULL, '公子行二首 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d0dee6-3e15-4931-9984-4c7b1e1f8583', '短歌', '短歌', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["八月木陰薄，十葉三墮枝。","人生過五十，亦已同此時。","朝出東郭門，嘉樹鬱參差。","暮出西郭門，原草已離披。","南鄰好臺榭，北鄰善歌吹。","榮華忽銷歇，四顧令人悲。","生死與榮辱，四者乃常期。","古人耻其名，沒世無人知。","無言鬢似霜，勿謂事如絲。","耆年無一善，何殊食乳兒。"]', '["八月木陰薄，十葉三墮枝。","人生過五十，亦已同此时。","朝出东郭门，嘉樹鬱參差。","暮出西郭门，原草已離披。","南鄰好台榭，北鄰善歌吹。","榮华忽銷歇，四顧令人悲。","生死與榮辱，四者乃常期。","古人耻其名，沒世無人知。","無言鬢似霜，勿謂事如絲。","耆年無一善，何殊食乳兒。"]', '诗', 'shi', '', NULL, '短歌 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366e820c-e3bb-4276-bc10-c8daa92aad19', '過比干墓', '過比干墓', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["殷辛帝天下，厭爲天下尊。","乾綱既一斷，賢愚無二門。","佞是福身本，忠作喪己源。","餓虎不食子，人無骨肉恩。","日影不入地，下埋冤死魂。","腐骨不爲土，應作石木根。","余來過此鄉，下馬弔此墳。","靜念君臣間，有道誰敢論。"]', '["殷辛帝天下，厭爲天下尊。","乾綱既一斷，賢愚無二门。","佞是福身本，忠作喪己源。","餓虎不食子，人無骨肉恩。","日影不入地，下埋冤死魂。","腐骨不爲土，應作石木根。","余来過此乡，下马弔此墳。","静念君臣间，有道誰敢論。"]', '诗', 'shi', '', NULL, '過比干墓 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3dd335-205d-45dc-9818-8413ff9dc59d', '住京寄同志', '住京寄同志', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["在京如在道，日日先雞起。","不離十二街，日行一百里。","役役大塊上，周朝復秦市。","貴賤與賢愚，古今同一軌。","白兔落天西，赤鵶飛海底。","一日復一日，日日無終始。","自嫌性如石，不達榮辱理。","試問九十翁，吾今尚如此。"]', '["在京如在道，日日先雞起。","不離十二街，日行一百里。","役役大塊上，周朝复秦市。","貴賤與賢愚，古今同一軌。","白兔落天西，赤鵶飞海底。","一日复一日，日日無終始。","自嫌性如石，不達榮辱理。","試问九十翁，吾今尚如此。"]', '诗', 'shi', '', NULL, '住京寄同志 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932552dc-b1e3-45cd-a80f-309b37db4acf', '贈農', '贈農', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["勸爾勤耕田，盈爾倉中粟。","勸爾無伐桑，減爾身上服。","清霜一委地，萬草色不綠。","狂風一飄林，萬葉不著木。","青春如不耕，何以自拘束。"]', '["勸爾勤耕田，盈爾倉中粟。","勸爾無伐桑，減爾身上服。","清霜一委地，万草色不綠。","狂风一飄林，万葉不著木。","青春如不耕，何以自拘束。"]', '诗', 'shi', '', NULL, '贈農 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e4458c-f82c-4c43-a3ca-b08f0c8f7e46', '客有追歎後時者作詩勉之', '客有追歎後时者作诗勉之', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["後達多晚榮，速得多疾傾。","君看構大廈，何曾一日成。","在暖須在桑，在飽須在耕。","君子貴弘道，道弘無不亨。","太陽垂好光，毛髪悉見形。","我亦二十年，直似戴盆行。","荆山產美玉，石石皆堅貞。","未必盡有玉，玉且間石生。","精衛一微物，猶恐填海平。"]', '["後達多晚榮，速得多疾傾。","君看構大廈，何曾一日成。","在暖須在桑，在飽須在耕。","君子貴弘道，道弘無不亨。","太陽垂好光，毛髪悉见形。","我亦二十年，直似戴盆行。","荆山產美玉，石石皆堅貞。","未必尽有玉，玉且间石生。","精衛一微物，猶恐填海平。"]', '诗', 'shi', '', NULL, '客有追歎後時者作詩勉之 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea71c69-cbd6-4e16-bdbc-29876ca356d5', '訪嵩陽道士不遇', '訪嵩陽道士不遇', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["先生五岳遊，文焰滅金鼎。","日下鶴過時，人間空落影。","常言一粒藥，不隨死生境。","何當列禦寇，去問仙人請。"]', '["先生五岳游，文焰滅金鼎。","日下鹤過时，人间空落影。","常言一粒藥，不隨死生境。","何當列禦寇，去问仙人請。"]', '诗', 'shi', '', NULL, '訪嵩陽道士不遇 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efa9734-5a13-4087-a59c-49a4f0fb63c3', '早發鄴北經古城', '早發鄴北經古城', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["微月東南明，雙牛耕古城。","但耕古城地，不知古城名。","當昔置此城，豈料今日耕。","蔓草已離披，狐兔何縱橫。","秋雲零落散，秋風蕭條生。","對古良可歎，念今轉傷情。","古人已冥冥，今人又營營。","不知馬蹄下，誰家舊臺亭。"]', '["微月东南明，雙牛耕古城。","但耕古城地，不知古城名。","當昔置此城，豈料今日耕。","蔓草已離披，狐兔何縱橫。","秋云零落散，秋风蕭條生。","对古良可歎，念今轉傷情。","古人已冥冥，今人又營營。","不知马蹄下，誰家旧台亭。"]', '诗', 'shi', '', NULL, '早發鄴北經古城 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ba9d47-b06b-4146-a0f7-ffbb67a35705', '題賈氏林泉', '題賈氏林泉', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["市朝束名利，林泉繫清通。","豈知黃塵內，迥有白雲蹤。","輕流逗密蓧，直榦入寬空。","高吟五君詠，疑對九華峰。","我知種竹心，欲扇清涼風。","我知決泉意，將明濟物功。","有琴不張弦，衆星列梧桐。","須知澹泊聽，聲在無聲中。","地非樵者路，武陵又何逢。","祗慮迷所歸，池上日西東。"]', '["市朝束名利，林泉繫清通。","豈知黄塵內，迥有白云蹤。","轻流逗密蓧，直榦入寬空。","高吟五君詠，疑对九华峰。","我知種竹心，欲扇清涼风。","我知決泉意，將明濟物功。","有琴不張弦，衆星列梧桐。","須知澹泊听，声在無声中。","地非樵者路，武陵又何逢。","祗慮迷所归，池上日西东。"]', '诗', 'shi', '', NULL, '題賈氏林泉 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e09623-9ab1-4f2f-8d40-0888d8bd88f1', '送友人歸江南', '送友人归江南', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["皇州五更鼓，月落西南維。","此時有行客，別我孤舟歸。","上國身無主，下第誠可悲。"]', '["皇州五更鼓，月落西南維。","此时有行客，別我孤舟归。","上国身無主，下第誠可悲。"]', '诗', 'shi', '', NULL, '送友人歸江南 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a22f40-7a74-4c1a-9cf8-b113db2acc92', '秋夕', '秋夕', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["日往無復見，秋堂暮乃學。","玄髪不知白，曉入寒銅覺。","爲才未離羣，有玉猶在璞。","誰把碧桐枝，刻作雲門樂。"]', '["日往無复见，秋堂暮乃学。","玄髪不知白，晓入寒銅覺。","爲才未離羣，有玉猶在璞。","誰把碧桐枝，刻作云门乐。"]', '诗', 'shi', '', NULL, '秋夕 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3b4935-f037-41ba-b264-2732c514a28e', '哭劉駕博士', '哭劉駕博士', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["出門四顧望，此日何徘徊。","終南舊山色，夫子安在哉。","君詩如門戶，夕閉晝還開。","君名如四時，春盡夏復來。","原野多丘陵，纍纍如高臺。","君墳須數尺，誰與夫子偕。"]', '["出门四顧望，此日何徘徊。","終南旧山色，夫子安在哉。","君诗如门戶，夕閉晝還开。","君名如四时，春尽夏复来。","原野多丘陵，纍纍如高台。","君墳須數尺，誰與夫子偕。"]', '诗', 'shi', '', NULL, '哭劉駕博士 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1417d6-912a-4606-a798-d8971da31a7e', '公子家', '公子家', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["種花滿西園，花發青樓道。","花下一禾生，去之爲惡草。"]', '["種花满西园，花發青楼道。","花下一禾生，去之爲惡草。"]', '诗', 'shi', '', NULL, '公子家 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91276d5a-1844-40ec-a102-a41eaab21c12', '田家二首 一', '田家二首 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["父耕原上田，子劚山下荒。","六月禾未秀，官家已修倉。"]', '["父耕原上田，子劚山下荒。","六月禾未秀，官家已修倉。"]', '诗', 'shi', '', NULL, '田家二首 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a50612-df8c-44a5-8a19-f455cc185195', '田家二首 二', '田家二首 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["鋤田當日午，汗滴禾下土。","誰念盤中餐，粒粒皆辛苦。"]', '["鋤田當日午，汗滴禾下土。","誰念盤中餐，粒粒皆辛苦。"]', '诗', 'shi', '', NULL, '田家二首 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59d9e42-871a-4d57-8515-aaf7622af1c4', '雜怨', '杂怨', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["良人昨日去，明月又不圓。","別時各有淚，零落青樓前。"]', '["良人昨日去，明月又不圓。","別时各有泪，零落青楼前。"]', '诗', 'shi', '', NULL, '雜怨 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7763540-977d-4290-8d99-2e0ad16af9d6', '烏夜啼', '烏夜啼', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["衆鳥各歸枝，烏烏爾不棲。","還應知妾恨，故向綠窗啼。"]', '["衆鸟各归枝，烏烏爾不棲。","還應知妾恨，故向綠窗啼。"]', '诗', 'shi', '', NULL, '烏夜啼 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e512a19-210d-4612-8dc5-1d9b6ae52610', '起夜來', '起夜来', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["念遠心如燒，不覺中夜起。","桃花帶露泛，立在月明裏。"]', '["念远心如燒，不覺中夜起。","桃花带露泛，立在月明裏。"]', '诗', 'shi', '', NULL, '起夜來 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c52bf9-7672-44a1-a618-92b26b91fde1', '古別離', '古別離', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["欲別牽郎衣，問郎遊何處。","不恨歸日遲，莫向臨邛去。"]', '["欲別牽郎衣，问郎游何处。","不恨归日遲，莫向臨邛去。"]', '诗', 'shi', '', NULL, '古別離 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5237a4cc-a1d5-48a6-9ec3-72a4b400dea0', '長安道', '长安道', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["此地無駐馬，夜中猶走輪。","所以路傍草，少於衣上塵。"]', '["此地無駐马，夜中猶走輪。","所以路傍草，少於衣上塵。"]', '诗', 'shi', '', NULL, '長安道 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab09e37b-0114-49f7-ab82-56480afb3d9e', '遊子行', '游子行', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["萱草生堂階，遊子行天涯。","慈親倚門望，不見萱草花。"]', '["萱草生堂階，游子行天涯。","慈親倚门望，不见萱草花。"]', '诗', 'shi', '', NULL, '遊子行 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d813c029-0b6d-4b89-b4ba-5d6d725e73d9', '聞人說海北事有感', '闻人说海北事有感', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["故鄉歸路隔高雷，見說年來事可哀。","村落日中眠虎豹，田園雨後長蒿萊。","海隅久已無春色，地底真成有劫灰。","荆棘滿山行不得，不知當日是誰栽。"]', '["故乡归路隔高雷，见说年来事可哀。","村落日中眠虎豹，田园雨後长蒿萊。","海隅久已無春色，地底真成有劫灰。","荆棘满山行不得，不知當日是誰栽。"]', '诗', 'shi', '', NULL, '聞人說海北事有感 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0830243-f9c8-4261-9aeb-888cd8c84283', '華清詞', '华清词', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["祥雲皓鶴盤碧空，喬松稍稍韻微風。","絳節影來，朱旛響丁東。","相公清齋朝蘂宮，太上符籙龍蛇蹤。","散花天女侍香童，隔煙遙望見雲水。","彈璈吹鳳清瓏瓏，丹砂黃金世可度。","願啓一言告仙翁，道門弟子山中客。","長向山中禮空碧，九色真龍上漢時，願把霓幢引煙策。"]', '["祥云皓鹤盤碧空，喬松稍稍韻微风。","絳節影来，朱旛响丁东。","相公清斋朝蘂宮，太上符籙龙蛇蹤。","散花天女侍香童，隔煙遙望见云水。","彈璈吹鳳清瓏瓏，丹砂黄金世可度。","願啓一言告仙翁，道门弟子山中客。","长向山中禮空碧，九色真龙上漢时，願把霓幢引煙策。"]', '诗', 'shi', '', NULL, '華清詞 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e85dbe-1c8f-4964-a82e-d01a8f9ba1e2', '天威行', '天威行', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["蠻嶺高，蠻海闊，去舸迴艘投此歇。","一夜舟人得夢間，草草相呼一時發。","颶風忽起雲顛狂，波濤擺掣魚龍殭。","海神怕急上岸走，山燕股慄入石藏。","金蛇飛狀霍閃過，白日倒挂銀繩長。","轟轟砢砢雷車轉，霹靂一聲天地戰。","風定雲開始望看，萬里青山分兩片。","車遙遙，馬闐闐，平如砥，直如弦。","雲南八國萬部落，皆知此路來朝天。","耿恭拜出井底水，廣利刺開山上泉。","若論終古濟物意，二將之功皆小焉。"]', '["蠻嶺高，蠻海闊，去舸迴艘投此歇。","一夜舟人得梦间，草草相呼一时發。","颶风忽起云顛狂，波濤擺掣鱼龙殭。","海神怕急上岸走，山燕股慄入石藏。","金蛇飞狀霍閃過，白日倒挂銀繩长。","轟轟砢砢雷车轉，霹靂一声天地戰。","风定云开始望看，万里青山分兩片。","车遙遙，马闐闐，平如砥，直如弦。","云南八国万部落，皆知此路来朝天。","耿恭拜出井底水，廣利刺开山上泉。","若論終古濟物意，二將之功皆小焉。"]', '诗', 'shi', '', NULL, '天威行 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48356297-d07a-48ad-a8cd-d7c91bcfc8b8', '築城篇', '築城篇', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["三十六里西川地，圍遶城郭峨天橫。","一家人率一口甓，版築纔興城已成。","役夫登登無倦色，饌飽觴酣方暫息。","不假神龜出指蹤，盡憑心匠爲籌畫。","畫閣團團真鐵甕，堵闊巉巖齊石壁。","風吹四面旌旗動，火焰相燒滿天赤。","散花樓晚挂殘虹，濯錦秋江澄倒碧。","西川父老賀子孫，從茲始是中華人。"]', '["三十六里西川地，圍遶城郭峨天橫。","一家人率一口甓，版築纔兴城已成。","役夫登登無倦色，饌飽觴酣方暫息。","不假神龟出指蹤，尽憑心匠爲籌畫。","畫閣團團真鐵甕，堵闊巉巖齊石壁。","风吹四面旌旗动，火焰相燒满天赤。","散花楼晚挂殘虹，濯錦秋江澄倒碧。","西川父老賀子孫，從茲始是中华人。"]', '诗', 'shi', '', NULL, '築城篇 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a701ec-0276-4364-be88-e02b67c39226', '蘇君廳觀韓幹馬障歌', '蘇君廳观韓幹马障歌', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["杜甫歌詩吟不足，可憐曹霸丹青曲。","直言弟子韓幹馬，畫馬無骨但有肉。","今日披圖見筆跡，始知甫也真凡目。","秦王學士居武功，六印名家聲價雄。","乃孫屈跡寧百里，好奇學古有祖風。","竹廳斜日弈碁散，延我直入書齋中。","屹然六幅古屏上，歘見胡人牽入天廐之神龍。","麟鬐鳳臆真相似，秋竹慘慘披兩耳。","輕勻杏蘂糝皮毛，細撚銀絲插騣尾。","思量動步應千里，誰見初離渥洼水。","眼前只欠燕雪飛，蹄下如聞朔風起。","朱崖謫掾從亡歿，更有何人鑒奇物。","當時若遇燕昭王，肯把千金買枯骨。"]', '["杜甫歌诗吟不足，可怜曹霸丹青曲。","直言弟子韓幹马，畫马無骨但有肉。","今日披圖见笔跡，始知甫也真凡目。","秦王学士居武功，六印名家声價雄。","乃孫屈跡寧百里，好奇学古有祖风。","竹廳斜日弈碁散，延我直入书斋中。","屹然六幅古屏上，歘见胡人牽入天廐之神龙。","麟鬐鳳臆真相似，秋竹慘慘披兩耳。","轻勻杏蘂糝皮毛，細撚銀絲插騣尾。","思量动步應千里，誰见初離渥洼水。","眼前只欠燕雪飞，蹄下如闻朔风起。","朱崖謫掾從亡歿，更有何人鑒奇物。","當时若遇燕昭王，肯把千金買枯骨。"]', '诗', 'shi', '', NULL, '蘇君廳觀韓幹馬障歌 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7210ac8-7fc6-4374-b555-dfb6d6d3e372', '苔歌', '苔歌', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["檻前溪奪秋空色，百丈潭心數砂礫。","松筠條條長碧苔，苔色碧於溪水碧。","波迴梳開孔雀尾，根細貼著盤陀石。","撥浪輕拈出少時，一髻濃煙三四尺。","山光日華亂相射，靜縷蘭鬐勻襞積。","試把臨流抖擻看，琉璃珠子淚雙滴。","如看玉女洗頭處，解破雲鬟收未得。","即是仙宮欲製六銖衣，染絲未倩鮫人織。","採之不敢盈筐篋，苦怕龍神河伯惜。","瓊蘇玉鹽爛漫煮，嚥入丹田續靈液。","會待功成插翅飛，蓬萊頂上尋仙客。"]', '["檻前溪奪秋空色，百丈潭心數砂礫。","松筠條條长碧苔，苔色碧於溪水碧。","波迴梳开孔雀尾，根細貼著盤陀石。","撥浪轻拈出少时，一髻濃煙三四尺。","山光日华亂相射，静縷蘭鬐勻襞積。","試把臨流抖擻看，琉璃珠子泪雙滴。","如看玉女洗头处，解破云鬟收未得。","即是仙宮欲製六銖衣，染絲未倩鮫人织。","採之不敢盈筐篋，苦怕龙神河伯惜。","瓊蘇玉鹽爛漫煮，嚥入丹田續靈液。","會待功成插翅飞，蓬萊頂上尋仙客。"]', '诗', 'shi', '', NULL, '苔歌 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56a0c29-f1b5-4190-a0f9-a0ba16776cae', '池陽醉歌贈匡廬處士姚巖傑', '池陽醉歌贈匡廬处士姚巖傑', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["九華太守行春罷，高絳紅筵壓花榭。","四面繁英拂檻開，帖雪團霞墜枝亞。","空中焰若燒藍天，萬里滑靜無纖煙。","弦索緊快管聲脆，急曲碎拍聲相連。","主人憐才多傾興，許客酣歌露真性。","春酎香濃枝盞黏，一醉有時三日病。","黿潭鱗粉解不去，鴉嶺蘂花澆不醒。","肺枯似著爐鞲煽，腦熱如遭鎚鑿釘。","蒙溪先生梁公孫，忽然示我十軸文。","展開一卷讀一首，四顧特地無涯垠。","又開一軸讀一帙，酒病豁若風驅雲。","文鋒斡破造化窟，心刃掘出興亡根。","經疾史恙萬片恨，墨炙筆針如有神。","呵叱潘陸鄙瑣屑，提挈揚孟歸孔門。","時時說及開元理，家風颯颯吹人耳。","吳[兢]纂出升平源，十事分明鋪在紙。","裔孫才業今如此，誰人爲奏明天子。","鑾駕何當獵左馮，神鷹一擲望千里。","戲操狂翰涴蠻牋，傍人莫笑我率然。"]', '["九华太守行春罷，高絳紅筵壓花榭。","四面繁英拂檻开，帖雪團霞墜枝亞。","空中焰若燒藍天，万里滑静無纖煙。","弦索緊快管声脆，急曲碎拍声相連。","主人怜才多傾兴，許客酣歌露真性。","春酎香濃枝盞黏，一醉有时三日病。","黿潭鱗粉解不去，鴉嶺蘂花澆不醒。","肺枯似著爐鞲煽，腦熱如遭鎚鑿釘。","蒙溪先生梁公孫，忽然示我十軸文。","展开一卷读一首，四顧特地無涯垠。","又开一軸读一帙，酒病豁若风驱云。","文鋒斡破造化窟，心刃掘出兴亡根。","經疾史恙万片恨，墨炙笔針如有神。","呵叱潘陸鄙瑣屑，提挈揚孟归孔门。","时时说及开元理，家风颯颯吹人耳。","吳[兢]纂出升平源，十事分明鋪在紙。","裔孫才業今如此，誰人爲奏明天子。","鑾駕何當獵左馮，神鷹一擲望千里。","戲操狂翰涴蠻牋，傍人莫笑我率然。"]', '诗', 'shi', '', NULL, '池陽醉歌贈匡廬處士姚巖傑 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95477829-6273-4f85-a0b8-d5bf3c07e507', '詠柳二首 一', '詠柳二首 一', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["帶露含煙處處垂，綻黃搖綠嫩參差。","長堤未見風飄絮，廣陌初憐日映絲。","斜傍畫筵偷舞態，低臨粧閣學愁眉。","離亭不放到春暮，折盡拂簷千萬枝。"]', '["带露含煙处处垂，綻黄搖綠嫩參差。","长堤未见风飄絮，廣陌初怜日映絲。","斜傍畫筵偷舞態，低臨粧閣学愁眉。","離亭不放到春暮，折尽拂簷千万枝。"]', '诗', 'shi', '', NULL, '詠柳二首 一 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f496ea26-55a4-4871-9124-1686c08a4ae4', '詠柳二首 二', '詠柳二首 二', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["閑花野草總爭新，眉皺絲乾獨不勻。","乞取東風殘氣力，莫教虛度一年春。"]', '["闲花野草總爭新，眉皺絲乾独不勻。","乞取东风殘氣力，莫教虛度一年春。"]', '诗', 'shi', '', NULL, '詠柳二首 二 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755f481e-df48-4cc6-a457-f376783f11f6', '宴邊將', '宴邊將', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一曲梁州金石清，邊風蕭颯動江城。","座中有老沙場客，橫笛休吹塞上聲。"]', '["一曲梁州金石清，邊风蕭颯动江城。","座中有老沙場客，橫笛休吹塞上声。"]', '诗', 'shi', '', NULL, '宴邊將 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec6ccc2-422a-40f1-8d99-9832cf0b2687', '郢州即事', '郢州即事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["孤城臨遠水，千里見寒山。","白雪無人唱，滄洲盡日閑。","鳥歸殘燒外，帆出斷雲間。","此地秋風起，應隨計吏還。"]', '["孤城臨远水，千里见寒山。","白雪無人唱，滄洲尽日闲。","鸟归殘燒外，帆出斷云间。","此地秋风起，應隨計吏還。"]', '诗', 'shi', '', NULL, '郢州即事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f41f985-161d-4afb-a4c2-23f1698aa420', '送賓貢金夷吾奉使歸本國', '送賓貢金夷吾奉使归本国', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["渡海登仙籍，還家備漢儀。","孤舟無岸泊，萬里有星隨。","積水浮魂夢，流年半別離。","東風未迴日，音信杳難期。"]', '["渡海登仙籍，還家備漢儀。","孤舟無岸泊，万里有星隨。","積水浮魂梦，流年半別離。","东风未迴日，音信杳难期。"]', '诗', 'shi', '', NULL, '送賓貢金夷吾奉使歸本國 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a6c96f-4023-4b94-a2b8-24b6c481a28c', '華山', '华山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["誰將倚天劒，削出倚天峰。","衆水背流急，他山相向重。","樹黏青靄合，崖夾白雲濃。","一夜盆傾雨，前湫起毒龍。"]', '["誰將倚天劒，削出倚天峰。","衆水背流急，他山相向重。","樹黏青靄合，崖夾白云濃。","一夜盆傾雨，前湫起毒龙。"]', '诗', 'shi', '', NULL, '華山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8f3ce8-4766-4896-9420-ded8b2856a36', '滕王閣', '滕王閣', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["昔人登覽處，遺閣大江隅。","疊浪有時有，閑雲無日無。","早涼先燕去，返照後帆孤。","未得營歸計，菱歌滿舊湖。"]', '["昔人登覽处，遺閣大江隅。","叠浪有时有，闲云無日無。","早涼先燕去，返照後帆孤。","未得營归計，菱歌满旧湖。"]', '诗', 'shi', '', NULL, '滕王閣 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9f6ef2-3e5b-49e9-ae32-b6fdf7b02f80', '寄處士梁燭', '寄处士梁燭', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["賢哉君子風，諷與古人同。","採藥楚雲裏，移家湘水東。","星霜秋野闊，雨雹夜山空。","早晚相招隱，深耕老此中。"]', '["賢哉君子风，諷與古人同。","採藥楚云裏，移家湘水东。","星霜秋野闊，雨雹夜山空。","早晚相招隐，深耕老此中。"]', '诗', 'shi', '', NULL, '寄處士梁燭 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff5b4d9-d8fe-436b-8126-b6503503244a', '送許棠下第遊蜀', '送許棠下第游蜀', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["天下猿多處，西南是蜀關。","馬登青壁瘦，人宿翠微閑。","帶雨逢殘日，因江見斷山。","行歌風月好，莫老錦城間。"]', '["天下猿多处，西南是蜀关。","马登青壁瘦，人宿翠微闲。","带雨逢殘日，因江见斷山。","行歌风月好，莫老錦城间。"]', '诗', 'shi', '', NULL, '送許棠下第遊蜀 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314ee84c-a03c-409b-b13e-fb0a6daeb283', '題終南山白鶴觀', '題終南山白鹤观', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["上徹鍊丹峰，求玄意未窮。","古壇青草合，往事白雲空。","仙境日月外，帝鄉煙霧中。","人間足煩署，欲去戀松風。"]', '["上徹鍊丹峰，求玄意未窮。","古壇青草合，往事白云空。","仙境日月外，帝乡煙霧中。","人间足煩署，欲去戀松风。"]', '诗', 'shi', '', NULL, '題終南山白鶴觀 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9edfa3-cbb6-47b0-a637-e1cdc52e06f3', '贈邊將', '贈邊將', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["將軍誇膽氣，功在殺人多。","對酒擎鍾飲，臨風拔劒歌。","翻師平碎葉，掠地取交河。","應笑孔門客，年年羨四科。"]', '["將軍誇膽氣，功在殺人多。","对酒擎鍾饮，臨风拔劒歌。","翻師平碎葉，掠地取交河。","應笑孔门客，年年羨四科。"]', '诗', 'shi', '', NULL, '贈邊將 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ed88d6-e73a-42e1-bc4b-f0c36870e5e7', '弔建州李員外', '弔建州李員外', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["銘旌歸故里，猿鳥亦悽然。","已葬桐江月，空迴建水船。","客傳爲郡日，僧說讀書年。","恐有吟魂在，深山古木邊。"]', '["銘旌归故里，猿鸟亦悽然。","已葬桐江月，空迴建水船。","客傳爲郡日，僧说读书年。","恐有吟魂在，深山古木邊。"]', '诗', 'shi', '', NULL, '弔建州李員外 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa78634-4351-4ccd-86ac-5be70c4a4dd9', '送許棠及第歸宣州', '送許棠及第归宣州', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["雅調一生吟，誰爲晚達心。","傍人賀及第，獨自却霑襟。","宴別喧天樂，家歸礙日岑。","青門許攀送，故里接雲林。"]', '["雅調一生吟，誰爲晚達心。","傍人賀及第，独自却霑襟。","宴別喧天乐，家归礙日岑。","青门許攀送，故里接云林。"]', '诗', 'shi', '', NULL, '送許棠及第歸宣州 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a341fedf-e08f-41a6-a65c-84853ad63ad5', '送龐百篇之任青陽縣尉', '送龐百篇之任青陽縣尉', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["都堂公試日，詞翰獨超羣。","品秩台庭與，篇章聖主聞。","鄉連三楚樹，縣對九華雲。","多少青門客，臨岐共羨君。"]', '["都堂公試日，词翰独超羣。","品秩台庭與，篇章聖主闻。","乡連三楚樹，縣对九华云。","多少青门客，臨岐共羨君。"]', '诗', 'shi', '', NULL, '送龐百篇之任青陽縣尉 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3608fba3-87f4-420d-b1fe-d52a8f4cc7e7', '曲江春', '曲江春', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["尋春與送春，多遶曲江濱。","一片鳧鷖水，千秋輦轂塵。","岸涼隨衆木，波影逐遊人。","自是遊人老，年年管吹新。"]', '["尋春與送春，多遶曲江濱。","一片鳧鷖水，千秋輦轂塵。","岸涼隨衆木，波影逐游人。","自是游人老，年年管吹新。"]', '诗', 'shi', '', NULL, '曲江春 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4d8eef-358d-40fa-98d0-8d8fe189fae2', '秦原春望', '秦原春望', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["無窮名利塵，軒蓋逐年新。","北闋東堂路，千山萬水人。","雲離僧榻曙，燕遠鳳樓春。","荏苒文明代，難歸釣艇身。"]', '["無窮名利塵，軒蓋逐年新。","北闋东堂路，千山万水人。","云離僧榻曙，燕远鳳楼春。","荏苒文明代，难归釣艇身。"]', '诗', 'shi', '', NULL, '秦原春望 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11bab6c9-81b8-4c27-a60c-9b50385cdf35', '遊華山雲際寺', '游华山云際寺', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["少華中峰寺，高秋衆景歸。","地連秦塞起，河隔晉山微。","晚木蟬相應，涼天鴈並飛。","殷勤記巖石，秪恐再來稀。"]', '["少华中峰寺，高秋衆景归。","地連秦塞起，河隔晉山微。","晚木蟬相應，涼天鴈並飞。","殷勤記巖石，秪恐再来稀。"]', '诗', 'shi', '', NULL, '遊華山雲際寺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e764782e-ad6a-4609-a0b2-ca8a5f877f59', '送碁待詔朴球歸新羅', '送碁待詔朴球归新羅', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["海東誰敵手，歸去道應孤。","闕下傳新勢，船中覆舊圖。","窮荒迴日月，積水載寰區。","故國多年別，桑田復在無。"]', '["海东誰敵手，归去道應孤。","闕下傳新勢，船中覆旧圖。","窮荒迴日月，積水載寰區。","故国多年別，桑田复在無。"]', '诗', 'shi', '', NULL, '送碁待詔朴球歸新羅 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ef3f03-4cfe-4448-a6aa-ef8e9e52e3bd', '送鄭谷先輩赴汝州辟命', '送鄭谷先輩赴汝州辟命', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["看花興未休，已散曲江遊。","載筆離秦甸，從軍過洛州。","嵩雲將雨去，汝水背城流。","應念依門客，蒿萊滿徑秋。"]', '["看花兴未休，已散曲江游。","載笔離秦甸，從軍過洛州。","嵩云將雨去，汝水背城流。","應念依门客，蒿萊满徑秋。"]', '诗', 'shi', '', NULL, '送鄭谷先輩赴汝州辟命 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195092ae-a3d3-462c-8d23-817c811b1357', '贈敬亭清越上人', '贈敬亭清越上人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["海上獨隨緣，歸來二十年。","久閑時得句，漸老不離禪。","砌木欹臨水，窗峰直倚天。","猶期向雲裏，別掃石床眠。"]', '["海上独隨緣，归来二十年。","久闲时得句，漸老不離禪。","砌木欹臨水，窗峰直倚天。","猶期向云裏，別掃石床眠。"]', '诗', 'shi', '', NULL, '贈敬亭清越上人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ccf3ce-0108-4833-a296-f36085ca2d72', '題靈山寺', '題靈山寺', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["樹涼清島寺，虛閣敞禪扉。","四面閑雲入，中流獨鳥歸。","湖平幽徑近，船泊夜燈微。","一宿秋風裏，煙波隔擣衣。"]', '["樹涼清島寺，虛閣敞禪扉。","四面闲云入，中流独鸟归。","湖平幽徑近，船泊夜灯微。","一宿秋风裏，煙波隔擣衣。"]', '诗', 'shi', '', NULL, '題靈山寺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128d1f2f-9cd5-4d87-9343-87ec666157d7', '弔栖白上人', '弔栖白上人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["今古遰相送，幾時無逝波。","篇章名不朽，寂滅理如何。","內殿留真影，閑房落貝多。","從茲高塔寺，惆悵懶經過。"]', '["今古遰相送，幾时無逝波。","篇章名不朽，寂滅理如何。","內殿留真影，闲房落貝多。","從茲高塔寺，惆悵懶經過。"]', '诗', 'shi', '', NULL, '弔栖白上人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a26dea0-34f7-4013-97dd-bc4ac5cbf6f3', '北山書事', '北山书事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["黃河一曲山，天半鎖重關。","聖日雄藩靜，秋風老將閑。","車輿穿谷口，市井響雲間。","大野無飛鳥，元戎校獵還。"]', '["黄河一曲山，天半鎖重关。","聖日雄藩静，秋风老將闲。","车輿穿谷口，市井响云间。","大野無飞鸟，元戎校獵還。"]', '诗', 'shi', '', NULL, '北山書事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93bbdbc5-72a2-4c8f-9ba0-6adc1c0aca56', '長安書事', '长安书事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["出送鄉人盡，滄洲未得還。","秋風五陵樹，晴日六街山。","有景終年住，無機是處閑。","何當向雲外，免老別離間。"]', '["出送乡人尽，滄洲未得還。","秋风五陵樹，晴日六街山。","有景終年住，無機是处闲。","何當向云外，免老別離间。"]', '诗', 'shi', '', NULL, '長安書事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30fc6ee-bd0f-408f-8a14-a558cf183dd8', '送鄭侍御赴汴州辟命', '送鄭侍御赴汴州辟命', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["官從諫署清，暫去佐戎旌。","朝客多相戀，吟僧欲伴行。","河冰天際白，嶽雪眼前明。","即見東風起，梁園聽早鶯。"]', '["官從諫署清，暫去佐戎旌。","朝客多相戀，吟僧欲伴行。","河冰天際白，嶽雪眼前明。","即见东风起，梁园听早鶯。"]', '诗', 'shi', '', NULL, '送鄭侍御赴汴州辟命 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8acfa02-7294-43f9-a9ab-e3c23603768d', '弔造微上人', '弔造微上人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["至人隨化往，遺路自堪傷。","白塔收真骨，青山閉影堂。","鐘殘含細韻，煙滅有餘香。","松上齋烏在，遲遲立夕陽。"]', '["至人隨化往，遺路自堪傷。","白塔收真骨，青山閉影堂。","鐘殘含細韻，煙滅有餘香。","松上斋烏在，遲遲立夕陽。"]', '诗', 'shi', '', NULL, '弔造微上人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6f6a75-db19-4163-bb99-d542d3c2412a', '經隱巖舊居', '經隐巖旧居', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["夜久村落靜，徘徊楊柳津。","青山猶有路，明月已無人。","夢寐空前事，星霜倦此身。","嘗期結茅處，來往躡遺塵。"]', '["夜久村落静，徘徊楊柳津。","青山猶有路，明月已無人。","梦寐空前事，星霜倦此身。","嘗期結茅处，来往躡遺塵。"]', '诗', 'shi', '', NULL, '經隱巖舊居 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0164776b-bf22-4a59-9cc7-58364316c11b', '再題敬亭清越上人山房', '再題敬亭清越上人山房', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["重來訪惠休，已是十年遊。","向水千松老，空山一磬秋。","石窗清吹入，河漢夜光流。","久別多新作，長吟洗俗愁。"]', '["重来訪惠休，已是十年游。","向水千松老，空山一磬秋。","石窗清吹入，河漢夜光流。","久別多新作，长吟洗俗愁。"]', '诗', 'shi', '', NULL, '再題敬亭清越上人山房 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10ee032-78a8-46d1-887f-6030197aacbc', '浮汴東歸', '浮汴东归', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["日暖泗濱西，無窮岸草齊。","薄煙衰草樹，微月迥城雞。","水近滄浪急，山隨綠野低。","羞將舊名姓，還向舊遊題。"]', '["日暖泗濱西，無窮岸草齊。","薄煙衰草樹，微月迥城雞。","水近滄浪急，山隨綠野低。","羞將旧名姓，還向旧游題。"]', '诗', 'shi', '', NULL, '浮汴東歸 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d94b8b1-d00c-4667-a411-3117ac16e7a4', '雨中宿僧院', '雨中宿僧院', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["千燈有宿因，長老許相親。","夜永樓臺雨，更深江海人。","勞生無了日，妄念起微塵。","不是真如理，何門靜此身。"]', '["千灯有宿因，长老許相親。","夜永楼台雨，更深江海人。","勞生無了日，妄念起微塵。","不是真如理，何门静此身。"]', '诗', 'shi', '', NULL, '雨中宿僧院 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5342aa89-462b-464b-bf6b-120738e8397b', '江行至沙浦', '江行至沙浦', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["煙霞接杳冥，旅泊寄迴汀。","夜雨雷電歇，春江蛟蜃腥。","城侵潮影白，嶠截鳥行青。","徧欲探泉石，南須過洞庭。"]', '["煙霞接杳冥，旅泊寄迴汀。","夜雨雷電歇，春江蛟蜃腥。","城侵潮影白，嶠截鸟行青。","徧欲探泉石，南須過洞庭。"]', '诗', 'shi', '', NULL, '江行至沙浦 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e546a15f-e9b2-4e4c-9f89-191579667689', '送友人歸江南', '送友人归江南', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["辛勤同失意，迢遞獨還家。","落日江邊笛，殘春島上花。","親安誠可喜，道在亦何嗟。","誰伴高吟處，晴天望九華。"]', '["辛勤同失意，迢遞独還家。","落日江邊笛，殘春島上花。","親安誠可喜，道在亦何嗟。","誰伴高吟处，晴天望九华。"]', '诗', 'shi', '', NULL, '送友人歸江南 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f72189-38fe-4093-91c7-6d40a3689bcc', '劉補闕自九華山拜官因以寄獻', '劉補闕自九华山拜官因以寄獻', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["冥鴻久不羣，徵拜動天文。","地主迎過郡，山僧送出雲。","登車殘月在，宿館亂流分。","若更思林下，還須共致君。"]', '["冥鴻久不羣，徵拜动天文。","地主迎過郡，山僧送出云。","登车殘月在，宿館亂流分。","若更思林下，還須共致君。"]', '诗', 'shi', '', NULL, '劉補闕自九華山拜官因以寄獻 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6dd000-e39f-40aa-911a-fba3e94d92b3', '岳陽即事', '岳陽即事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["遠色岳陽樓，湘帆數片愁。","竹風山上路，沙月水中洲。","力學桑田廢，思歸鬢髪秋。","功名如不立，豈易狎汀鷗。"]', '["远色岳陽楼，湘帆數片愁。","竹风山上路，沙月水中洲。","力学桑田廢，思归鬢髪秋。","功名如不立，豈易狎汀鷗。"]', '诗', 'shi', '', NULL, '岳陽即事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('828569ff-c3b9-4408-bb07-9b1dd00b80ce', '題興善寺僧道深院', '題兴善寺僧道深院', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["江峰峰頂人，受法老西秦。","法本無前業，禪非爲後身。","院栽他國樹，堂展祖師真。","甚願依宗旨，求閑未有因。"]', '["江峰峰頂人，受法老西秦。","法本無前業，禪非爲後身。","院栽他国樹，堂展祖師真。","甚願依宗旨，求闲未有因。"]', '诗', 'shi', '', NULL, '題興善寺僧道深院 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78f17a5-1503-40cd-800b-a8d64d6ca044', '送龍門令劉滄', '送龙门令劉滄', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["去宰龍門縣，應思變化年。","還將魯儒政，又與晉人傳。","峭壁開中古，長河落半天。","幾鄉因勸勉，耕稼滿雲煙。"]', '["去宰龙门縣，應思变化年。","還將魯儒政，又與晉人傳。","峭壁开中古，长河落半天。","幾乡因勸勉，耕稼满云煙。"]', '诗', 'shi', '', NULL, '送龍門令劉滄 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c95f197-4560-4ceb-8e04-69fdffab85d3', '送友人往宜春', '送友人往宜春', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["落花兼柳絮，無處不紛紛。","遠道空歸去，流鶯獨自聞。","野橋喧磑水，山郭入樓雲。","故里南陵曲，秋期更送君。"]', '["落花兼柳絮，無处不紛紛。","远道空归去，流鶯独自闻。","野橋喧磑水，山郭入楼云。","故里南陵曲，秋期更送君。"]', '诗', 'shi', '', NULL, '送友人往宜春 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8324db66-b75a-40ff-9469-cba276d2f88f', '書邊事', '书邊事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["調角斷清秋，征人倚戍樓。","春風對青塚，白日落梁州。","大漢無兵阻，窮邊有客遊。","蕃情似此水，長願向南流。"]', '["調角斷清秋，征人倚戍楼。","春风对青塚，白日落梁州。","大漢無兵阻，窮邊有客游。","蕃情似此水，长願向南流。"]', '诗', 'shi', '', NULL, '書邊事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ffd49c-a436-4d95-847d-701ae56adf17', '送僧雅覺歸東海', '送僧雅覺归东海', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["山川心地內，一念即千重。","老別關中寺，禪歸海外峰。","鳥行來有路，帆影去無蹤。","幾夜波濤息，先聞本國鐘。"]', '["山川心地內，一念即千重。","老別关中寺，禪归海外峰。","鸟行来有路，帆影去無蹤。","幾夜波濤息，先闻本国鐘。"]', '诗', 'shi', '', NULL, '送僧雅覺歸東海 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4796c6d6-5a11-462b-a26a-4497fcd99e14', '和薛監察題興善寺古松', '和薛監察題兴善寺古松', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["種在法王城，前朝古寺名。","瘦根盤地遠，香吹入雲清。","鶴動池臺影，僧禪雨雪聲。","看來人旋老，因此歎浮生。"]', '["種在法王城，前朝古寺名。","瘦根盤地远，香吹入云清。","鹤动池台影，僧禪雨雪声。","看来人旋老，因此歎浮生。"]', '诗', 'shi', '', NULL, '和薛監察題興善寺古松 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9c9d0b-eb38-4239-a506-d237cd207139', '聽琴', '听琴', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["清月轉瑤軫，弄中湘水寒。","能令坐來客，不語自相看。","靜恐鬼神出，急疑風雨殘。","幾時歸嶺嶠，更過洞庭彈。"]', '["清月轉瑤軫，弄中湘水寒。","能令坐来客，不語自相看。","静恐鬼神出，急疑风雨殘。","幾时归嶺嶠，更過洞庭彈。"]', '诗', 'shi', '', NULL, '聽琴 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f67006-a3bd-43ab-ad7a-6463c1100442', '送友人遊蜀', '送友人游蜀', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["此心知者稀，欲別倍相依。","無食擬同去，有家還未歸。","巴山開國遠，劒道入天微。","必恐臨邛客，疑君學賦非。"]', '["此心知者稀，欲別倍相依。","無食擬同去，有家還未归。","巴山开国远，劒道入天微。","必恐臨邛客，疑君学賦非。"]', '诗', 'shi', '', NULL, '送友人遊蜀 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12530e2-dbb4-4ebd-9b59-0d529b93d1b8', '聞仰山禪師往曹溪因贈', '闻仰山禪師往曹溪因贈', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["曹溪松下路，猨鳥重相親。","四海求玄理，千峰遶定身。","異花天上墮，靈草雪中春。","自惜經行處，焚香禮舊真。"]', '["曹溪松下路，猨鸟重相親。","四海求玄理，千峰遶定身。","異花天上墮，靈草雪中春。","自惜經行处，焚香禮旧真。"]', '诗', 'shi', '', NULL, '聞仰山禪師往曹溪因贈 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d277b62e-eaa4-4a5e-b051-42e72ab95cd3', '藍溪夜坐', '藍溪夜坐', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["藍水警塵夢，夜吟開草堂。","月臨山靄薄，松滴露花香。","詩外真風遠，人間靜興長。","明朝訪禪侶，更上翠微房。"]', '["藍水警塵梦，夜吟开草堂。","月臨山靄薄，松滴露花香。","诗外真风远，人间静兴长。","明朝訪禪侶，更上翠微房。"]', '诗', 'shi', '', NULL, '藍溪夜坐 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b948a659-c0db-4ecc-98f5-b88a074c5f12', '題鄭侍御藍田別業', '題鄭侍御藍田別業', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["秋山清若水，吟客靜於僧。","小徑通商嶺，高窗見杜陵。","雲霞朝入鏡，猨鳥夜窺燈。","許作前峰侶，終來寄上層。"]', '["秋山清若水，吟客静於僧。","小徑通商嶺，高窗见杜陵。","云霞朝入镜，猨鸟夜窺灯。","許作前峰侶，終来寄上層。"]', '诗', 'shi', '', NULL, '題鄭侍御藍田別業 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b0a0f97-59ea-469f-a0a8-b0621082b31c', '送友人進士許棠', '送友人進士許棠', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["離鄉積歲年，歸路遠依然。","夜火山頭市，春江樹杪船。","干戈愁鬢改，瘴癘喜家全。","何處營甘旨，潮濤浸薄田。"]', '["離乡積歲年，归路远依然。","夜火山头市，春江樹杪船。","干戈愁鬢改，瘴癘喜家全。","何处營甘旨，潮濤浸薄田。"]', '诗', 'shi', '', NULL, '送友人進士許棠 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852b7cfa-6c72-433b-b69a-8ce908dc2ed6', '秘省伴直', '秘省伴直', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["喬枝聚暝禽，疊閣鎖遙岑。","待月當秋直，看書廢夜吟。","殘薪留火細，古井下瓶深。","縱欲抄前史，貧難遂此心。"]', '["喬枝聚暝禽，叠閣鎖遙岑。","待月當秋直，看书廢夜吟。","殘薪留火細，古井下瓶深。","縱欲抄前史，貧难遂此心。"]', '诗', 'shi', '', NULL, '秘省伴直 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd59254-617d-4217-a59a-6a02ecdc1756', '宿昭應', '宿昭應', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["夜憶開元寺，淒涼里巷間。","薄煙通魏闕，明月照驪山。","半壁空宮閉，連天白道閑。","清晨更回首，獨向灞陵還。"]', '["夜憶开元寺，淒涼里巷间。","薄煙通魏闕，明月照驪山。","半壁空宮閉，連天白道闲。","清晨更回首，独向灞陵還。"]', '诗', 'shi', '', NULL, '宿昭應 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b653a15-b561-4f8f-903d-33bc4b33234f', '送陸處士', '送陸处士', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["樽前放浩歌，便起泛煙波。","舟楫故人少，江湖明月多。","孤峰經宿上，僻寺共雲過。","若向仙巖住，還應著薜蘿。"]', '["樽前放浩歌，便起泛煙波。","舟楫故人少，江湖明月多。","孤峰經宿上，僻寺共云過。","若向仙巖住，還應著薜蘿。"]', '诗', 'shi', '', NULL, '送陸處士 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7785626-8a80-48d2-b160-4b73d16f11c4', '送韓處士歸少室山', '送韓处士归少室山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["江外歷千岑，還歸少室吟。","地閑緱嶺月，窗迥洛城砧。","石竇垂寒乳，松枝長別琴。","他年瀑泉下，亦擬置家林。"]', '["江外歷千岑，還归少室吟。","地闲緱嶺月，窗迥洛城砧。","石竇垂寒乳，松枝长別琴。","他年瀑泉下，亦擬置家林。"]', '诗', 'shi', '', NULL, '送韓處士歸少室山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ae4cdeb-5f15-4e17-b4a5-1d4a4eea62e4', '贈初上人', '贈初上人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["竹色覆禪棲，幽禽遶院啼。","空門無去住，行客自東西。","井氣春來歇，庭枝雪後低。","相看念山水，盡日話曹溪。"]', '["竹色覆禪棲，幽禽遶院啼。","空门無去住，行客自东西。","井氣春来歇，庭枝雪後低。","相看念山水，尽日話曹溪。"]', '诗', 'shi', '', NULL, '贈初上人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d277af-3905-4a1b-98e9-7d57e4a64806', '送新羅僧', '送新羅僧', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["東來此學禪，多病念佛緣。","把錫離巖寺，收經上海船。","落帆敲石火，宿島汲瓶泉。","永向扶桑老，知無再少年。"]', '["东来此学禪，多病念佛緣。","把錫離巖寺，收經上海船。","落帆敲石火，宿島汲瓶泉。","永向扶桑老，知無再少年。"]', '诗', 'shi', '', NULL, '送新羅僧 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173969ed-0afb-4b36-8f25-de62dbabc1cc', '題山僧院', '題山僧院', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["谿路曾來日，年多與舊同。","地寒松影裏，僧老磬聲中。","遠水清風落，閑雲別院通。","心源若無礙，何必更論空。"]', '["谿路曾来日，年多與旧同。","地寒松影裏，僧老磬声中。","远水清风落，闲云別院通。","心源若無礙，何必更論空。"]', '诗', 'shi', '', NULL, '題山僧院 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ee25ca-ce4a-45ac-83bc-70f0ca0679cb', '書梅福殿壁二首 一', '书梅福殿壁二首 一', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["梅真從羽化，萬古是須臾。","此地名空在，西山雲亦孤。","井痕平野水，壇級上春蕪。","縱有雙飛鶴，年多松已枯。"]', '["梅真從羽化，万古是須臾。","此地名空在，西山云亦孤。","井痕平野水，壇級上春蕪。","縱有雙飞鹤，年多松已枯。"]', '诗', 'shi', '', NULL, '書梅福殿壁二首 一 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d31cf8-16e6-4ade-91f6-4549375ac632', '書梅福殿壁二首 二', '书梅福殿壁二首 二', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一自白雲去，千秋壇月明。","我來思往事，誰更得長生。","雅韻磬鍾遠，真風樓殿清。","今來爲尉者，天下有仙名。"]', '["一自白云去，千秋壇月明。","我来思往事，誰更得长生。","雅韻磬鍾远，真风楼殿清。","今来爲尉者，天下有仙名。"]', '诗', 'shi', '', NULL, '書梅福殿壁二首 二 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353cf8af-79e4-4de1-b43f-8add0f481998', '荆楚道中', '荆楚道中', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["前程曾未到，岐路擬何爲。","返照行人急，荒郊去鳥遲。","春宵多旅夢，夏閏遠秋期。","處處牽愁緒，無窮是柳絲。"]', '["前程曾未到，岐路擬何爲。","返照行人急，荒郊去鸟遲。","春宵多旅梦，夏閏远秋期。","处处牽愁緒，無窮是柳絲。"]', '诗', 'shi', '', NULL, '荆楚道中 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5839dca5-f3dc-4626-9eac-5d2baca3f55c', '送南陵尉李頻', '送南陵尉李頻', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["重作東南尉，生涯尚似僧。","客程淮館月，鄉思海船燈。","晚霧看春轂，晴天見朗陵。","不應三考足，先授詔書徵。"]', '["重作东南尉，生涯尚似僧。","客程淮館月，乡思海船灯。","晚霧看春轂，晴天见朗陵。","不應三考足，先授詔书徵。"]', '诗', 'shi', '', NULL, '送南陵尉李頻 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc37c875-1e11-4ad6-b196-85581c174787', '將歸江淮書', '將归江淮书', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["東風搖衆木，即有看花期。","紫陌頻來日，滄洲獨去時。","郡因兵役苦，家爲海翻移。","未老多如此，那堪鬢不衰。"]', '["东风搖衆木，即有看花期。","紫陌頻来日，滄洲独去时。","郡因兵役苦，家爲海翻移。","未老多如此，那堪鬢不衰。"]', '诗', 'shi', '', NULL, '將歸江淮書 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617d3b4d-4282-44b5-88b5-d486ef867a0a', '沿漢東歸', '沿漢东归', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["北去窮秦塞，南歸遶漢川。","深山逢古跡，遠道見新年。","絕壁雲銜寺，空江雪灑船。","縈迴還此景，多坐夜燈前。"]', '["北去窮秦塞，南归遶漢川。","深山逢古跡，远道见新年。","絕壁云銜寺，空江雪灑船。","縈迴還此景，多坐夜灯前。"]', '诗', 'shi', '', NULL, '沿漢東歸 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e240a046-b096-4499-a859-217aa76a48aa', '送蜀客', '送蜀客', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["劒閣緣空去，西南轉幾州。","丹霄行客語，明月杜鵑愁。","露帶山花落，雲隨野水流。","相如曾醉地，莫滯少年遊。"]', '["劒閣緣空去，西南轉幾州。","丹霄行客語，明月杜鵑愁。","露带山花落，云隨野水流。","相如曾醉地，莫滯少年游。"]', '诗', 'shi', '', NULL, '送蜀客 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5a64cc-7b45-4405-ae1b-70a9c2f4a51c', '塞上', '塞上', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["勒兵遼水邊，風急卷旌旃。","絕塞寒無樹，平沙勢盡天。","雪晴迴探騎，月落控鳴弦。","永定山河誓，南歸改漢年。"]', '["勒兵遼水邊，风急卷旌旃。","絕塞寒無樹，平沙勢尽天。","雪晴迴探騎，月落控鳴弦。","永定山河誓，南归改漢年。"]', '诗', 'shi', '', NULL, '塞上 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba47779b-5e75-4c42-926b-dd0898fb4b04', '送友人歸袁州', '送友人归袁州', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["袁江猨鳥清，曾向此中行。","才子登科去，諸侯掃榻迎。","山藏明月浦，樹遶白雲城。","遠想安親後，秋風夢不驚。"]', '["袁江猨鸟清，曾向此中行。","才子登科去，諸侯掃榻迎。","山藏明月浦，樹遶白云城。","远想安親後，秋风梦不驚。"]', '诗', 'shi', '', NULL, '送友人歸袁州 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f0b477-1b49-4a6e-a91a-ddf4d57a07f4', '贈別李山人', '贈別李山人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["分合老西秦，年年夢白蘋。","曾爲洞庭客，還送洞庭人。","語別惜殘夜，思歸愁見春。","遙知泊舟處，沙月自相親。"]', '["分合老西秦，年年梦白蘋。","曾爲洞庭客，還送洞庭人。","語別惜殘夜，思归愁见春。","遙知泊舟处，沙月自相親。"]', '诗', 'shi', '', NULL, '贈別李山人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec637d1-43a5-450d-84a4-81656275b759', '思宜春寄友人', '思宜春寄友人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["勝遊雖隔年，魂夢亦依然。","瀑水喧秋思，孤燈動夜船。","斷虹全嶺雨，斜月半溪煙。","舊日吟詩侶，何人更不眠。"]', '["勝游雖隔年，魂梦亦依然。","瀑水喧秋思，孤灯动夜船。","斷虹全嶺雨，斜月半溪煙。","旧日吟诗侶，何人更不眠。"]', '诗', 'shi', '', NULL, '思宜春寄友人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57286cf-5bc2-4dc1-ab2c-2ef9b08686a1', '江行夜雨', '江行夜雨', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["江風木落天，遊子感流年。","萬里波連蜀，三更雨到船。","夢殘燈影外，愁積葦業邊。","不及樵漁客，全家住島田。"]', '["江风木落天，游子感流年。","万里波連蜀，三更雨到船。","梦殘灯影外，愁積葦業邊。","不及樵漁客，全家住島田。"]', '诗', 'shi', '', NULL, '江行夜雨 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdf10d7-e2df-4a19-897e-8e9da1c37a75', '贈仰大師', '贈仰大師', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["仰山因久住，天下仰山名。","井邑身雖到，林泉性本清。","野雲居處盡，江月定中明。","髣髴曾相識，今來隔幾生。"]', '["仰山因久住，天下仰山名。","井邑身雖到，林泉性本清。","野云居处尽，江月定中明。","髣髴曾相識，今来隔幾生。"]', '诗', 'shi', '', NULL, '贈仰大師 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f16a9fd-4043-4d02-80be-1d324e54b96f', '江南逢洛下友人', '江南逢洛下友人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["洛下吟詩侶，南遊只有君。","波濤歸路見，蟋蟀在船聞。","曉月江城出，晴霞島樹分。","無窮懷古意，豈獨遶湘雲。"]', '["洛下吟诗侶，南游只有君。","波濤归路见，蟋蟀在船闻。","晓月江城出，晴霞島樹分。","無窮懷古意，豈独遶湘云。"]', '诗', 'shi', '', NULL, '江南逢洛下友人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ce758a-99de-440d-aed3-dacab03880b9', '東湖贈僧子蘭', '东湖贈僧子蘭', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["名利了無時，何人暫訪師。","道情閑外見，心地語來知。","竹落穿窗葉，松寒蔭井枝。","匡山許同社，願卜挂帆期。"]', '["名利了無时，何人暫訪師。","道情闲外见，心地語来知。","竹落穿窗葉，松寒蔭井枝。","匡山許同社，願卜挂帆期。"]', '诗', 'shi', '', NULL, '東湖贈僧子蘭 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d8bfca-75cc-4541-968a-f2f9545dca33', '隱巖陪鄭少師夜坐', '隐巖陪鄭少師夜坐', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["幸喜陪騶馭，頻來向此宵。","硯磨清澗石，廚爨白雲樵。","竹外村煙細，燈中禁漏遙。","衣冠與文理，靜語對前朝。"]', '["幸喜陪騶馭，頻来向此宵。","硯磨清澗石，廚爨白云樵。","竹外村煙細，灯中禁漏遙。","衣冠與文理，静語对前朝。"]', '诗', 'shi', '', NULL, '隱巖陪鄭少師夜坐 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc457c1-ca13-4a0a-9e61-0154efdb3434', '送三傳赴長城尉', '送三傳赴长城尉', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["登科精魯史，爲尉及良時。","高論窮諸國，長才併幾司。","地傾流水疾，山疊過雲遲。","暇日琴書畔，何人對手棋。"]', '["登科精魯史，爲尉及良时。","高論窮諸国，长才併幾司。","地傾流水疾，山叠過云遲。","暇日琴书畔，何人对手棋。"]', '诗', 'shi', '', NULL, '送三傳赴長城尉 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e21ba5-d87f-4996-a891-e9877a73b68b', '送李道士歸南嶽', '送李道士归南嶽', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["千峰隔湘水，迢遰挂帆歸。","掃月眠蒼壁，和雲著褐衣。","洞虛懸溜滴，徑狹長松圍。","只恐相尋日，人間舊識稀。"]', '["千峰隔湘水，迢遰挂帆归。","掃月眠蒼壁，和云著褐衣。","洞虛懸溜滴，徑狹长松圍。","只恐相尋日，人间旧識稀。"]', '诗', 'shi', '', NULL, '送李道士歸南嶽 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02730697-145c-4a61-9ea5-df89de60a46f', '延福里秋懷', '延福里秋懷', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["終年九陌行，要路跡皆生。","苦學猶難至，甘貧豈有成。","病攜秋卷重，閑著暑衣輕。","一別林泉久，中宵御水聲。"]', '["終年九陌行，要路跡皆生。","苦学猶难至，甘貧豈有成。","病携秋卷重，闲著暑衣轻。","一別林泉久，中宵御水声。"]', '诗', 'shi', '', NULL, '延福里秋懷 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e0ba93-51db-4633-8b0e-91127e8be054', '題玄哲禪師影堂', '題玄哲禪師影堂', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["吾師視化身，一念即遺塵。","巖谷藏虛塔，江湖散學人。","雲迷禪處石，院掩寫來真。","寂寞焚香後，閑階細草生。"]', '["吾師視化身，一念即遺塵。","巖谷藏虛塔，江湖散学人。","云迷禪处石，院掩寫来真。","寂寞焚香後，闲階細草生。"]', '诗', 'shi', '', NULL, '題玄哲禪師影堂 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41228ca3-85bf-46fb-8663-a5947e49d78a', '登慈恩寺塔', '登慈恩寺塔', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["窗戶幾層風，清涼碧落中。","世人來往別，煙景古今同。","列岫橫秦斷，長河極塞空。","斜陽越鄉思，天末見歸鴻。"]', '["窗戶幾層风，清涼碧落中。","世人来往別，煙景古今同。","列岫橫秦斷，长河極塞空。","斜陽越乡思，天末见归鴻。"]', '诗', 'shi', '', NULL, '登慈恩寺塔 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0849e88-2e9d-4f70-a3cc-75ebc39c9c79', '送友人東歸', '送友人东归', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["遠涉期秋卷，將行不廢吟。","故鄉芳草路，來往別離心。","挂席春風盡，開齋夏景深。","子規誰共聽，江月上清岑。"]', '["远涉期秋卷，將行不廢吟。","故乡芳草路，来往別離心。","挂席春风尽，开斋夏景深。","子規誰共听，江月上清岑。"]', '诗', 'shi', '', NULL, '送友人東歸 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96aca1e5-a4e2-4ff0-855d-48732f37b359', '送僧鸞歸蜀寧親', '送僧鸾归蜀寧親', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["歌詩精外學，天子是知音。","坐夏宮鍾近，寧親劒閣深。","高名徹西國，舊跡寄東林。","自此棲禪者，因師滿蜀今。"]', '["歌诗精外学，天子是知音。","坐夏宮鍾近，寧親劒閣深。","高名徹西国，旧跡寄东林。","自此棲禪者，因師满蜀今。"]', '诗', 'shi', '', NULL, '送僧鸞歸蜀寧親 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9691bb64-4889-4a18-9f78-9f174c0305b5', '送人歸江南', '送人归江南', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["貧歸無定程，水宿與山行。","未有安親計，難爲去國情。","島煙孤寺磬，江月遠船箏。","思苦秋迴日，多應吟更清。"]', '["貧归無定程，水宿與山行。","未有安親計，难爲去国情。","島煙孤寺磬，江月远船箏。","思苦秋迴日，多應吟更清。"]', '诗', 'shi', '', NULL, '送人歸江南 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c281e09-5785-4391-af95-21b76e2c35dc', '將離江上作', '將離江上作', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["白衣歸樹下，青草戀江邊。","三楚足深隱，五陵多少年。","寂寥聞蜀魄，清絕怨湘弦。","岐路在何處，西行心渺然。"]', '["白衣归樹下，青草戀江邊。","三楚足深隐，五陵多少年。","寂寥闻蜀魄，清絕怨湘弦。","岐路在何处，西行心渺然。"]', '诗', 'shi', '', NULL, '將離江上作 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a182fb81-26ca-4766-9faf-a257733106c6', '別李參軍', '別李參軍', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["王孫遊不遇，況我五湖人。","野店難投宿，漁家獨問津。","嶺分中夜月，江隔兩鄉春。","靜想青雲路，還應寄此身。"]', '["王孫游不遇，況我五湖人。","野店难投宿，漁家独问津。","嶺分中夜月，江隔兩乡春。","静想青云路，還應寄此身。"]', '诗', 'shi', '', NULL, '別李參軍 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ccec37-b521-41c0-b040-f2d1dc9165bb', '送睦州張參軍', '送睦州張參軍', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["重祿輕身日，清資近故鄉。","因知送君後，轉自惜年芳。","遠水分林影，層峰起鳥行。","扁舟此中去，溪月有餘光。"]', '["重祿轻身日，清資近故乡。","因知送君後，轉自惜年芳。","远水分林影，層峰起鸟行。","扁舟此中去，溪月有餘光。"]', '诗', 'shi', '', NULL, '送睦州張參軍 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d82ff7b-35f6-46fc-9d3c-ebfbd55d0b86', '贈棋僧侶', '贈棋僧侶', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["機謀時未有，多向弈棋銷。","已與山僧敵，無令海客饒。","靜驅雲陣起，疎點鴈行遙。","夜雨如相憶，松窗更見招。"]', '["機謀时未有，多向弈棋銷。","已與山僧敵，無令海客饒。","静驱云陣起，疎点鴈行遙。","夜雨如相憶，松窗更见招。"]', '诗', 'shi', '', NULL, '贈棋僧侶 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f671b4c-2385-4887-a332-746988d5f723', '題湖上友人居', '題湖上友人居', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["豈得戀樵漁，全家湖畔居。","遠無潮客信，閑寄嶽僧書。","野白梅繁後，山明雨散初。","逍遙向雲水，莫與宦情疎。"]', '["豈得戀樵漁，全家湖畔居。","远無潮客信，闲寄嶽僧书。","野白梅繁後，山明雨散初。","逍遙向云水，莫與宦情疎。"]', '诗', 'shi', '', NULL, '題湖上友人居 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc26c5be-a206-44e5-9542-79b12ec9be55', '送友人歸宣州', '送友人归宣州', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["失計復離愁，君歸我獨遊。","亂花藏道發，春水遶鄉流。","暝火叢橋市，晴山疊郡樓。","無爲謝公戀，吟過曉蟬秋。"]', '["失計复離愁，君归我独游。","亂花藏道發，春水遶乡流。","暝火叢橋市，晴山叠郡楼。","無爲謝公戀，吟過晓蟬秋。"]', '诗', 'shi', '', NULL, '送友人歸宣州 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f07535-c709-455f-be61-0545617f1e26', '題古觀', '題古观', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["急景遰衰老，此經誰養真。","松留千載鶴，碑隔六朝人。","洞水流花早，壺天閉雪春。","其如爲名利，歸踏五陵塵。"]', '["急景遰衰老，此經誰養真。","松留千載鹤，碑隔六朝人。","洞水流花早，壺天閉雪春。","其如爲名利，归踏五陵塵。"]', '诗', 'shi', '', NULL, '題古觀 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16c9f87-b4f8-4215-803d-ff9460d1f0eb', '送友人及第歸江南', '送友人及第归江南', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["豈易及歸榮，辛勤致此名。","登車思往事，迴首勉諸生。","路遶山光曉，帆通海氣清。","秋期却閑坐，林下聽江聲。"]', '["豈易及归榮，辛勤致此名。","登车思往事，迴首勉諸生。","路遶山光晓，帆通海氣清。","秋期却闲坐，林下听江声。"]', '诗', 'shi', '', NULL, '送友人及第歸江南 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba684e4-409f-45f9-ae88-676658c27021', '送朴充侍御歸海東', '送朴充侍御归海东', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["天涯離二紀，闕下歷三朝。","漲海雖然闊，歸帆不覺遙。","驚波時失侶，舉火夜相招。","來往尋遺事，秦皇有斷橋。"]', '["天涯離二紀，闕下歷三朝。","漲海雖然闊，归帆不覺遙。","驚波时失侶，舉火夜相招。","来往尋遺事，秦皇有斷橋。"]', '诗', 'shi', '', NULL, '送朴充侍御歸海東 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca77f48a-68d0-4918-8a41-45255761b316', '弔前水部賈員外', '弔前水部賈員外', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["籠中江海禽，日夕有歸心。","魏闕長謠久，吳山獨往深。","別時羣木落，終處亂猨吟。","李白墳前路，溪僧送入林。"]', '["籠中江海禽，日夕有归心。","魏闕长謠久，吳山独往深。","別时羣木落，終处亂猨吟。","李白墳前路，溪僧送入林。"]', '诗', 'shi', '', NULL, '弔前水部賈員外 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafba258-a4b0-4583-a2ad-a8f5001968f3', '題小松', '題小松', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["松子落何年，纖枝長水邊。","斸開深澗雪，移出遠林煙。","帶月棲幽鳥，兼花灌冷泉。","微風動清韻，閑聽罷琴眠。"]', '["松子落何年，纖枝长水邊。","斸开深澗雪，移出远林煙。","带月棲幽鸟，兼花灌冷泉。","微风动清韻，闲听罷琴眠。"]', '诗', 'shi', '', NULL, '題小松 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('910b1225-a0b4-4dd8-be4f-4a8c7c456ad2', '寄中岳顓頊先生', '寄中岳顓頊先生', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["先生顓頊後，得道自何人。","松柏卑於壽，兒孫老却身。","夜窗峰頂曙，寒澗洞中春。","戀此逍遙境，雲間不可親。"]', '["先生顓頊後，得道自何人。","松柏卑於壽，兒孫老却身。","夜窗峰頂曙，寒澗洞中春。","戀此逍遙境，云间不可親。"]', '诗', 'shi', '', NULL, '寄中岳顓頊先生 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('590acf9b-de49-48bb-a074-102775ec44a0', '送沈先輩尉昭應', '送沈先輩尉昭應', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["餘才不廢詩，佐邑喜閑司。","丹陛終須去，青山未可期。","葉凋溫谷晚，雲出古宮遲。","若草東封疏，君王到有時。"]', '["餘才不廢诗，佐邑喜闲司。","丹陛終須去，青山未可期。","葉凋溫谷晚，云出古宮遲。","若草东封疏，君王到有时。"]', '诗', 'shi', '', NULL, '送沈先輩尉昭應 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b09510c-3df1-49ef-8799-477dd5b415da', '送友人遊湖南', '送友人游湖南', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["所投非舊知，亦似有前期。","路向長江上，帆揚細雨時。","春生南嶽早，日轉大荒遲。","盡採瀟湘句，重來會近期。"]', '["所投非旧知，亦似有前期。","路向长江上，帆揚細雨时。","春生南嶽早，日轉大荒遲。","尽採瀟湘句，重来會近期。"]', '诗', 'shi', '', NULL, '送友人遊湖南 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700f7795-49ec-42f6-b5a3-19a520c59336', '江上送友人南遊', '江上送友人南游', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["何處積鄉愁，天涯聚亂流。","岸長羣岫晚，湖闊片帆秋。","買酒過漁舍，分燈與釣舟。","瀟湘見來鴈，應念獨邊遊。"]', '["何处積乡愁，天涯聚亂流。","岸长羣岫晚，湖闊片帆秋。","買酒過漁舍，分灯與釣舟。","瀟湘见来鴈，應念独邊游。"]', '诗', 'shi', '', NULL, '江上送友人南遊 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85e0394-7595-4662-bf30-4bbed92eb890', '江南別友人', '江南別友人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["勞生故白頭，頭白未應休。","闕下難孤立，天涯尚旅遊。","聽猨吟島寺，待月上江樓。","醉別醒惆悵，雲帆滿亂流。"]', '["勞生故白头，头白未應休。","闕下难孤立，天涯尚旅游。","听猨吟島寺，待月上江楼。","醉別醒惆悵，云帆满亂流。"]', '诗', 'shi', '', NULL, '江南別友人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4f838a-a563-49da-822e-f3b7a7b446c1', '商山道中', '商山道中', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["春去計秋期，長安在夢思。","多逢山好處，少值客行時。","雲起爭峰勢，花交隱澗枝。","停驂一惆悵，應秪嶺猨知。"]', '["春去計秋期，长安在梦思。","多逢山好处，少值客行时。","云起爭峰勢，花交隐澗枝。","停驂一惆悵，應秪嶺猨知。"]', '诗', 'shi', '', NULL, '商山道中 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2d197a-aeb7-4134-9819-60598dc05330', '吳江旅次', '吳江旅次', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["行人愁落日，去鳥倦遙林。","曠野鳴流水，空山響暮砧。","旅途歸計晚，鄉樹別年深。","寂寞逢村酒，漁家一醉吟。"]', '["行人愁落日，去鸟倦遙林。","曠野鳴流水，空山响暮砧。","旅途归計晚，乡樹別年深。","寂寞逢村酒，漁家一醉吟。"]', '诗', 'shi', '', NULL, '吳江旅次 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8077d3-da95-431b-b6e9-f2510303935a', '寄南中友人', '寄南中友人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["相夢如相見，相思去後頻。","舊時行處斷，華髪別來新。","浪動三湘月，煙藏五嶺春。","又無歸北客，書札寄何人。"]', '["相梦如相见，相思去後頻。","旧时行处斷，华髪別来新。","浪动三湘月，煙藏五嶺春。","又無归北客，书札寄何人。"]', '诗', 'shi', '', NULL, '寄南中友人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ffa8288-5c0e-4f8d-9658-f33c9bc0377c', '寄績溪陳明府', '寄績溪陳明府', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["古邑猨聲裏，空城只半存。","岸移無舊路，沙漲別成村。","鼓角喧京口，江山盡汝濆。","六朝興廢地，行子一銷魂。"]', '["古邑猨声裏，空城只半存。","岸移無旧路，沙漲別成村。","鼓角喧京口，江山尽汝濆。","六朝兴廢地，行子一銷魂。"]', '诗', 'shi', '', NULL, '寄績溪陳明府 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f5e0c5-5fed-45bc-b03a-12c11491761b', '試月中桂', '試月中桂', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["與月轉洪濛，扶疎萬古同。","根非生下土，葉不墜秋風。","每以圓時足，還隨缺處空。","影高羣木外，香滿一輪中。","未種丹霄日，應虛玉兔宮。","何當因羽化，細得問玄功。"]', '["與月轉洪濛，扶疎万古同。","根非生下土，葉不墜秋风。","每以圓时足，還隨缺处空。","影高羣木外，香满一輪中。","未種丹霄日，應虛玉兔宮。","何當因羽化，細得问玄功。"]', '诗', 'shi', '', NULL, '試月中桂 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc10764-f488-4f16-8b47-033e829eb20c', '遊歙州興唐寺', '游歙州兴唐寺', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["山橋通絕境，到此憶天台。","竹裏尋幽徑，雲邊上古臺。","鳥歸殘照出，鐘斷細泉來。","爲愛澄溪月，因成隔宿迴。"]', '["山橋通絕境，到此憶天台。","竹裏尋幽徑，云邊上古台。","鸟归殘照出，鐘斷細泉来。","爲愛澄溪月，因成隔宿迴。"]', '诗', 'shi', '', NULL, '遊歙州興唐寺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff8dfde-34fb-410c-8cbe-90601ca2f855', '題詮律師院', '題詮律師院', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["院涼松雨聲，相對有山情。","未許谿邊老，猶思嶽頂行。","紗燈留火細，石井灌瓶清。","欲問吾師外，何人得此生。"]', '["院涼松雨声，相对有山情。","未許谿邊老，猶思嶽頂行。","紗灯留火細，石井灌瓶清。","欲问吾師外，何人得此生。"]', '诗', 'shi', '', NULL, '題詮律師院 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b869eb-0d87-4dbc-be12-8c3611e6891c', '金山寺空上人院', '金山寺空上人院', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["已老金山頂，無心上石橋。","講移三楚遍，梵譯五天遙。","板閣禪秋月，銅瓶汲夜潮。","自慙昏醉客，來坐亦通宵。"]', '["已老金山頂，無心上石橋。","講移三楚遍，梵譯五天遙。","板閣禪秋月，銅瓶汲夜潮。","自慙昏醉客，来坐亦通宵。"]', '诗', 'shi', '', NULL, '金山寺空上人院 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a0eac0-10ae-4c0a-bada-91f07b7deb60', '題廣信寺', '題廣信寺', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["亭北敞靈溪，林梢與檻齊。","野雲來影遠，沙鳥去行低。","晚渡明村火，晴山響郡鼙。","思鄉值搖落，賴不有猨啼。"]', '["亭北敞靈溪，林梢與檻齊。","野云来影远，沙鸟去行低。","晚渡明村火，晴山响郡鼙。","思乡值搖落，賴不有猨啼。"]', '诗', 'shi', '', NULL, '題廣信寺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173b8948-228c-469d-b296-a1f2c161f8ca', '興善寺貝多樹', '兴善寺貝多樹', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["還應毫末長，始見拂丹霄。","得子從西國，成陰見昔朝。","勢隨雙剎直，寒出四墻遙。","帶月啼春鳥，連空噪暝蜩。","遠根穿古井，高頂起涼飆。","影動懸燈夜，聲繁過雨朝。","靜遲松桂老，堅任雪霜凋。","永共終南在，應隨劫火燒。"]', '["還應毫末长，始见拂丹霄。","得子從西国，成陰见昔朝。","勢隨雙剎直，寒出四墻遙。","带月啼春鸟，連空噪暝蜩。","远根穿古井，高頂起涼飆。","影动懸灯夜，声繁過雨朝。","静遲松桂老，堅任雪霜凋。","永共終南在，應隨劫火燒。"]', '诗', 'shi', '', NULL, '興善寺貝多樹 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef373170-25e6-47be-a989-a1040dd4584f', '華山', '华山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["青蒼河一隅，氣狀杳難圖。","卓傑三峰出，高奇四岳無。","力疑擎上界，勢獨壓中區。","衆水東西走，羣山遠近趨。","天迴諸宿照，地聳百靈扶。","石壁煙霞麗，龍潭雨雹麤。","澄凝臨甸服，險固束神都。","淺覺川原異，深應日月殊。","鶴歸青靄合，仙去白雲孤。","瀑漏斜飛凍，松長倒挂枯。","每來尋洞穴，不擬返江湖。","儻有芝田種，巖間老一夫。"]', '["青蒼河一隅，氣狀杳难圖。","卓傑三峰出，高奇四岳無。","力疑擎上界，勢独壓中區。","衆水东西走，羣山远近趨。","天迴諸宿照，地聳百靈扶。","石壁煙霞丽，龙潭雨雹麤。","澄凝臨甸服，險固束神都。","淺覺川原異，深應日月殊。","鹤归青靄合，仙去白云孤。","瀑漏斜飞凍，松长倒挂枯。","每来尋洞穴，不擬返江湖。","儻有芝田種，巖间老一夫。"]', '诗', 'shi', '', NULL, '華山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79a22b2-0db9-4a47-bf47-595bd438e5ca', '送何道士歸山', '送何道士归山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["身非絕粒本清羸，束挂仙經杖一枝。","落葉獨尋流水去，深山長與白雲期。","樹臨丹竈寒花疾，壇近清嵐夜月遲。","樵客若能隨洞裏，迴歸人世始應悲。"]', '["身非絕粒本清羸，束挂仙經杖一枝。","落葉独尋流水去，深山长與白云期。","樹臨丹竈寒花疾，壇近清嵐夜月遲。","樵客若能隨洞裏，迴归人世始應悲。"]', '诗', 'shi', '', NULL, '送何道士歸山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5198cf6-e149-4edc-8bbf-74377ac47449', '城東寓居寄知己', '城东寓居寄知己', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["花木閑門苔蘚生，滻川特去得吟情。","病來久絕洞庭信，年長卻思廬岳耕。","落日獨歸林下宿，暮雲多遶水邊行。","干時退出長如此，頻愧相憂道姓名。"]', '["花木闲门苔蘚生，滻川特去得吟情。","病来久絕洞庭信，年长卻思廬岳耕。","落日独归林下宿，暮云多遶水邊行。","干时退出长如此，頻愧相憂道姓名。"]', '诗', 'shi', '', NULL, '城東寓居寄知己 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb671b1c-3850-416e-8fc4-cfa4c2cda3f7', '再書邊事', '再书邊事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["萬里沙西寇已平，犬羊羣外築空城。","分營夜火燒雲遠，校獵秋鵰掠草輕。","秦將力隨胡馬竭，蕃河流入漢家清。","羌戎不識干戈老，須賀當時聖主明。"]', '["万里沙西寇已平，犬羊羣外築空城。","分營夜火燒云远，校獵秋鵰掠草轻。","秦將力隨胡马竭，蕃河流入漢家清。","羌戎不識干戈老，須賀當时聖主明。"]', '诗', 'shi', '', NULL, '再書邊事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741ea37f-d711-4905-8a29-5456ae82b2b8', '遊邊感懷二首 一', '游邊感懷二首 一', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["貧遊繚繞困邊沙，却被遼陽戰士嗟。","不是無家歸不得，有家歸去似無家。"]', '["貧游繚繞困邊沙，却被遼陽戰士嗟。","不是無家归不得，有家归去似無家。"]', '诗', 'shi', '', NULL, '遊邊感懷二首 一 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbae0d2-65b4-42da-8a84-c73f9e1541f8', '遊邊感懷二首 二', '游邊感懷二首 二', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["兄弟江南身塞北，鴈飛猶自半年餘。","夜來因得思鄉夢，重讀前秋轉海書。"]', '["兄弟江南身塞北，鴈飞猶自半年餘。","夜来因得思乡梦，重读前秋轉海书。"]', '诗', 'shi', '', NULL, '遊邊感懷二首 二 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013ea317-616c-4455-a5f4-70c6fa19b393', '無題', '無題', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["九霄無詔下，何事觸清塵。","宅帶松蘿僻，身惟猨鳥親。","吟看仙掌月，期有洞庭人。","莫問煙霞句，懸知見岳神。"]', '["九霄無詔下，何事觸清塵。","宅带松蘿僻，身惟猨鸟親。","吟看仙掌月，期有洞庭人。","莫问煙霞句，懸知见岳神。"]', '诗', 'shi', '', NULL, '無題 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a678775-f915-49b4-90ec-10684835be2a', '蟬', '蟬', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["先秋蟬一悲，長是客行時。","曾感去年者，又鳴何處枝。","細聽殘韻在，迴望舊聲遲。","斷續誰家樹，涼風送別離。"]', '["先秋蟬一悲，长是客行时。","曾感去年者，又鳴何处枝。","細听殘韻在，迴望旧声遲。","斷續誰家樹，涼风送別離。"]', '诗', 'shi', '', NULL, '蟬 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2878d7-d77b-4ed7-bc30-4945f48182e3', '江上逢進士許棠', '江上逢進士許棠', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["詩人推上第，新榜又無君。","鶴髪他鄉老，漁歌故國聞。","平江流曉月，獨鳥伴餘雲。","且了髫年志，沙鷗未可羣。"]', '["诗人推上第，新榜又無君。","鹤髪他乡老，漁歌故国闻。","平江流晓月，独鸟伴餘云。","且了髫年志，沙鷗未可羣。"]', '诗', 'shi', '', NULL, '江上逢進士許棠 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0879d94f-3cc1-4458-8bcf-3b5d2206cb08', '送河西從事', '送河西從事', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["結束佐戎旃，河西住幾年。","隴頭隨日去，磧裏寄星眠。","水近沙連帳，程遙馬入天。","聖朝思上策，重待奏安邊。"]', '["結束佐戎旃，河西住幾年。","隴头隨日去，磧裏寄星眠。","水近沙連帳，程遙马入天。","聖朝思上策，重待奏安邊。"]', '诗', 'shi', '', NULL, '送河西從事 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d574dd-045f-4cef-a102-77d22289f6ec', '河湟舊卒', '河湟旧卒', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["少年隨將討河湟，頭白時清返故鄉。","十萬漢軍零落盡，獨吹邊曲向殘陽。"]', '["少年隨將討河湟，头白时清返故乡。","十万漢軍零落尽，独吹邊曲向殘陽。"]', '诗', 'shi', '', NULL, '河湟舊卒 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa1699d-1936-42d7-bb1c-716ced12fdb2', '促織', '促织', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["念爾無機自有情，迎寒辛苦弄梭聲。","椒房金屋何曾識，偏向貧家壁下鳴。"]', '["念爾無機自有情，迎寒辛苦弄梭声。","椒房金屋何曾識，偏向貧家壁下鳴。"]', '诗', 'shi', '', NULL, '促織 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3df47d70-81a0-42ab-8a8b-87f11fba968f', '猨', '猨', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["挂月棲雲向楚林，取來全是爲清音。","誰知繫在黃金索，翻畏侯家不敢吟。"]', '["挂月棲云向楚林，取来全是爲清音。","誰知繫在黄金索，翻畏侯家不敢吟。"]', '诗', 'shi', '', NULL, '猨 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f111b723-9679-4381-a8b9-3183f55bac2a', '寄薦福寺棲白大師', '寄薦福寺棲白大師', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["高塔六街無不見，塔邊名出秪吾師。","嘗聞朝客多相□，記得□□數句詩。"]', '["高塔六街無不见，塔邊名出秪吾師。","嘗闻朝客多相□，記得□□數句诗。"]', '诗', 'shi', '', NULL, '寄薦福寺棲白大師 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fac468-9df3-4e36-8f96-8ab61172fffd', '越中贈別', '越中贈別', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["東越相逢幾醉眠，滿樓明月鏡湖邊。","別離吟斷西陵渡，楊柳秋風兩岸蟬。"]', '["东越相逢幾醉眠，满楼明月镜湖邊。","別離吟斷西陵渡，楊柳秋风兩岸蟬。"]', '诗', 'shi', '', NULL, '越中贈別 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72561e12-6f17-4f35-96cb-fc591e621567', '寄清越上人', '寄清越上人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["大道本來無所染，白雲那得有心期。","遠公獨刻蓮花漏，猶向空山禮六時。"]', '["大道本来無所染，白云那得有心期。","远公独刻蓮花漏，猶向空山禮六时。"]', '诗', 'shi', '', NULL, '寄清越上人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b71b83-daeb-4af4-a4b6-7683d664fd88', '宿齊山僧舍', '宿齊山僧舍', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一宿經窗臥白波，萬重歸夢隔煙蘿。","若言不得南宗要，長在禪牀事更多。"]', '["一宿經窗臥白波，万重归梦隔煙蘿。","若言不得南宗要，长在禪牀事更多。"]', '诗', 'shi', '', NULL, '宿齊山僧舍 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbd5b98b-d62a-4efb-bc61-ff102d7d09c9', '宿齊山僧舍', '宿齊山僧舍', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一宿經窗望白波，曉隨山月出煙蘿。","若言不得南宗要，長在禪牀事更多。"]', '["一宿經窗望白波，晓隨山月出煙蘿。","若言不得南宗要，长在禪牀事更多。"]', '诗', 'shi', '', NULL, '宿齊山僧舍 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7572fbc6-e028-4516-bd45-69f12a0861b8', '春日遊曲江', '春日游曲江', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["日暖鴛鴦拍浪春，蒹葭浦際聚青蘋。","若論來往鄉心切，須是煙波島上人。"]', '["日暖鴛鴦拍浪春，蒹葭浦際聚青蘋。","若論来往乡心切，須是煙波島上人。"]', '诗', 'shi', '', NULL, '春日遊曲江 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5921ec-d74f-413b-b0fc-a114076c747c', '漁家', '漁家', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["擁棹思悠悠，更深泛積流。","唯將一星火，何處宿蘆洲。"]', '["擁棹思悠悠，更深泛積流。","唯將一星火，何处宿蘆洲。"]', '诗', 'shi', '', NULL, '漁家 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11300d0c-362c-4b25-8df1-7e5f6963e30b', '送人及第歸海東', '送人及第归海东', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["東風日邊起，草木一時春。","自笑中華路，年年送遠人。"]', '["东风日邊起，草木一时春。","自笑中华路，年年送远人。"]', '诗', 'shi', '', NULL, '送人及第歸海東 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0af0529-265c-4969-9acc-0d9bec5cf709', '題河中鸛雀樓', '題河中鸛雀楼', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["高樓懷古動悲歌，鸛雀今無野燕過。","樹隔五陵秋色早，水連三晉夕陽多。","漁人遺火成寒燒，牧笛吹風起夜波。","十載重來值搖落，天涯歸計欲如何。"]', '["高楼懷古动悲歌，鸛雀今無野燕過。","樹隔五陵秋色早，水連三晉夕陽多。","漁人遺火成寒燒，牧笛吹风起夜波。","十載重来值搖落，天涯归計欲如何。"]', '诗', 'shi', '', NULL, '題河中鸛雀樓 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a76b693-e322-4688-9dd7-098cf380991b', '宿洛都門', '宿洛都门', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["山川馬上度邊禽，一宿都門永夜吟。","客路不歸秋又晚，西風吹動洛陽砧。"]', '["山川马上度邊禽，一宿都门永夜吟。","客路不归秋又晚，西风吹动洛陽砧。"]', '诗', 'shi', '', NULL, '宿洛都門 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee4ebe2-0939-4c49-b8bd-d88471711e2a', '對月二首 一', '对月二首 一', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["圓魄上寒空，皆言四海同。","安知千里外，不有雨兼風。"]', '["圓魄上寒空，皆言四海同。","安知千里外，不有雨兼风。"]', '诗', 'shi', '', NULL, '對月二首 一 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a6e89f-5d94-4d06-921a-539f5f057611', '對月二首 二', '对月二首 二', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["盈缺青冥外，東風萬古吹。","何人種丹桂，不長出輪枝。"]', '["盈缺青冥外，东风万古吹。","何人種丹桂，不长出輪枝。"]', '诗', 'shi', '', NULL, '對月二首 二 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa22688e-e812-418b-8b6b-7fbd45950086', '贈友人', '贈友人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["自說安貧歸未得，竹邊門掩小池冰。","典琴賒酒吟過寺，送客思鄉上灞陵。","待月夜留煙島客，憶雲閑訪翠微僧。","幾時獻了相如賦，共向嵩山採茯苓。"]', '["自说安貧归未得，竹邊门掩小池冰。","典琴賒酒吟過寺，送客思乡上灞陵。","待月夜留煙島客，憶云闲訪翠微僧。","幾时獻了相如賦，共向嵩山採茯苓。"]', '诗', 'shi', '', NULL, '贈友人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5d644c-3353-4329-b751-1aca34836c4d', '笛', '笛', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["剪雨裁煙一節秋，落梅楊柳曲中愁。","尊前暫借殷勤看，明日曾聞向隴頭。"]', '["剪雨裁煙一節秋，落梅楊柳曲中愁。","尊前暫借殷勤看，明日曾闻向隴头。"]', '诗', 'shi', '', NULL, '笛 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a98f6d-e367-43a4-b173-4a3fdf5dcca0', '漁者', '漁者', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["首戴圓荷髪不梳，葉舟爲宅水爲居。","沙頭聚看人如市，釣得澄江一丈魚。"]', '["首戴圓荷髪不梳，葉舟爲宅水爲居。","沙头聚看人如市，釣得澄江一丈鱼。"]', '诗', 'shi', '', NULL, '漁者 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40165616-5d7a-4119-969e-099cf6fe8147', '宿潺湲亭', '宿潺湲亭', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["走月流煙疊樹西，聽來愁甚聽猨啼。","幾時御水聲邊住，却夢潺湲宿此溪。"]', '["走月流煙叠樹西，听来愁甚听猨啼。","幾时御水声邊住，却梦潺湲宿此溪。"]', '诗', 'shi', '', NULL, '宿潺湲亭 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0106d1-6b21-468a-bfdc-2ca84a4cb4a4', '臺城', '台城', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["宮殿餘基長草花，景陽宮樹噪村鴉。","雲屯雉堞依然在，空繞漁樵四五家。"]', '["宮殿餘基长草花，景陽宮樹噪村鴉。","云屯雉堞依然在，空繞漁樵四五家。"]', '诗', 'shi', '', NULL, '臺城 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec4f514-9027-4764-b3d5-7de9107f3269', '寄山僧', '寄山僧', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["閑倚蒲團向日眠，不能歸老岳雲邊。","舊時僧侶無人在，惟有長松見少年。"]', '["闲倚蒲團向日眠，不能归老岳云邊。","旧时僧侶無人在，惟有长松见少年。"]', '诗', 'shi', '', NULL, '寄山僧 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b737f57b-3510-49cd-8415-628f307bde52', '題上元許棠所任王昌齡廳', '題上元許棠所任王昌齡廳', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["瑠璃堂裏當時客，久絕吟聲繼後塵。","百四十年庭樹老，如今重得見詩人。"]', '["瑠璃堂裏當时客，久絕吟声繼後塵。","百四十年庭樹老，如今重得见诗人。"]', '诗', 'shi', '', NULL, '題上元許棠所任王昌齡廳 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c492ce-b641-4f65-9b0d-ef79257e63f8', '自誚', '自誚', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["每到花時恨道窮，一生光景半成空。","只應抱璞非良玉，豈得年年不至公。"]', '["每到花时恨道窮，一生光景半成空。","只應抱璞非良玉，豈得年年不至公。"]', '诗', 'shi', '', NULL, '自誚 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b93005-b78c-4c14-b219-9b0d0e802e49', '贈河南詩友', '贈河南诗友', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["山東令族玉無塵，裁剪煙花筆下春。","不把瑤華借風月，洛陽才子更何人。"]', '["山东令族玉無塵，裁剪煙花笔下春。","不把瑤华借风月，洛陽才子更何人。"]', '诗', 'shi', '', NULL, '贈河南詩友 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0648c317-8e84-4ff6-814f-123c0b9d9a04', '寄維揚故人', '寄維揚故人', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["離別河邊綰柳條，千山萬水玉人遙。","月明記得相尋處，城鎖東風十五橋。"]', '["離別河邊綰柳條，千山万水玉人遙。","月明記得相尋处，城鎖东风十五橋。"]', '诗', 'shi', '', NULL, '寄維揚故人 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36bde069-941f-4103-be62-321d7cf0fd74', '孤雲', '孤云', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["舒卷因風何所之，碧天孤影勢遲遲。","莫言長是無心物，還有隨龍作雨時。"]', '["舒卷因风何所之，碧天孤影勢遲遲。","莫言长是無心物，還有隨龙作雨时。"]', '诗', 'shi', '', NULL, '孤雲 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9fc1ad3-4fce-4ba4-8582-bb6ec792ab67', '詠棋子贈弈僧', '詠棋子贈弈僧', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["黑白誰能用入玄，千回生死體方圓。","空門說得恆沙劫，應笑終年爲一先。"]', '["黑白誰能用入玄，千回生死體方圓。","空门说得恆沙劫，應笑終年爲一先。"]', '诗', 'shi', '', NULL, '詠棋子贈弈僧 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de5f7bf-6476-4d34-9439-8ba3a0934b4c', '谷口作', '谷口作', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["巴客青冥過嶺塵，雪崖交映一川春。","晴朝採藥尋源去，必恐雲深見異人。"]', '["巴客青冥過嶺塵，雪崖交映一川春。","晴朝採藥尋源去，必恐云深见異人。"]', '诗', 'shi', '', NULL, '谷口作 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab9bb2c-10ce-4a2a-817a-38ba1c2f325a', '寄弟', '寄弟', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["故里行人戰後疎，青崖萍寄白雲居。","那堪又是傷春日，把得長安落第書。"]', '["故里行人戰後疎，青崖萍寄白云居。","那堪又是傷春日，把得长安落第书。"]', '诗', 'shi', '', NULL, '寄弟 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1bab312-82d5-413a-b0e5-5a77be070edc', '春日有懷', '春日有懷', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["高下尋花春景遲，汾陽臺榭白雲詩。","看山懷古翻惆悵，未勝遙傳不到時。"]', '["高下尋花春景遲，汾陽台榭白云诗。","看山懷古翻惆悵，未勝遙傳不到时。"]', '诗', 'shi', '', NULL, '春日有懷 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3341c9e-c49b-4f83-a084-175106ac0e0e', '鷺鷥障子', '鷺鷥障子', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["剪得機中如雪素，畫爲江上帶絲禽。","閑來相對茅堂下，引出煙波萬里心。"]', '["剪得機中如雪素，畫爲江上带絲禽。","闲来相对茅堂下，引出煙波万里心。"]', '诗', 'shi', '', NULL, '鷺鷥障子 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08e4bd5-7af6-48a0-9263-6740114e3041', '甘露寺僧房', '甘露寺僧房', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["臨水登山路，重尋旅思勞。","竹陰行處密，僧臘別來高。","遠岫明寒火，危樓響夜濤。","悲秋不成寐，明月上千舠。"]', '["臨水登山路，重尋旅思勞。","竹陰行处密，僧臘別来高。","远岫明寒火，危楼响夜濤。","悲秋不成寐，明月上千舠。"]', '诗', 'shi', '', NULL, '甘露寺僧房 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d377ce-4f11-4de1-b7ef-c7b71ccbfeb2', '宿江叟島居', '宿江叟島居', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一家煙島隈，竹裏夜窗開。","數派分潮去，千檣聚月來。","石樓雲斷續，澗渚鴈徘徊。","了得平生志，還歸築釣臺。"]', '["一家煙島隈，竹裏夜窗开。","數派分潮去，千檣聚月来。","石楼云斷續，澗渚鴈徘徊。","了得平生志，還归築釣台。"]', '诗', 'shi', '', NULL, '宿江叟島居 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d2fb63-14b0-4633-995b-158213cd4380', '江村', '江村', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["貧遊無定蹤，鄉信轉難逢。","寒渚暮煙闊，去帆歸思重。","潮平低戍火，木落遠山鐘。","況是漁家宿，疎籬響夜舂。"]', '["貧游無定蹤，乡信轉难逢。","寒渚暮煙闊，去帆归思重。","潮平低戍火，木落远山鐘。","況是漁家宿，疎籬响夜舂。"]', '诗', 'shi', '', NULL, '江村 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f095bdc-f572-422f-bea4-1076af9dfeb4', '贈進士顧雲', '贈進士顧云', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["潮檻煙波別釣津，西京同□荻□貧。","不知守道歸何日，相對無言盡幾春。","晴景遠山花外暮，雲邊高蓋水邊□。","與君愁寂無消處，賒酒青門送楚人。"]', '["潮檻煙波別釣津，西京同□荻□貧。","不知守道归何日，相对無言尽幾春。","晴景远山花外暮，云邊高蓋水邊□。","與君愁寂無消处，賒酒青门送楚人。"]', '诗', 'shi', '', NULL, '贈進士顧雲 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68d7f43-5046-4c5a-a7b6-074e1783ba38', '贈頭陀僧', '贈头陀僧', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["自說年深別石橋，遍遊靈跡熟南朝。","已知世路皆虛幻，不覺空門是寂寥。","滄海附船浮浪久，碧山尋塔上雲遙。","如今竹院藏衰老，一點寒燈弟子燒。"]', '["自说年深別石橋，遍游靈跡熟南朝。","已知世路皆虛幻，不覺空门是寂寥。","滄海附船浮浪久，碧山尋塔上云遙。","如今竹院藏衰老，一点寒灯弟子燒。"]', '诗', 'shi', '', NULL, '贈頭陀僧 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ffe0e8-195d-4f2a-b378-40658be1beac', '尋陽村舍', '尋陽村舍', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["荒林寄遠居，坐臥見樵漁。","夜火隨船遠，寒更出郡疎。","雪迷登岳路，風阻轉江書。","寂寞高窗下，思鄉歲欲除。"]', '["荒林寄远居，坐臥见樵漁。","夜火隨船远，寒更出郡疎。","雪迷登岳路，风阻轉江书。","寂寞高窗下，思乡歲欲除。"]', '诗', 'shi', '', NULL, '尋陽村舍 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c01d6b1-945b-45df-bc02-3cd671b258a9', '江樓作', '江楼作', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["憑檻見天涯，非秋亦可悲。","晚天帆去疾，春雪燕來遲。","山水分鄉縣，干戈足別離。","南人廢耕織，早晚罷王師。"]', '["憑檻见天涯，非秋亦可悲。","晚天帆去疾，春雪燕来遲。","山水分乡縣，干戈足別離。","南人廢耕织，早晚罷王師。"]', '诗', 'shi', '', NULL, '江樓作 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0ff1fe-2c03-4b3e-8dd0-ad2a223416c2', '回鸞閣寫望', '回鸾閣寫望', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["古閣上空半，寥寥千里心。","多年爲客路，盡日倚欄吟。","山壓秦川重，河來虜塞深。","回鑾今不見，煙霧杳沉沉。"]', '["古閣上空半，寥寥千里心。","多年爲客路，尽日倚欄吟。","山壓秦川重，河来虜塞深。","回鑾今不见，煙霧杳沉沉。"]', '诗', 'shi', '', NULL, '回鸞閣寫望 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd75b1f-9924-4ee8-bd23-9aafb516ec3d', '題宣州開元寺', '題宣州开元寺', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["誰家煙徑長莓苔，金碧虛欄竹上開。","流水遠分山色斷，清猨時帶角聲來。","六朝明月唯詩在，三楚空山有鴈迴。","達理始應盡惆悵，僧閑應得話天台。"]', '["誰家煙徑长莓苔，金碧虛欄竹上开。","流水远分山色斷，清猨时带角声来。","六朝明月唯诗在，三楚空山有鴈迴。","達理始應尽惆悵，僧闲應得話天台。"]', '诗', 'shi', '', NULL, '題宣州開元寺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcc1839-e35b-4608-89cb-316bc863911f', '題友人草堂', '題友人草堂', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["空山卜隱初，生計亦無餘。","三畝水邊竹，一床琴畔書。","深林收晚果，絕頂拾秋蔬。","堅話長如此，何年獻子虛。"]', '["空山卜隐初，生計亦無餘。","三畝水邊竹，一床琴畔书。","深林收晚果，絕頂拾秋蔬。","堅話长如此，何年獻子虛。"]', '诗', 'shi', '', NULL, '題友人草堂 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8398ff87-94b9-420a-a5f4-6d3239431fec', '七松亭', '七松亭', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["七松亭上望秦川，高鳥閑雲滿目前。","已比子真耕谷口，豈同陶令臥江邊。","臨崖把卷驚迴燒，掃石留僧聽遠泉。","明月影中宮漏近，珮聲應宿使朝天。"]', '["七松亭上望秦川，高鸟闲云满目前。","已比子真耕谷口，豈同陶令臥江邊。","臨崖把卷驚迴燒，掃石留僧听远泉。","明月影中宮漏近，珮声應宿使朝天。"]', '诗', 'shi', '', NULL, '七松亭 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3745325f-2413-45a3-b19b-4fff8e023cc2', '題友人林齋', '題友人林斋', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["喬木帶涼蟬，來吟暑雨天。","不離高枕上，似宿遠山邊。","簟冷窗中月，茶香竹裏泉。","吾廬近溪島，憶別動經年。"]', '["喬木带涼蟬，来吟暑雨天。","不離高枕上，似宿远山邊。","簟冷窗中月，茶香竹裏泉。","吾廬近溪島，憶別动經年。"]', '诗', 'shi', '', NULL, '題友人林齋 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7800bf54-49ad-46cd-8488-95bd78200e8d', '經宣城元員外山居', '經宣城元員外山居', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["無人襲仙隱，石室閉空山。","避燒猨猶到，隨雲鶴不還。","澗荒巖影在，橋斷樹陰閑。","但有黃河賦，長留在世間。"]', '["無人襲仙隐，石室閉空山。","避燒猨猶到，隨云鹤不還。","澗荒巖影在，橋斷樹陰闲。","但有黄河賦，长留在世间。"]', '诗', 'shi', '', NULL, '經宣城元員外山居 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af878e9-cdd4-459a-a05a-603fe49909cf', '經九華山費徵君故居', '經九华山費徵君故居', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["草堂蕪沒後，來往問樵翁。","斷石荒林外，孤墳晚照中。","數溪分大野，九子立寒空。","煙壁曾行處，青雲路不通。"]', '["草堂蕪沒後，来往问樵翁。","斷石荒林外，孤墳晚照中。","數溪分大野，九子立寒空。","煙壁曾行处，青云路不通。"]', '诗', 'shi', '', NULL, '經九華山費徵君故居 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0814b58c-879d-4e70-bbe1-29ec7e9bf37b', '題賈島吟詩臺', '題賈島吟诗台', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["吟魂不復遊，臺亦似荒丘。","一徑草中出，長江天外流。","暝煙寒鳥集，殘月夜蟲愁。","願得生禾黍，鋤平恨即休。"]', '["吟魂不复游，台亦似荒丘。","一徑草中出，长江天外流。","暝煙寒鸟集，殘月夜蟲愁。","願得生禾黍，鋤平恨即休。"]', '诗', 'shi', '', NULL, '題賈島吟詩臺 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3805cb81-114a-40ca-8eb5-028c0c9d0165', '遊南岳', '游南岳', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["入巖仙境清，行盡復重行。","若得閑無事，長來寄此生。","澗松閑易老，籠燭晚生明。","一宿泉聲裏，思鄉夢不成。"]', '["入巖仙境清，行尽复重行。","若得闲無事，长来寄此生。","澗松闲易老，籠燭晚生明。","一宿泉声裏，思乡梦不成。"]', '诗', 'shi', '', NULL, '遊南岳 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a4c495-3f07-4d11-b30a-5ccfc6210734', '尋桃源', '尋桃源', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["武林春草齊，花影隔澄溪。","路遠無人去，山空有鳥啼。","水垂青靄斷，松偃綠蘿低。","世上迷途客，經茲盡不迷。"]', '["武林春草齊，花影隔澄溪。","路远無人去，山空有鸟啼。","水垂青靄斷，松偃綠蘿低。","世上迷途客，經茲尽不迷。"]', '诗', 'shi', '', NULL, '尋桃源 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcba299-a46b-4b5d-bd57-7f5df0787cd3', '青鳥泉', '青鸟泉', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["祗此沉仙翼，瑤池似不遙。","有聲懸翠壁，無勢下丹霄。","淨瀨煙霞古，寒原草木凋。","山河幾更變，幽咽到唐朝。"]', '["祗此沉仙翼，瑤池似不遙。","有声懸翠壁，無勢下丹霄。","淨瀨煙霞古，寒原草木凋。","山河幾更变，幽咽到唐朝。"]', '诗', 'shi', '', NULL, '青鳥泉 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9079d2a2-4ca7-440f-90c0-fbb73330e997', '望巫山', '望巫山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["溪疊雲深轉谷遲，暝投孤店草蟲悲。","愁連遠水波濤夜，夢斷空山雨雹時。","邊海故園荒後買，入關玄髪夜來衰。","東歸未必勝羈旅，況是東歸未有期。"]', '["溪叠云深轉谷遲，暝投孤店草蟲悲。","愁連远水波濤夜，梦斷空山雨雹时。","邊海故园荒後買，入关玄髪夜来衰。","东归未必勝羈旅，況是东归未有期。"]', '诗', 'shi', '', NULL, '望巫山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3060f939-c1df-4b2b-9dcf-fad407145f75', '省中偶作', '省中偶作', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["二轉郎曹自勉旃，莎階吟步想前賢。","不如何遜無佳句，若比馮唐是壯年。","捧制名題黃紙尾，約僧心在白雲邊。","乳毛松雪春來好，直夜清閑且學禪。"]', '["二轉郎曹自勉旃，莎階吟步想前賢。","不如何遜無佳句，若比馮唐是壯年。","捧制名題黄紙尾，約僧心在白云邊。","乳毛松雪春来好，直夜清闲且学禪。"]', '诗', 'shi', '', NULL, '省中偶作 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e22fdfe-3e2f-4130-a417-bb748a736edd', '秋夕', '秋夕', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["春恨復秋悲，秋悲難到時。","每逢明月夜，長起故山思。","巷僻行吟遠，蛩多獨臥遲。","溪僧與樵客，動別十年期。"]', '["春恨复秋悲，秋悲难到时。","每逢明月夜，长起故山思。","巷僻行吟远，蛩多独臥遲。","溪僧與樵客，动別十年期。"]', '诗', 'shi', '', NULL, '秋夕 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d853633-4327-42cd-aed2-ee371fe58ec5', '山中冬夜', '山中冬夜', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["寒葉風搖盡，空林鳥宿稀。","澗冰妨鹿飲，山雪阻僧歸。","夜坐塵心定，長吟語力微。"]', '["寒葉风搖尽，空林鸟宿稀。","澗冰妨鹿饮，山雪阻僧归。","夜坐塵心定，长吟語力微。"]', '诗', 'shi', '', NULL, '山中冬夜 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6705ee-8be3-43e1-a22e-e8fadb9fe06a', '宿劉溫書齋', '宿劉溫书斋', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["不掩盈窗月，天然格調高。","涼風移蟋蟀，落葉在離騷。","迴筆挑燈燼，懸圖見海濤。","因論三國志，空載幾英豪。"]', '["不掩盈窗月，天然格調高。","涼风移蟋蟀，落葉在離騷。","迴笔挑灯燼，懸圖见海濤。","因論三国志，空載幾英豪。"]', '诗', 'shi', '', NULL, '宿劉溫書齋 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98014159-5660-4ef0-bdce-16012d97b35c', '歸舊山', '归旧山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["昔年山下結茅茨，村落重來野徑移。","樵客相逢悲往事，林僧閑坐問歸期。","異藤遍樹無空處，幽草緣溪少歇時。","此景一拋吟欲老，可能文字聖朝知。"]', '["昔年山下結茅茨，村落重来野徑移。","樵客相逢悲往事，林僧闲坐问归期。","異藤遍樹無空处，幽草緣溪少歇时。","此景一拋吟欲老，可能文字聖朝知。"]', '诗', 'shi', '', NULL, '歸舊山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2617d2ea-5a0f-4485-b0cf-07203461453d', '潭上作', '潭上作', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["竹島殘陽映翠微，雪翎禽過碧潭飛。","人間未有關身事，每到漁家不欲歸。"]', '["竹島殘陽映翠微，雪翎禽過碧潭飞。","人间未有关身事，每到漁家不欲归。"]', '诗', 'shi', '', NULL, '潭上作 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c9bfc7-5f9b-4585-af8b-a1634cc298b2', '楊花落', '楊花落', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["北斗南回春物老，紅英落盡綠尚早。","韶風澹蕩無所依，偏惜垂楊作春好。","此時可憐楊柳花，縈盈豔曳滿人家。","人家女兒出羅幕，淨掃玉除看花落。","寶環纖手捧更飛，翠羽輕裙承不著。","歷歷瑤琴舞袖陳，飛紅拂黛憐玉人。","東園桃李芳已歇，猶有楊花嬌暮春。"]', '["北斗南回春物老，紅英落尽綠尚早。","韶风澹蕩無所依，偏惜垂楊作春好。","此时可怜楊柳花，縈盈豔曳满人家。","人家女兒出羅幕，淨掃玉除看花落。","寶环纖手捧更飞，翠羽轻裙承不著。","歷歷瑤琴舞袖陳，飞紅拂黛怜玉人。","东园桃李芳已歇，猶有楊花嬌暮春。"]', '诗', 'shi', '', NULL, '楊花落 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a71457b4-1633-488e-8ba4-1265f0a20156', '九華樓晴望', '九华楼晴望', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["一夜江潭風雨後，九華晴望倚天秋。","重來此地知何日，欲別殷勤更上樓。"]', '["一夜江潭风雨後，九华晴望倚天秋。","重来此地知何日，欲別殷勤更上楼。"]', '诗', 'shi', '', NULL, '九華樓晴望 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c5b0a0-b08a-4ae7-b60a-b877ce9a18b7', '終南山', '終南山', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["帶雪復銜春，橫天占半秦。","勢奇看不定，景變寫難真。","洞遠皆通岳，川多更有神。","白雲幽絕處，自古屬樵人。"]', '["带雪复銜春，橫天占半秦。","勢奇看不定，景变寫难真。","洞远皆通岳，川多更有神。","白云幽絕处，自古屬樵人。"]', '诗', 'shi', '', NULL, '終南山 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5feeaa1c-7e0d-4bc7-809c-02a71ce5c376', '哭陳陶', '哭陳陶', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["先生抱衰疾，不起茂陵間。","夕臨諸孤少，荒居弔客還。","遺文禪東岳，留語葬鄉山。","多雨銘旌故，殘燈素帳閑。","樂章誰與集，隴樹即堪攀。","神理今難問，予將呌帝關。"]', '["先生抱衰疾，不起茂陵间。","夕臨諸孤少，荒居弔客還。","遺文禪东岳，留語葬乡山。","多雨銘旌故，殘灯素帳闲。","乐章誰與集，隴樹即堪攀。","神理今难问，予將呌帝关。"]', '诗', 'shi', '', NULL, '哭陳陶 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e2ecc5-b67a-4498-ab42-781a23bb2c27', '長門怨', '长门怨', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["御泉長繞鳳皇樓，自是恩波別處流。","閑揲舞衣歸未得，夜來砧杵六宮秋。"]', '["御泉长繞鳳皇楼，自是恩波別处流。","闲揲舞衣归未得，夜来砧杵六宮秋。"]', '诗', 'shi', '', NULL, '長門怨 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a103eda0-b3fd-4504-ab3c-6fb4a0b26f3d', '昇平詞五首 一', '昇平词五首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["瑞氣遶宮樓，皇居上苑游。","遠岡連聖祚，平地載神州。","會合兼重譯，潺湲近八流。","中興豈假問，據此自千秋。"]', '["瑞氣遶宮楼，皇居上苑游。","远岡連聖祚，平地載神州。","會合兼重譯，潺湲近八流。","中兴豈假问，據此自千秋。"]', '诗', 'shi', '', NULL, '昇平詞五首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eac73d8-38fa-4810-bf49-7f90608883a5', '昇平詞五首 二', '昇平词五首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["寥泬敞延英，朝班立位橫。","宣傳無草動，拜舞有衣聲。","鴛瓦霜消濕，蟲絲日照明。","辛勤自不到，遙見似前程。"]', '["寥泬敞延英，朝班立位橫。","宣傳無草动，拜舞有衣声。","鴛瓦霜消濕，蟲絲日照明。","辛勤自不到，遙见似前程。"]', '诗', 'shi', '', NULL, '昇平詞五首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83117785-1aae-4dd3-b3ca-cf2e0ca678b2', '昇平詞五首 三', '昇平词五首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["處處是歡心，時康歲已深。","不同三尺劒，應似五弦琴。","壽笑山猶盡，明嫌日有陰。","何當憐一物，亦遺斷愁吟。"]', '["处处是歡心，时康歲已深。","不同三尺劒，應似五弦琴。","壽笑山猶尽，明嫌日有陰。","何當怜一物，亦遺斷愁吟。"]', '诗', 'shi', '', NULL, '昇平詞五首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22730830-cf5b-4f48-9302-ce9c898bee23', '昇平詞五首 四', '昇平词五首 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["日日聽歌謠，區中盡祝堯。","蟲蝗初不害，夷狄近全銷。","史筆唯書瑞，天臺絕見妖。","因令匹夫志，轉欲事清朝。"]', '["日日听歌謠，區中尽祝堯。","蟲蝗初不害，夷狄近全銷。","史笔唯书瑞，天台絕见妖。","因令匹夫志，轉欲事清朝。"]', '诗', 'shi', '', NULL, '昇平詞五首 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f8b040-292d-4630-ae51-86b5365e6b38', '昇平詞五首 五', '昇平词五首 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["五帝三皇主，蕭曹魏邴臣。","文章唯返朴，戈甲盡生塵。","諫紙應無用，朝綱自有倫。","昇平不可記，所見是閑人。"]', '["五帝三皇主，蕭曹魏邴臣。","文章唯返朴，戈甲尽生塵。","諫紙應無用，朝綱自有倫。","昇平不可記，所见是闲人。"]', '诗', 'shi', '', NULL, '昇平詞五首 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb35531c-3751-4dc0-9505-7ccbe39a504f', '洛東蘭若歸', '洛东蘭若归', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["一衲老禪床，吾生半異鄉。","管弦愁裏老，書劒夢中忙。","鳥急山初暝，蟬稀樹正涼。","又歸何處去，塵路月蒼蒼。"]', '["一衲老禪床，吾生半異乡。","管弦愁裏老，书劒梦中忙。","鸟急山初暝，蟬稀樹正涼。","又归何处去，塵路月蒼蒼。"]', '诗', 'shi', '', NULL, '洛東蘭若歸 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c347c7aa-4e3b-49dc-ba59-ebd7da87f872', '仙都即景', '仙都即景', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["黃帝登真處，青青不記年。","孤峰應礙日，一柱自擎天。","石怪長棲鶴，雲閑若有仙。","鼎湖看不見，零落數枝蓮。"]', '["黄帝登真处，青青不記年。","孤峰應礙日，一柱自擎天。","石怪长棲鹤，云闲若有仙。","鼎湖看不见，零落數枝蓮。"]', '诗', 'shi', '', NULL, '仙都即景 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9fcd28-5e5b-4322-a8fe-ba67cf1c3f90', '漢武帝將候西王母下降', '漢武帝將候西王母下降', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["崑崙凝想最高峰，王母來乘五色龍。","歌聽紫鸞猶縹緲，語來青鳥許從容。","風迴水落三清月，漏苦霜傳五夜鐘。","樹影悠悠花悄悄，若聞簫管是行蹤。"]', '["崑崙凝想最高峰，王母来乘五色龙。","歌听紫鸾猶縹緲，語来青鸟許從容。","风迴水落三清月，漏苦霜傳五夜鐘。","樹影悠悠花悄悄，若闻簫管是行蹤。"]', '诗', 'shi', '', NULL, '漢武帝將候西王母下降 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21e0ad6-2739-41bc-8476-7af65282a844', '漢武帝於宮中宴西王母', '漢武帝於宮中宴西王母', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["鼇岫雲低太一壇，武皇齋潔不勝懽。","長生碧字期親署，延壽丹泉許細看。","劒佩有聲宮樹靜，星河無影禁花寒。","秋風褭褭月朗朗，玉女清歌一夜闌。"]', '["鼇岫云低太一壇，武皇斋潔不勝懽。","长生碧字期親署，延壽丹泉許細看。","劒佩有声宮樹静，星河無影禁花寒。","秋风褭褭月朗朗，玉女清歌一夜闌。"]', '诗', 'shi', '', NULL, '漢武帝於宮中宴西王母 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ef8154-75da-4136-a018-36b95fba1bd4', '劉晨阮肇遊天台', '劉晨阮肇游天台', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["樹入天台石路新，雲和草靜迥無塵。","煙霞不省生前事，水木空疑夢後身。","往往雞鳴巖下月，時時犬吠洞中春。","不知此地歸何處，須就桃源問主人。"]', '["樹入天台石路新，云和草静迥無塵。","煙霞不省生前事，水木空疑梦後身。","往往雞鳴巖下月，时时犬吠洞中春。","不知此地归何处，須就桃源问主人。"]', '诗', 'shi', '', NULL, '劉晨阮肇遊天台 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6bdbc47-6fcd-459a-a52b-441714614a87', '劉阮洞中遇仙子', '劉阮洞中遇仙子', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["天和樹色靄蒼蒼，霞重嵐深路渺茫。","雲實滿山無鳥雀，水聲沿澗有笙簧。","碧沙洞裏乾坤別，紅樹枝前日月長。","願得花間有人出，免令仙犬吠劉郎。"]', '["天和樹色靄蒼蒼，霞重嵐深路渺茫。","云實满山無鸟雀，水声沿澗有笙簧。","碧沙洞裏乾坤別，紅樹枝前日月长。","願得花间有人出，免令仙犬吠劉郎。"]', '诗', 'shi', '', NULL, '劉阮洞中遇仙子 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26fa2cba-4c75-4b87-83e5-4f941cc54540', '仙子送劉阮出洞', '仙子送劉阮出洞', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["殷勤相送出天台，仙境那能却再來。","雲液每歸須強飲，玉書無事莫頻開。","花當洞口應長在，水到人間定不迴。","惆悵溪頭從此別，碧山明月閉蒼苔。"]', '["殷勤相送出天台，仙境那能却再来。","云液每归須強饮，玉书無事莫頻开。","花當洞口應长在，水到人间定不迴。","惆悵溪头從此別，碧山明月閉蒼苔。"]', '诗', 'shi', '', NULL, '仙子送劉阮出洞 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b6e597-69ab-48d4-b1e1-ad180c6dcb2a', '仙子洞中有懷劉阮', '仙子洞中有懷劉阮', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["不將清瑟理霓裳，塵夢那知鶴夢長。","洞裏有天春寂寂，人間無路月茫茫。","玉沙瑤草連溪碧，流水桃花滿澗香。","曉露風燈零落盡，此生無處訪劉郎。"]', '["不將清瑟理霓裳，塵梦那知鹤梦长。","洞裏有天春寂寂，人间無路月茫茫。","玉沙瑤草連溪碧，流水桃花满澗香。","晓露风灯零落尽，此生無处訪劉郎。"]', '诗', 'shi', '', NULL, '仙子洞中有懷劉阮 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623e9184-c669-4bad-8a09-96faa95732f1', '劉阮再到天台不復見仙子', '劉阮再到天台不复见仙子', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["再到天台訪玉真，青苔白石已成塵。","笙歌冥寞閑深洞，雲鶴蕭條絕舊隣。","草樹總非前度色，煙霞不似昔年春。","桃花流水依然在，不見當時勸酒人。"]', '["再到天台訪玉真，青苔白石已成塵。","笙歌冥寞闲深洞，云鹤蕭條絕旧隣。","草樹總非前度色，煙霞不似昔年春。","桃花流水依然在，不见當时勸酒人。"]', '诗', 'shi', '', NULL, '劉阮再到天台不復見仙子 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9997089f-74db-4739-9d9a-8e632fc48490', '織女懷牽牛', '织女懷牽牛', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["北斗佳人雙淚流，眼穿腸斷爲牽牛。","封題錦字凝新恨，拋擲金梭織舊愁。","桂樹三春煙漠漠，銀河一水夜悠悠。","欲將心向仙郎說，借問榆花早晚秋。"]', '["北斗佳人雙泪流，眼穿腸斷爲牽牛。","封題錦字凝新恨，拋擲金梭织旧愁。","桂樹三春煙漠漠，銀河一水夜悠悠。","欲將心向仙郎说，借问榆花早晚秋。"]', '诗', 'shi', '', NULL, '織女懷牽牛 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b63980-020d-45a5-b71f-a6d75cd40645', '王遠宴麻姑蔡經宅', '王远宴麻姑蔡經宅', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["好風吹樹杏花香，花下真人道姓王。","大篆龍蛇隨筆札，小天星斗滿衣裳。","閑拋南極歸期晚，笑指東溟飲興長。","要喚麻姑同一醉，使人沽酒向餘杭。"]', '["好风吹樹杏花香，花下真人道姓王。","大篆龙蛇隨笔札，小天星斗满衣裳。","闲拋南極归期晚，笑指东溟饮兴长。","要喚麻姑同一醉，使人沽酒向餘杭。"]', '诗', 'shi', '', NULL, '王遠宴麻姑蔡經宅 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc724846-47d8-4ebe-9b3a-017a1b0b2aeb', '萼綠華將歸九疑留別許真人', '萼綠华將归九疑留別許真人', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["九點秋煙黛色空，綠華歸思頗無窮。","每悲馭鶴身難任，長恨臨霞語未終。","河影暗吹雲夢月，花聲閑落洞庭風。","藍絲重勒金條脫，留與人間許侍中。"]', '["九点秋煙黛色空，綠华归思頗無窮。","每悲馭鹤身难任，长恨臨霞語未終。","河影暗吹云梦月，花声闲落洞庭风。","藍絲重勒金條脫，留與人间許侍中。"]', '诗', 'shi', '', NULL, '萼綠華將歸九疑留別許真人 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd4dfc0-30a5-461e-a773-1e1ae708669b', '穆王宴王母於九光流霞館', '穆王宴王母於九光流霞館', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["桑葉扶疎閉日華，穆王邀命宴流霞。","霓旌著地雲初駐，金奏掀天月欲斜。","歌咽細風吹粉蕊，飲餘清露濕瑤砂。","不知白馬紅韁解，偷喫東田碧玉花。"]', '["桑葉扶疎閉日华，穆王邀命宴流霞。","霓旌著地云初駐，金奏掀天月欲斜。","歌咽細风吹粉蕊，饮餘清露濕瑤砂。","不知白马紅韁解，偷喫东田碧玉花。"]', '诗', 'shi', '', NULL, '穆王宴王母於九光流霞館 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34805ce9-6ec1-4637-9395-1426e04d5f8f', '紫河張休真', '紫河張休真', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["琪樹扶疎壓瑞煙，玉皇朝客滿花前。","山川到處成三月，絲竹經時即萬年。","樹石冥茫初縮地，杯盤狼籍未朝天。","東風小飲人皆醉，從聽黃龍枕水眠。"]', '["琪樹扶疎壓瑞煙，玉皇朝客满花前。","山川到处成三月，絲竹經时即万年。","樹石冥茫初縮地，杯盤狼籍未朝天。","东风小饮人皆醉，從听黄龙枕水眠。"]', '诗', 'shi', '', NULL, '紫河張休真 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6750faf7-0641-4e38-85c7-097e7cdcf93c', '張碩重寄杜蘭香', '張碩重寄杜蘭香', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["碧落香銷蘭露秋，星河無夢夜悠悠。","靈妃不降三清駕，仙鶴空成萬古愁。","浩月隔花追欵別，瑞煙籠樹省淹留。","人間何事堪惆悵，海色西風十二樓。"]', '["碧落香銷蘭露秋，星河無梦夜悠悠。","靈妃不降三清駕，仙鹤空成万古愁。","浩月隔花追欵別，瑞煙籠樹省淹留。","人间何事堪惆悵，海色西风十二楼。"]', '诗', 'shi', '', NULL, '張碩重寄杜蘭香 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f65f20f-056b-4a05-bc38-7b05ce3f428a', '玉女杜蘭香下嫁於張碩', '玉女杜蘭香下嫁於張碩', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["天上人間兩渺茫，不知誰識杜蘭香。","來經玉樹三山遠，去隔銀河一水長。","怨入清塵愁錦瑟，酒傾玄露醉瑤觴。","遺情更說何珍重，擘破雲鬟金鳳皇。"]', '["天上人间兩渺茫，不知誰識杜蘭香。","来經玉樹三山远，去隔銀河一水长。","怨入清塵愁錦瑟，酒傾玄露醉瑤觴。","遺情更说何珍重，擘破云鬟金鳳皇。"]', '诗', 'shi', '', NULL, '玉女杜蘭香下嫁於張碩 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ef6636-167c-4e76-874d-b6011d689809', '蕭史攜弄玉上昇', '蕭史携弄玉上昇', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["豈是丹臺歸路遙，紫鸞煙駕不同飄。","一聲洛水傳幽咽，萬片宮花共寂寥。","紅粉美人愁未散，清華公子笑相邀。","緱山碧樹青樓月，腸斷春風爲玉簫。"]', '["豈是丹台归路遙，紫鸾煙駕不同飄。","一声洛水傳幽咽，万片宮花共寂寥。","紅粉美人愁未散，清华公子笑相邀。","緱山碧樹青楼月，腸斷春风爲玉簫。"]', '诗', 'shi', '', NULL, '蕭史攜弄玉上昇 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db3af61-7f6b-451f-90f2-47c03ff2f7dc', '皇初平將入金華山', '皇初平將入金华山', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["莫道真遊煙景賒，瀟湘有路入京華。","溪頭鶴樹春常在，洞口人家日易斜。","一水暗鳴閑遶澗，五雲長往不還家。","白羊成隊難收拾，喫盡溪邊巨勝花。"]', '["莫道真游煙景賒，瀟湘有路入京华。","溪头鹤樹春常在，洞口人家日易斜。","一水暗鳴闲遶澗，五云长往不還家。","白羊成隊难收拾，喫尽溪邊巨勝花。"]', '诗', 'shi', '', NULL, '皇初平將入金華山 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b38c69-8483-4e41-b359-ceadd408aeb1', '漢武帝思李夫人', '漢武帝思李夫人', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["惆悵冰顏不復歸，晚秋黃葉滿天飛。","迎風細荇傳香粉，隔水殘霞見畫衣。","白玉帳寒鴛夢絕，紫陽宮遠雁書稀。","夜深池上蘭橈歇，斷續歌聲徹太微。"]', '["惆悵冰顏不复归，晚秋黄葉满天飞。","迎风細荇傳香粉，隔水殘霞见畫衣。","白玉帳寒鴛梦絕，紫陽宮远雁书稀。","夜深池上蘭橈歇，斷續歌声徹太微。"]', '诗', 'shi', '', NULL, '漢武帝思李夫人 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0934c60-d894-408e-8b53-614e0ed3412f', '送羽人王錫歸羅浮', '送羽人王錫归羅浮', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["風前整頓紫荷巾，常向羅浮保養神。","石磴倚天行帶月，鐵橋通海入無塵。","龍蛇出洞閑邀雨，犀象眠花不避人。","最愛葛洪尋藥處，露苗煙蕊滿山春。"]', '["风前整頓紫荷巾，常向羅浮保養神。","石磴倚天行带月，鐵橋通海入無塵。","龙蛇出洞闲邀雨，犀象眠花不避人。","最愛葛洪尋藥处，露苗煙蕊满山春。"]', '诗', 'shi', '', NULL, '送羽人王錫歸羅浮 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec81852-3ed9-4e2f-a6b2-8e2dd8d0c1b5', '送劉尊師祗詔闕庭三首 一', '送劉尊師祗詔闕庭三首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海風葉葉駕霓旌，天路悠悠接上清。","錦誥淒涼遺去恨，玉簫哀絕醉離情。","五湖夜月幡幢濕，雙闕清風劒珮輕。","從此暫辭華表柱，便應千載是歸程。"]', '["海风葉葉駕霓旌，天路悠悠接上清。","錦誥淒涼遺去恨，玉簫哀絕醉離情。","五湖夜月幡幢濕，雙闕清风劒珮轻。","從此暫辞华表柱，便應千載是归程。"]', '诗', 'shi', '', NULL, '送劉尊師祗詔闕庭三首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43b7380-4f3b-4b8f-ab2d-1fbfecad43b9', '送劉尊師祗詔闕庭三首 二', '送劉尊師祗詔闕庭三首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["五峰已別隔人間，雙闕何年許再還。","既埽山川收地脉，須留日月駐天顏。","霞觴共飲身雖在，風馭難陪跡未閑。","從此枕中唯有夢，夢魂何處訪三山。"]', '["五峰已別隔人间，雙闕何年許再還。","既埽山川收地脉，須留日月駐天顏。","霞觴共饮身雖在，风馭难陪跡未闲。","從此枕中唯有梦，梦魂何处訪三山。"]', '诗', 'shi', '', NULL, '送劉尊師祗詔闕庭三首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420aa1d7-a1ea-4676-b7d0-a61a08f80293', '送劉尊師祗詔闕庭三首 三', '送劉尊師祗詔闕庭三首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["仙老閑眠碧草堂，帝書徵入白雲鄉。","龜臺欲署長生籍，鸞殿還論不死方。","紅露想傾延命酒，素煙思爇降真香。","五千言外無文字，更有何詞贈武皇。"]', '["仙老闲眠碧草堂，帝书徵入白云乡。","龟台欲署长生籍，鸾殿還論不死方。","紅露想傾延命酒，素煙思爇降真香。","五千言外無文字，更有何词贈武皇。"]', '诗', 'shi', '', NULL, '送劉尊師祗詔闕庭三首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2693a9bf-a0ba-44bd-b308-4de0b9925856', '三年冬大禮五首 一', '三年冬大禮五首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["皇帝齋心潔素誠，自朝真祖報升平。","華山秋草多歸馬，滄海寒波絕洗兵。","銀箭水殘河勢斷，玉爐煙盡日華生。","千官整肅三天夜，劒佩初聞入太清。"]', '["皇帝斋心潔素誠，自朝真祖報升平。","华山秋草多归马，滄海寒波絕洗兵。","銀箭水殘河勢斷，玉爐煙尽日华生。","千官整肅三天夜，劒佩初闻入太清。"]', '诗', 'shi', '', NULL, '三年冬大禮五首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc07ef1-651f-4c45-9125-010ad5982816', '三年冬大禮五首 二', '三年冬大禮五首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海日西飛度禁林，太清宮殿月沉沉。","不聞北斗傾堯酒，空覺南風入舜琴。","歌壓鈞天閑夢盡，詔歸秋水道情深。","雪風更起古杉葉，時送步虛清磬音。"]', '["海日西飞度禁林，太清宮殿月沉沉。","不闻北斗傾堯酒，空覺南风入舜琴。","歌壓鈞天闲梦尽，詔归秋水道情深。","雪风更起古杉葉，时送步虛清磬音。"]', '诗', 'shi', '', NULL, '三年冬大禮五首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e7f2b31-b1e2-4579-a77d-e038dd8512d7', '三年冬大禮五首 三', '三年冬大禮五首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["太一天壇降紫君，屬車龍鶴夜成羣。","春浮玉藻寒初落，露拂金莖曙欲分。","三代樂迴風入律，四溟歌駐水成文。","千官不動旌旗下，日照南山萬樹雲。"]', '["太一天壇降紫君，屬车龙鹤夜成羣。","春浮玉藻寒初落，露拂金莖曙欲分。","三代乐迴风入律，四溟歌駐水成文。","千官不动旌旗下，日照南山万樹云。"]', '诗', 'shi', '', NULL, '三年冬大禮五首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2ac80b-014e-485a-a6d1-0968c1466b39', '三年冬大禮五首 四', '三年冬大禮五首 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["山擁飛雲海水清，天壇未夕仗先成。","千官不起金縢議，萬國空瞻玉藻聲。","禁火曙然煙焰褭，宮衣寒拂雪花輕。","側聞左右皆周呂，看取從容致太平。"]', '["山擁飞云海水清，天壇未夕仗先成。","千官不起金縢議，万国空瞻玉藻声。","禁火曙然煙焰褭，宮衣寒拂雪花轻。","側闻左右皆周呂，看取從容致太平。"]', '诗', 'shi', '', NULL, '三年冬大禮五首 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b618be-e9b4-48aa-8408-f626a6737e7b', '三年冬大禮五首 五', '三年冬大禮五首 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["太和琴暖發南薰，水闊風高得細聞。","滄海舉歌夔是相，歷山迴禪舜爲君。","翠微呼處生丹障，清靜封中起白雲。","今日病身慙小隱，欲將泉石勒移文。"]', '["太和琴暖發南薰，水闊风高得細闻。","滄海舉歌夔是相，歷山迴禪舜爲君。","翠微呼处生丹障，清静封中起白云。","今日病身慙小隐，欲將泉石勒移文。"]', '诗', 'shi', '', NULL, '三年冬大禮五首 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ba5715-a6d7-4ffc-b38b-01fd6c37d1fe', '暮春戲贈吳端公', '暮春戲贈吳端公', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["年少英雄好丈夫，大家望拜執金吾。","閑眠曉日聽鶗鴂，笑倚春風仗轆轤。","深院吹笙聞漢婢，靜街調馬任奚奴。","牡丹花下簾鉤外，獨凭紅肌捋虎鬚。"]', '["年少英雄好丈夫，大家望拜執金吾。","闲眠晓日听鶗鴂，笑倚春风仗轆轤。","深院吹笙闻漢婢，静街調马任奚奴。","牡丹花下簾鉤外，独凭紅肌捋虎鬚。"]', '诗', 'shi', '', NULL, '暮春戲贈吳端公 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0fca6bb-3db4-476d-a052-a47ead7b87ae', '奉送嚴大夫再領容府二首 一', '奉送嚴大夫再領容府二首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海風捲樹凍嵐消，憂國寧辭嶺外遙。","自顧勤勞甘百戰，不將功業負三朝。","劒澄黑水曾芟虎，箭劈黃雲慣射鵰。","代北天南盡成事，肯將心許霍嫖姚。"]', '["海风捲樹凍嵐消，憂国寧辞嶺外遙。","自顧勤勞甘百戰，不將功業負三朝。","劒澄黑水曾芟虎，箭劈黄云慣射鵰。","代北天南尽成事，肯將心許霍嫖姚。"]', '诗', 'shi', '', NULL, '奉送嚴大夫再領容府二首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a6bdae-51a9-4f5a-903a-ac72b298e06e', '奉送嚴大夫再領容府二首 二', '奉送嚴大夫再領容府二首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["日照雙旌射火山，笑迎賓從却南還。","風雲暗發談諧外，感會潛生氣概間。","蘄竹水翻臺榭濕，刺桐花落管弦閑。","無因得靸真珠履，親從新侯定八蠻。"]', '["日照雙旌射火山，笑迎賓從却南還。","风云暗發談諧外，感會潛生氣概间。","蘄竹水翻台榭濕，刺桐花落管弦闲。","無因得靸真珠履，親從新侯定八蠻。"]', '诗', 'shi', '', NULL, '奉送嚴大夫再領容府二首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501d63f0-e30d-4006-9524-c7c013540132', '贈南嶽馮處士二首 一', '贈南嶽馮处士二首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["白石溪邊自結廬，風泉滿院稱幽居。","鳥啼深樹斸靈藥，花落閑窗看道書。","煙嵐晚過鹿裘濕，水月夜明山舍虛。","支頤冷笑緣名出，終日王門強曳裾。"]', '["白石溪邊自結廬，风泉满院稱幽居。","鸟啼深樹斸靈藥，花落闲窗看道书。","煙嵐晚過鹿裘濕，水月夜明山舍虛。","支頤冷笑緣名出，終日王门強曳裾。"]', '诗', 'shi', '', NULL, '贈南嶽馮處士二首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e64c186-49c7-4352-8b70-28c7211aa361', '贈南嶽馮處士二首 二', '贈南嶽馮处士二首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["寂寥深木閉煙霞，洞裏相知有幾家。","笑看潭魚吹水沫，醉嗔溪鹿吃蕉花。","穿廚歷歷泉聲細，繞屋悠悠樹影斜。","夜靜著灰封釜竈，自添文武養丹砂。"]', '["寂寥深木閉煙霞，洞裏相知有幾家。","笑看潭鱼吹水沫，醉嗔溪鹿吃蕉花。","穿廚歷歷泉声細，繞屋悠悠樹影斜。","夜静著灰封釜竈，自添文武養丹砂。"]', '诗', 'shi', '', NULL, '贈南嶽馮處士二首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1811949c-c4d2-4279-b776-b2c87c225331', '題子姪書院雙松', '題子姪书院雙松', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["自種雙松費幾錢，頓令院落似秋天。","能藏此地新晴雨，却惹空山舊燒煙。","枝壓細風過枕上，影籠殘月到窗前。","莫教取次成閑夢，使汝悠悠十八年。"]', '["自種雙松費幾錢，頓令院落似秋天。","能藏此地新晴雨，却惹空山旧燒煙。","枝壓細风過枕上，影籠殘月到窗前。","莫教取次成闲梦，使汝悠悠十八年。"]', '诗', 'shi', '', NULL, '題子姪書院雙松 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb3cdef-69cc-4b4a-94e1-49704bfaa4b8', '羽林賈中丞', '羽林賈中丞', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["四十年前百戰身，曾驅虎隊掃胡塵。","風悲鼓角榆關暮，日暖旌旗隴草春。","鐵馬慣牽邀上客，金魚多解乞佳人。","胸中別有安邊計，誰睬髭鬚白似銀。"]', '["四十年前百戰身，曾驱虎隊掃胡塵。","风悲鼓角榆关暮，日暖旌旗隴草春。","鐵马慣牽邀上客，金鱼多解乞佳人。","胸中別有安邊計，誰睬髭鬚白似銀。"]', '诗', 'shi', '', NULL, '羽林賈中丞 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ff95f0-d92f-4414-a409-46cb0d088510', '送康祭酒赴輪臺', '送康祭酒赴輪台', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["灞水橋邊酒一杯，送君千里赴輪臺。","霜黏海眼旗聲凍，風射犀文甲縫開。","斷磧簇煙山似米，野營軒地鼓如雷。","分明會得將軍意，不斬樓蘭不擬迴。"]', '["灞水橋邊酒一杯，送君千里赴輪台。","霜黏海眼旗声凍，风射犀文甲縫开。","斷磧簇煙山似米，野營軒地鼓如雷。","分明會得將軍意，不斬楼蘭不擬迴。"]', '诗', 'shi', '', NULL, '送康祭酒赴輪臺 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39e7275-e294-410f-a36d-e848290d9d27', '南遊', '南游', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["盡興南遊卒未迴，水工舟子不須催。","政思碧樹關心句，難放紅螺蘸甲杯。","漲海潮生陰火滅，蒼梧風暖瘴雲開。"]', '["尽兴南游卒未迴，水工舟子不須催。","政思碧樹关心句，难放紅螺蘸甲杯。","漲海潮生陰火滅，蒼梧风暖瘴云开。"]', '诗', 'shi', '', NULL, '南遊 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cefbdf8b-9dda-4024-8d4c-0b51d8f82379', '哭陷邊許兵馬使', '哭陷邊許兵马使', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["北風裂地黯邊霜，戰敗桑乾日色黃。","故國暗迴殘士卒，新墳空葬舊衣裳。","散牽細馬嘶青草，任去佳人弔白楊。","除却陰符與兵法，更無一物在儀牀。"]', '["北风裂地黯邊霜，戰敗桑乾日色黄。","故国暗迴殘士卒，新墳空葬旧衣裳。","散牽細马嘶青草，任去佳人弔白楊。","除却陰符與兵法，更無一物在儀牀。"]', '诗', 'shi', '', NULL, '哭陷邊許兵馬使 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a963f58e-ac9f-498d-96fb-6e15ec249d80', '和周侍御買劍', '和周侍御買劍', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["將軍溢價買吳鉤，要與中原靜寇讐。","試挂窗前驚電轉，略拋牀下怕泉流。","青天露拔雲霓泣，黑地潛擎鬼魅愁。","見說夜深星斗畔，等閑期尅月支頭。"]', '["將軍溢價買吳鉤，要與中原静寇讐。","試挂窗前驚電轉，略拋牀下怕泉流。","青天露拔云霓泣，黑地潛擎鬼魅愁。","见说夜深星斗畔，等闲期尅月支头。"]', '诗', 'shi', '', NULL, '和周侍御買劍 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7edff69-936c-44c3-8d2e-15217629e066', '病馬五首呈鄭校書章三吳十五先輩 一', '病马五首呈鄭校书章三吳十五先輩 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["騄駬何年別渥洼。","病來顏色半泥沙，四蹄不鑿金砧裂。","雙眼慵開玉筯斜，墮月兔毛乾觳𧥆。","失雲龍骨瘦牙槎，平原好放無人放。","嘶向秋風苜蓿花。"]', '["騄駬何年別渥洼。","病来顏色半泥沙，四蹄不鑿金砧裂。","雙眼慵开玉筯斜，墮月兔毛乾觳𧥆。","失云龙骨瘦牙槎，平原好放無人放。","嘶向秋风苜蓿花。"]', '诗', 'shi', '', NULL, '病馬五首呈鄭校書章三吳十五先輩 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5710a187-8b53-40fe-87be-4e5633d8712f', '病馬五首呈鄭校書章三吳十五先輩 二', '病马五首呈鄭校书章三吳十五先輩 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["隴上沙蔥葉正齊，騰黃猶自跼羸蹄。","尾蟠夜雨紅絲脆，頭捽秋風白練低。","力憊未思金絡腦，影寒空望錦障泥。","階前莫怪垂雙淚，不遇孫陽不敢嘶。"]', '["隴上沙蔥葉正齊，腾黄猶自跼羸蹄。","尾蟠夜雨紅絲脆，头捽秋风白練低。","力憊未思金絡腦，影寒空望錦障泥。","階前莫怪垂雙泪，不遇孫陽不敢嘶。"]', '诗', 'shi', '', NULL, '病馬五首呈鄭校書章三吳十五先輩 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25131a88-021a-4321-82ed-b8612738959c', '病馬五首呈鄭校書章三吳十五先輩 三', '病马五首呈鄭校书章三吳十五先輩 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["不剪焦毛鬣半翻，何人別是古龍孫。","霜侵病骨無驕氣，土蝕驄花見臥痕。","未噴斷雲歸漢苑，曾追輕練過吳門。","一朝千里心猶在，爭肯潛忘秣飼恩。"]', '["不剪焦毛鬣半翻，何人別是古龙孫。","霜侵病骨無驕氣，土蝕驄花见臥痕。","未噴斷云归漢苑，曾追轻練過吳门。","一朝千里心猶在，爭肯潛忘秣飼恩。"]', '诗', 'shi', '', NULL, '病馬五首呈鄭校書章三吳十五先輩 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d40daf0a-349c-428f-a8d5-d292ca483ef2', '病馬五首呈鄭校書章三吳十五先輩 四', '病马五首呈鄭校书章三吳十五先輩 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["空被秋風吹病毛，無因濯浪刷洪濤。","臥來總怪龍蹄跙，瘦盡誰驚虎口高。","追電有心猶欵段，逢人相骨強嘶號。","欲將鬐鬣重裁剪，乞借新成利鉸刀。"]', '["空被秋风吹病毛，無因濯浪刷洪濤。","臥来總怪龙蹄跙，瘦尽誰驚虎口高。","追電有心猶欵段，逢人相骨強嘶號。","欲將鬐鬣重裁剪，乞借新成利鉸刀。"]', '诗', 'shi', '', NULL, '病馬五首呈鄭校書章三吳十五先輩 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69ac559f-09b2-47c1-80e3-9aa78c7966ae', '病馬五首呈鄭校書章三吳十五先輩 五', '病马五首呈鄭校书章三吳十五先輩 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["病久無人著意看，玉華衫色欲凋殘。","飲驚白露泉花冷，喫怕清秋荳葉寒。","長襜敢辭紅錦重，舊韁寧畏紫絲蟠。","王良若許相擡策，千里追風也不難。"]', '["病久無人著意看，玉华衫色欲凋殘。","饮驚白露泉花冷，喫怕清秋荳葉寒。","长襜敢辞紅錦重，旧韁寧畏紫絲蟠。","王良若許相擡策，千里追风也不难。"]', '诗', 'shi', '', NULL, '病馬五首呈鄭校書章三吳十五先輩 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15dbfa5b-036e-4af5-be46-14c2bf2adb1d', '長安客舍敘邵陵舊宴寄永州蕭使君五首 一', '长安客舍敘邵陵旧宴寄永州蕭使君五首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["邵陵佳樹碧蔥蘢，河漢西沈宴未終。","殘漏五更傳海月，清笳三會揭天風。","香熏舞席雲鬟綠，光射頭盤蠟燭紅。","今日却懷行樂處，兩床絲竹水樓中。"]', '["邵陵佳樹碧蔥蘢，河漢西沈宴未終。","殘漏五更傳海月，清笳三會揭天风。","香熏舞席云鬟綠，光射头盤蠟燭紅。","今日却懷行乐处，兩床絲竹水楼中。"]', '诗', 'shi', '', NULL, '長安客舍敘邵陵舊宴寄永州蕭使君五首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b1913e9-9086-4d5d-a4a9-096b2a4917ac', '長安客舍敘邵陵舊宴寄永州蕭使君五首 二', '长安客舍敘邵陵旧宴寄永州蕭使君五首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["不知何路却飛翻，虛受賢侯鄭重恩。","五夜清歌敲玉樹，三年洪飲倒金尊。","招攜永感雙魚在，報荅空知一劒存。","狼籍棃花滿城月，當時長醉信陵門。"]', '["不知何路却飞翻，虛受賢侯鄭重恩。","五夜清歌敲玉樹，三年洪饮倒金尊。","招携永感雙鱼在，報荅空知一劒存。","狼籍棃花满城月，當时长醉信陵门。"]', '诗', 'shi', '', NULL, '長安客舍敘邵陵舊宴寄永州蕭使君五首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c30c2cb-23be-4dc8-8b40-902f121c1864', '長安客舍敘邵陵舊宴寄永州蕭使君五首 三', '长安客舍敘邵陵旧宴寄永州蕭使君五首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["粉堞彤軒畫障西，水雲紅樹窣璇題。","鷓鴣欲絕歌聲定，鸜鵒初驚舞袖齊。","坐對玉山空甸線，細聽金石怕低迷。","東風夜月三年飲，不省非時不似泥。"]', '["粉堞彤軒畫障西，水云紅樹窣璇題。","鷓鴣欲絕歌声定，鸜鵒初驚舞袖齊。","坐对玉山空甸線，細听金石怕低迷。","东风夜月三年饮，不省非时不似泥。"]', '诗', 'shi', '', NULL, '長安客舍敘邵陵舊宴寄永州蕭使君五首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe929876-6e1c-4a62-891c-9c302a5154ee', '長安客舍敘邵陵舊宴寄永州蕭使君五首 四', '长安客舍敘邵陵旧宴寄永州蕭使君五首 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["木魚金鑰鎖春城，夜上紅樓縱酒情。","竹葉水繁更漏促，桐花風軟管弦清。","百分散打銀船溢，十指寬催玉筯輕。","星斗漸稀賓客散，碧雲猶戀豔歌聲。"]', '["木鱼金鑰鎖春城，夜上紅楼縱酒情。","竹葉水繁更漏促，桐花风軟管弦清。","百分散打銀船溢，十指寬催玉筯轻。","星斗漸稀賓客散，碧云猶戀豔歌声。"]', '诗', 'shi', '', NULL, '長安客舍敘邵陵舊宴寄永州蕭使君五首 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975f674b-37c5-4e60-9974-cd0c7e2e2ce5', '長安客舍敘邵陵舊宴寄永州蕭使君五首 五', '长安客舍敘邵陵旧宴寄永州蕭使君五首 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["三年身逐漢諸侯，賓榻容居最上頭。","飽聽笙歌陪痛飲，熟尋雲水縱閑遊。","朱門鎖閉煙嵐暮，鈴閣清冷水木秋。","月滿前山圓不動，更邀詩客上高樓。"]', '["三年身逐漢諸侯，賓榻容居最上头。","飽听笙歌陪痛饮，熟尋云水縱闲游。","朱门鎖閉煙嵐暮，鈴閣清冷水木秋。","月满前山圓不动，更邀诗客上高楼。"]', '诗', 'shi', '', NULL, '長安客舍敘邵陵舊宴寄永州蕭使君五首 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1f27bd-d0da-43d9-adb3-c33c9c9b02c7', '勗劒', '勗劒', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["古物神光雪見羞，未能擎出恐泉流。","暗臨黑水蛟螭泣，潛倚空山鬼魅愁。","生怕雷霆號澗底，長聞風雨在牀頭。","垂情不用將閑氣，惱亂司空犯斗牛。"]', '["古物神光雪见羞，未能擎出恐泉流。","暗臨黑水蛟螭泣，潛倚空山鬼魅愁。","生怕雷霆號澗底，长闻风雨在牀头。","垂情不用將闲氣，惱亂司空犯斗牛。"]', '诗', 'shi', '', NULL, '勗劒 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a973a52b-b7e5-4c37-b247-c1d7a89a43b2', '仙都即景', '仙都即景', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["蟠桃花老華陽東，軒后登真謝六宮。","旌節暗迎歸碧落，笙歌遙聽隔崆峒。","衣冠留葬橋山月，劒履將隨浪海風。","看却龍髯攀不得，紅霞零落鼎湖空。"]', '["蟠桃花老华陽东，軒后登真謝六宮。","旌節暗迎归碧落，笙歌遙听隔崆峒。","衣冠留葬橋山月，劒履將隨浪海风。","看却龙髯攀不得，紅霞零落鼎湖空。"]', '诗', 'shi', '', NULL, '仙都即景 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13227c7a-3367-4bdc-a362-094c8ff6e94b', '望九華寄池陽杜員外', '望九华寄池陽杜員外', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["戴月早辭三秀館，遲明初識九華峰。","差差玉劒寒鋩利，褭褭青蓮翠葉重。","奇狀却疑人畫出，嵐光如爲客添濃。","行春若到五溪上，此處褰帷正面逢。"]', '["戴月早辞三秀館，遲明初識九华峰。","差差玉劒寒鋩利，褭褭青蓮翠葉重。","奇狀却疑人畫出，嵐光如爲客添濃。","行春若到五溪上，此处褰帷正面逢。"]', '诗', 'shi', '', NULL, '望九華寄池陽杜員外 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b1ade71-4a27-4fdf-9956-d72894160f51', '小遊仙詩九十八首 一', '小游仙诗九十八首 一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玉簫金瑟發商聲，桑葉枯乾海水清。","淨埽蓬萊山下路，略邀王母話長生。"]', '["玉簫金瑟發商声，桑葉枯乾海水清。","淨埽蓬萊山下路，略邀王母話长生。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baeafdd-69f2-46c2-933a-8ce96b2502cc', '小遊仙詩九十八首 二', '小游仙诗九十八首 二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["上元元日豁明堂，五帝望空拜玉皇。","萬樹琪花千圃藥，心知不敢輒形相。"]', '["上元元日豁明堂，五帝望空拜玉皇。","万樹琪花千圃藥，心知不敢輒形相。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d064aaeb-2832-4d34-b7cf-2cb9b2d967ca', '小遊仙詩九十八首 三', '小游仙诗九十八首 三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["騎龍重過玉溪頭，紅葉還春碧水流。","省得壺中見天地，壺中天地不曾秋。"]', '["騎龙重過玉溪头，紅葉還春碧水流。","省得壺中见天地，壺中天地不曾秋。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b259d59b-4adc-470b-b561-cc2ea4231800', '小遊仙詩九十八首 四', '小游仙诗九十八首 四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["真王未許久從容，立在花前別甯封。","手把玉簫頭不舉，自愁如醉倚黃龍。"]', '["真王未許久從容，立在花前別甯封。","手把玉簫头不舉，自愁如醉倚黄龙。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8c29bd-15b1-4875-9eb6-d3309884efe6', '小遊仙詩九十八首 五', '小游仙诗九十八首 五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["金殿無人鏁絳煙，玉郎並不賞丹田。","白龍蹀躞難迴跋，爭下紅綃碧玉鞭。"]', '["金殿無人鏁絳煙，玉郎並不賞丹田。","白龙蹀躞难迴跋，爭下紅綃碧玉鞭。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1499d3-f9ec-4820-8dd3-2fc40129d692', '小遊仙詩九十八首 六', '小游仙诗九十八首 六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玄洲草木不知黃，甲子初開浩劫長。","無限萬年年少女，手攀紅樹滿殘陽。"]', '["玄洲草木不知黄，甲子初开浩劫长。","無限万年年少女，手攀紅樹满殘陽。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('730d3e9d-6128-4ab0-9357-99bd7463bab4', '小遊仙詩九十八首 七', '小游仙诗九十八首 七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["宮闕重重閉玉林，崑崙高闢彩雲深。","黄龍掉尾引郎去，使妾月眀何處尋。"]', '["宮闕重重閉玉林，崑崙高闢彩云深。","黄龙掉尾引郎去，使妾月眀何处尋。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c25f6713-1db4-410c-9567-47f7d6a74c5f', '小遊仙詩九十八首 八', '小游仙诗九十八首 八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["風滿塗山玉蕊稀，赤龍閑臥鶴東飛。","紫棃爛盡無人喫，何事韓君去不歸。"]', '["风满塗山玉蕊稀，赤龙闲臥鹤东飞。","紫棃爛尽無人喫，何事韓君去不归。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e980d63-2a35-436d-bcc9-0deb97bfd097', '小遊仙詩九十八首 九', '小游仙诗九十八首 九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["武帝徒勞厭暮年，不曾清淨不精專。","上元少女絕還往，滿竈丹成白玉煙。"]', '["武帝徒勞厭暮年，不曾清淨不精專。","上元少女絕還往，满竈丹成白玉煙。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02db2c92-3745-4d56-86b6-5482956b8541', '小遊仙詩九十八首 十', '小游仙诗九十八首 十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["百辟朝回閉玉除，露風清宴桂花疎。","西歸使者騎金虎，嚲鞚垂鞭唱步虛。"]', '["百辟朝回閉玉除，露风清宴桂花疎。","西归使者騎金虎，嚲鞚垂鞭唱步虛。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399a4873-ea86-43e3-b82f-1c86e1fdd1d4', '小遊仙詩九十八首 十一', '小游仙诗九十八首 十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["南斗闌珊北斗稀，茅君夜著紫霞衣。","朝騎白鹿趁朝去，鳳押笙歌逐後飛。"]', '["南斗闌珊北斗稀，茅君夜著紫霞衣。","朝騎白鹿趁朝去，鳳押笙歌逐後飞。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c6faaa-3e91-4a4b-a503-89971a034fe7', '小遊仙詩九十八首 十二', '小游仙诗九十八首 十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["焚香獨自上天壇，桂樹風吹玉簡寒。","長怕嵇康乏僊骨，與將僊籍再尋看。"]', '["焚香独自上天壇，桂樹风吹玉簡寒。","长怕嵇康乏僊骨，與將僊籍再尋看。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08884bd9-1832-48a3-ab03-376eb0234672', '小遊仙詩九十八首 十三', '小游仙诗九十八首 十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["冰屋朱扉曉未開，誰將金策扣瓊臺。","碧花紅尾小僊犬，閑吠五雲嗔客來。"]', '["冰屋朱扉晓未开，誰將金策扣瓊台。","碧花紅尾小僊犬，闲吠五云嗔客来。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f90606-fbbc-425c-8364-53f29dfa8cd3', '小遊仙詩九十八首 十四', '小游仙诗九十八首 十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["酒釅春濃瓊草齊，真公飲散醉如泥。","朱輪軋軋入雲去，行到半天聞馬嘶。"]', '["酒釅春濃瓊草齊，真公饮散醉如泥。","朱輪軋軋入云去，行到半天闻马嘶。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab077cee-5726-42f6-a888-6d46b8b15078', '小遊仙詩九十八首 十五', '小游仙诗九十八首 十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["白石山中自有天，竹花藤葉隔溪煙。","朝來洞口圍碁了，賭得青龍直幾錢。"]', '["白石山中自有天，竹花藤葉隔溪煙。","朝来洞口圍碁了，賭得青龙直幾錢。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f3c7a7-adc7-4757-9cfd-ea1f20128959', '小遊仙詩九十八首 十六', '小游仙诗九十八首 十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["海水西飛照柏林，青雲斜倚錦雲深。","水風暗入古山葉，吹斷步虛清磬音。"]', '["海水西飞照柏林，青云斜倚錦云深。","水风暗入古山葉，吹斷步虛清磬音。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ca2871-c1e9-4956-9187-830d37b1399e', '小遊仙詩九十八首 十七', '小游仙诗九十八首 十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玉詔新除沈侍郎，便分茅土鎮東方。","不知今夕游何處，侍從皆騎白鳳凰。"]', '["玉詔新除沈侍郎，便分茅土鎮东方。","不知今夕游何处，侍從皆騎白鳳凰。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698e79de-d181-44ba-b407-a875130650af', '小遊仙詩九十八首 十八', '小游仙诗九十八首 十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["洞裏煙霞無歇時，洞中天地足金芝。","月明朗朗溪頭樹，白髮老人相對棊。"]', '["洞裏煙霞無歇时，洞中天地足金芝。","月明朗朗溪头樹，白髮老人相对棊。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6506ffd-fea9-46dd-ad19-0fc99023a3db', '小遊仙詩九十八首 十九', '小游仙诗九十八首 十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["飢即餐霞悶即行，一聲長嘯萬山青。","穿花渡水來相訪，珍重多才阮步兵。"]', '["飢即餐霞悶即行，一声长嘯万山青。","穿花渡水来相訪，珍重多才阮步兵。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f272c7e0-719f-4c40-9c48-b1a38f5c13be', '小遊仙詩九十八首 二十', '小游仙诗九十八首 二十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["東妃閑著翠霞裙，自領笙歌出五雲。","清思密談誰第一，不過邀取小茅君。"]', '["东妃闲著翠霞裙，自領笙歌出五云。","清思密談誰第一，不過邀取小茅君。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fede091-6a7f-4bba-92bc-fde38ab07b0a', '小遊仙詩九十八首 二十一', '小游仙诗九十八首 二十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["月影悠悠秋樹明，露吹犀簟象牀輕。","嬪妃久立帳門外，暗笑夫人推酒聲。"]', '["月影悠悠秋樹明，露吹犀簟象牀轻。","嬪妃久立帳门外，暗笑夫人推酒声。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57330ac-3d46-4d64-b3c9-95b2f3f80838', '小遊仙詩九十八首 二十二', '小游仙诗九十八首 二十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["九天天路入雲長，燕使何由到上方。","玉女暗來花下立，手挼裙帶問昭王。"]', '["九天天路入云长，燕使何由到上方。","玉女暗来花下立，手挼裙带问昭王。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5682d0fe-9c5e-4f3e-8eab-019e8bc35607', '小遊仙詩九十八首 二十三', '小游仙诗九十八首 二十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玉皇賜妾紫衣裳，教向桃源嫁阮郎。","爛煮瓊花勸君喫，恐君毛鬢暗成霜。"]', '["玉皇賜妾紫衣裳，教向桃源嫁阮郎。","爛煮瓊花勸君喫，恐君毛鬢暗成霜。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9fd3a8-6222-41fb-967f-1073d97d5d42', '小遊仙詩九十八首 二十四', '小游仙诗九十八首 二十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["花底休傾綠玉巵，雲中含笑向安期。","窮陽有數不知數，大似人間年少兒。"]', '["花底休傾綠玉巵，云中含笑向安期。","窮陽有數不知數，大似人间年少兒。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2adb16a0-ab53-4730-8f5a-32a05038347d', '小遊仙詩九十八首 二十五', '小游仙诗九十八首 二十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["玉色雌龍金絡頭，真妃騎出縱閑遊。","崑崙山上桃花底，一曲商歌天地秋。"]', '["玉色雌龙金絡头，真妃騎出縱闲游。","崑崙山上桃花底，一曲商歌天地秋。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f138f395-d02f-423f-a9a8-f009e4dac3c5', '小遊仙詩九十八首 二十六', '小游仙诗九十八首 二十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["偷來洞口訪劉君，緩步輕擡玉線裙。","細擘桃花逐流水，更無言語倚彤雲。"]', '["偷来洞口訪劉君，緩步轻擡玉線裙。","細擘桃花逐流水，更無言語倚彤云。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc9e6bc-732f-4af0-a93e-81438f68bb36', '小遊仙詩九十八首 二十七', '小游仙诗九十八首 二十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["西漢夫人下太虛，九霞裙幅五雲輿。","欲將碧字相教示，自解盤囊出素書。"]', '["西漢夫人下太虛，九霞裙幅五云輿。","欲將碧字相教示，自解盤囊出素书。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3969ff55-3d21-4e5d-a3ae-398bf730122f', '小遊仙詩九十八首 二十八', '小游仙诗九十八首 二十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["天上雞鳴海日紅，青腰侍女掃朱宮。","洗花蒸葉濾清酒，待與夫人邀五翁。"]', '["天上雞鳴海日紅，青腰侍女掃朱宮。","洗花蒸葉濾清酒，待與夫人邀五翁。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十八 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c22cc759-e53c-43fe-a887-373ba46ff76d', '小遊仙詩九十八首 二十九', '小游仙诗九十八首 二十九', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["汗漫真遊實可奇，人間天上幾人知。","周王不信長生話，空使萇弘碧淚垂。"]', '["汗漫真游實可奇，人间天上幾人知。","周王不信长生話，空使萇弘碧泪垂。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 二十九 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe187100-d31e-4d06-9dc1-1fac91b98b9f', '小遊仙詩九十八首 三十', '小游仙诗九十八首 三十', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["青錦縫裳綠玉璫，滿身新帶五雲香。","閑依碧海攀鸞駕，笑就蘇君覓橘嘗。"]', '["青錦縫裳綠玉璫，满身新带五云香。","闲依碧海攀鸾駕，笑就蘇君覓橘嘗。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f39ea99f-85ac-4066-bd9a-381d8ebf5f4a', '小遊仙詩九十八首 三十一', '小游仙诗九十八首 三十一', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["鶴不西飛龍不行，露乾雲破洞簫清。","少年僊子說閑事，遙隔彩雲聞笑聲。"]', '["鹤不西飞龙不行，露乾云破洞簫清。","少年僊子说闲事，遙隔彩云闻笑声。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十一 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e7aba02-9a8a-4ac5-bc65-0f241b1f9255', '小遊仙詩九十八首 三十二', '小游仙诗九十八首 三十二', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["洞裏煙深木葉麤，乘風使者降玄都。","隔花相見遙相賀，擎出懷中赤玉符。"]', '["洞裏煙深木葉麤，乘风使者降玄都。","隔花相见遙相賀，擎出懷中赤玉符。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十二 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df1c99a-5453-4561-856a-2d7fbdf3dc40', '小遊仙詩九十八首 三十三', '小游仙诗九十八首 三十三', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["芝蕙芸花爛漫春，瑞香煙露濕衣巾。","玉童私地誇書札，偷寫雲謠暗贈人。"]', '["芝蕙芸花爛漫春，瑞香煙露濕衣巾。","玉童私地誇书札，偷寫云謠暗贈人。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十三 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a101806a-f602-46be-ac4f-c06fd32c72cd', '小遊仙詩九十八首 三十四', '小游仙诗九十八首 三十四', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["天上邀來不肯來，人間雙鶴又空回。","秦皇漢武死何處，海畔紅桑花自開。"]', '["天上邀来不肯来，人间雙鹤又空回。","秦皇漢武死何处，海畔紅桑花自开。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十四 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d58863-d49f-4f1a-b79f-d21204c5e8bd', '小遊仙詩九十八首 三十五', '小游仙诗九十八首 三十五', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["紫羽麾幢下玉京，却邀真母入三清。","白龍久住渾相戀，斜倚祥雲不肯行。"]', '["紫羽麾幢下玉京，却邀真母入三清。","白龙久住渾相戀，斜倚祥云不肯行。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十五 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f4a8c1-2270-4201-afb7-f94b2fad00f6', '小遊仙詩九十八首 三十六', '小游仙诗九十八首 三十六', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["鶴叫風悲竹葉疎，誰來五嶺拜雲車。","人間肉馬無輕步，踏破先生一卷書。"]', '["鹤叫风悲竹葉疎，誰来五嶺拜云车。","人间肉马無轻步，踏破先生一卷书。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十六 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6bb498d-c6e4-422b-b291-321326ab877e', '小遊仙詩九十八首 三十七', '小游仙诗九十八首 三十七', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["夜降西壇宴已終，花殘月榭霧朦朧。","誰遊八海門前過，空洞一聲風雨中。"]', '["夜降西壇宴已終，花殘月榭霧朦朧。","誰游八海门前過，空洞一声风雨中。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十七 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d5f2f0-c40e-4c0b-8e3c-f02ab9840812', '小遊仙詩九十八首 三十八', '小游仙诗九十八首 三十八', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["忘却教人鎖後宮，還丹失盡玉壺空。","嫦娥若不偷靈藥，爭得長生在月中。"]', '["忘却教人鎖後宮，還丹失尽玉壺空。","嫦娥若不偷靈藥，爭得长生在月中。"]', '诗', 'shi', '', NULL, '小遊仙詩九十八首 三十八 曹唐 shi');
